def _leader_chat_intent_card_blocker(embedded_card: object, payload: dict[str, object]) -> str | None:
    if embedded_card == "dispatch_preview_card":
        dispatch_preview_card = payload.get("dispatch_preview_card")
        blocker = dispatch_preview_card.get("blocker") if isinstance(dispatch_preview_card, dict) else None
        return str(blocker) if blocker else None
    if embedded_card == "dispatch_batch_preview_card":
        dispatch_batch_preview_card = payload.get("dispatch_batch_preview_card")
        if isinstance(dispatch_batch_preview_card, dict) and not dispatch_batch_preview_card.get("ready_count"):
            return "no ready approvals to dispatch"
    if embedded_card == "provider_health":
        provider_health = payload.get("provider_health")
        controls = provider_health.get("controls") if isinstance(provider_health, dict) else None
        if isinstance(controls, list):
            for control in controls:
                if isinstance(control, dict) and control.get("command") == payload.get("next_command"):
                    blocker = control.get("blocker")
                    return str(blocker) if blocker else None
    if embedded_card == "run_loop_preview_card":
        card = payload.get("run_loop_preview_card")
        blocker = card.get("blocker") if isinstance(card, dict) else None
        return str(blocker) if blocker else None
    return None


def _reject_negative_interval(args: argparse.Namespace, command: str) -> bool:
    """Refuse a negative `--interval`; return True when the refusal was printed.

    Single source for all eight entry points that accept `--interval`
    (`run-loop --follow`, `goal preview`, `goal start`, `run-loop-host start`,
    `run-loop-host serve`, `workbench --watch`, `dashboard --watch`,
    `boxes watch`).

    Why this is a safety gate and not merely input hygiene: every consumer
    guards the sleep with `if interval > 0: time.sleep(...)`, so a negative
    interval silently means "never sleep". The wave budget is a *bound* the
    human reads as wall-clock walk-away time --
    `run-loop-host start --confirm --max-waves 300 --interval -5` looks like
    "300 waves over ~8 hours" and would actually burn all 300 waves as fast as
    the machine allows, hammering providers and tmux. `goal preview` also
    prints the interval on its confirmation screen ("每 10s 一轮"), so a
    nonsense value there is a displayed fact that does not hold.

    Zero stays legal: it means "no sleep between waves", it is explicit, and it
    is visible in the preview. Only negative is nonsense that silently behaves
    like zero. Callers must invoke this before any mutation or spawn, so a
    refusal is zero-write / zero-spawn.
    """
    interval = getattr(args, "interval", None)
    if interval is None:
        return False
    if interval < 0:
        print(f"{command} requires --interval >= 0", file=sys.stderr)
        return True
    return False


def _project_view_payload_or_error(config: ProjectConfig, store: StateStore) -> dict[str, object] | None:
    payload = asdict(store.project_view(config))
    validation = validate_project_view_contract(payload)
    if not validation["ok"]:
        print("ProjectView contract validation failed", file=sys.stderr)
        for error in validation["errors"]:
            print(f"- {error}", file=sys.stderr)
        return None
    return payload


def _print_leader_chat_payload_or_error(
    payload: dict[str, object],
    store: StateStore,
    *,
    task: str,
) -> int:
    payload.setdefault("capability_card", None)
    payload.setdefault("control_registry_card", None)
    payload.setdefault("control_mode_card", None)
    payload.setdefault("provider_health", None)
    payload.setdefault("frontdesk_card", None)
    payload.setdefault("leader_status_card", None)
    payload.setdefault("learning_review_card", None)
    payload.setdefault("skill_context_card", None)
    payload.setdefault("skill_import_preview_card", None)
    payload.setdefault("skill_load_preview_card", None)
    payload.setdefault("skill_create_preview_card", None)
    payload.setdefault("skill_suggestions_card", None)
    payload.setdefault("memory_context_card", None)
    payload.setdefault("memory_apply_preview_card", None)
    payload.setdefault("memory_suggestions_card", None)
    payload.setdefault("lineage_card", None)
    payload.setdefault("audit_card", None)
    payload.setdefault("artifacts_card", None)
    payload.setdefault("trace_card", None)
    payload.setdefault("capture_card", None)
    payload.setdefault("terminal_card", None)
    payload.setdefault("terminal_session_card", None)
    payload.setdefault("dispatch_preview_card", None)
    payload.setdefault("dispatch_batch_preview_card", None)
    payload.setdefault("runtime_action_card", None)
    payload.setdefault("startup_preview_card", None)
    payload.setdefault("provider_setup_card", None)
    payload.setdefault("provider_switch_card", None)
    payload.setdefault("agent_ready_card", None)
    payload.setdefault("leader_summary_card", None)
    payload.setdefault("review_gate_card", None)
    payload.setdefault("release_preview_card", None)
    payload.setdefault("role_topology_card", None)
    payload.setdefault("run_start_card", None)
    payload.setdefault("run_progress_card", None)
    payload.setdefault("plan_board_card", None)
    payload.setdefault("skills_catalog_card", None)
    payload.setdefault("run_loop_preview_card", None)
    payload.setdefault("mission_preview_card", None)
    payload.setdefault("mission_status_card", None)
    payload.setdefault("mission_run_card", None)
    leader_action = payload.get("leader_action")
    payload.setdefault(
        "leader_action_card",
        leader_chat_action_card(leader_action) if isinstance(leader_action, dict) else None,
    )
    payload.setdefault("intent_card", _leader_chat_intent_card(payload))
    validation = validate_leader_chat_contract(payload)
    if not validation["ok"]:
        error = "; ".join(str(item) for item in validation["errors"])
        mode = str(payload.get("mode", "chat"))
        record = store.record_leader_error(mode, "agentdeck-contract", None, task, error)
        store.append_event(
            EventRecord.create(
                "leader_chat_contract_failed",
                {
                    "error_id": record["error_id"],
                    "mode": mode,
                    "message_length": len(task),
                    "error_count": len(validation["errors"]),
                },
            )
        )
        print("Leader chat contract validation failed", file=sys.stderr)
        for error in validation["errors"]:
            print(f"- {error}", file=sys.stderr)
        return 1
    _print_json(payload)
    return 0


def doctor_command(_args: argparse.Namespace) -> int:
    root = project_root()
    tmux = TmuxBackend().doctor()
    config_exists = config_path(root).exists()
    config = load_config(root) if config_exists else None
    deepseek = DeepSeekProvider().doctor()
    openai_compatible = OpenAICompatibleProvider().doctor()
    configured_leader = _doctor_configured_leader(config)
    leader_ready = bool(configured_leader.get("ready")) if configured_leader else False
    ok = tmux.ok and config_exists and leader_ready
    _print_json(
        {
            "ok": ok,
            "doctor_command": "agentdeck doctor",
            "root": str(root),
            "config_exists": config_exists,
            "config_path": str(config_path(root)),
            "tmux": asdict(tmux),
            "configured_leader": configured_leader,
            "deepseek": _doctor_api_provider_check("deepseek", deepseek),
            "openai_compatible": _doctor_api_provider_check("openai-compatible", openai_compatible),
            "codex_cli": _doctor_cli_provider_check("codex-cli"),
            "claude_cli": _doctor_cli_provider_check("claude-cli"),
        }
    )
    return 0 if ok else 1


def _doctor_api_provider_check(provider: str, doctor_result: tuple[bool, str]) -> dict[str, object]:
    return {
        "ok": doctor_result[0],
        "detail": doctor_result[1],
        "provider_backend": leader_provider_backend(provider),
        "provider_transport": leader_provider_transport(provider),
        "command_path": None,
        "setup_commands": _provider_setup_commands(provider),
    }


def _doctor_cli_provider_check(provider: str) -> dict[str, object]:
    command = {
        "codex-cli": "codex",
        "claude-cli": "claude",
    }[provider]
    command_path = _command_path(command)
    return {
        "ok": command_path is not None,
        "detail": f"{command} is available" if command_path else f"{command} is not found on PATH",
        "provider_backend": leader_provider_backend(provider),
        "provider_transport": leader_provider_transport(provider),
        "command_path": command_path,
        "setup_commands": _provider_setup_commands(provider),
    }


def _doctor_configured_leader(config: ProjectConfig | None) -> dict[str, object] | None:
    if config is None:
        return None
    return _leader_provider_readiness(
        agent_id=config.leader.agent_id,
        provider=config.leader.provider,
        model=config.leader.model,
        approval_mode=config.leader.approval_mode,
    )


def _leader_provider_readiness(
    *,
    agent_id: str,
    provider: str,
    model: str,
    approval_mode: str,
) -> dict[str, object]:
    leader_backend = leader_backend_identity(provider, model)
    if provider == "fake":
        return {
            "agent_id": agent_id,
            "provider": provider,
            "model": model,
            "approval_mode": approval_mode,
            "provider_backend": leader_provider_backend(provider),
            "provider_transport": leader_provider_transport(provider),
            "leader_backend": leader_backend,
            "ready": True,
            "supported": True,
            "missing_env": [],
            "detail": "fake provider is local and ready",
            "command_path": None,
            "setup_commands": _provider_setup_commands(provider),
        }
    required_env = {
        "deepseek": "DEEPSEEK_API_KEY",
        "openai-compatible": "AGENTDECK_LEADER_API_KEY",
    }.get(provider)
    cli_command = {
        "codex-cli": "codex",
        "claude-cli": "claude",
    }.get(provider)
    if cli_command is not None:
        command_path = _command_path(cli_command)
        ready = command_path is not None
        return {
            "agent_id": agent_id,
            "provider": provider,
            "model": model,
            "approval_mode": approval_mode,
            "provider_backend": leader_provider_backend(provider),
            "provider_transport": leader_provider_transport(provider),
            "leader_backend": leader_backend,
            "ready": ready,
            "supported": True,
            "missing_env": [],
            "detail": f"{cli_command} is available" if ready else f"{cli_command} is not found on PATH",
            "command_path": command_path,
            "setup_commands": _provider_setup_commands(provider),
        }
    if required_env is None:
        return {
            "agent_id": agent_id,
            "provider": provider,
            "model": model,
            "approval_mode": approval_mode,
            "provider_backend": leader_provider_backend(provider),
            "provider_transport": leader_provider_transport(provider),
            "leader_backend": leader_backend,
            "ready": False,
            "supported": False,
            "missing_env": [],
            "detail": f"unsupported leader provider: {provider}",
            "command_path": None,
            "setup_commands": [],
        }
    ready = bool(os.environ.get(required_env))
    detail = f"{required_env} is set" if ready else f"{required_env} is not set; provider calls are disabled"
    return {
        "agent_id": agent_id,
        "provider": provider,
        "model": model,
        "approval_mode": approval_mode,
        "provider_backend": leader_provider_backend(provider),
        "provider_transport": leader_provider_transport(provider),
        "leader_backend": leader_backend,
        "ready": ready,
        "supported": True,
        "missing_env": [] if ready else [required_env],
        "detail": detail,
        "command_path": None,
        "setup_commands": _provider_setup_commands(provider),
    }


def _leader_chat_provider_switch_card(
    project_view: dict[str, object],
    *,
    target_provider: str,
    target_model: str,
    require_ready: bool,
    command: str,
) -> dict[str, object]:
    leader = project_view.get("leader") if isinstance(project_view.get("leader"), dict) else {}
    approval_mode = str(leader.get("approval_mode") or "confirm")
    target_readiness = _leader_provider_readiness(
        agent_id="leader",
        provider=target_provider,
        model=target_model,
        approval_mode=approval_mode,
    )
    target_leader_backend = (
        target_readiness.get("leader_backend")
        if isinstance(target_readiness.get("leader_backend"), dict)
        else leader_backend_identity(target_provider, target_model)
    )
    control_kind = "guarded_set_provider" if require_ready else "set_provider"
    control_label = "Switch Leader provider if ready" if require_ready else "Switch Leader provider"
    target_ready = target_readiness.get("ready") is True
    provider_control_enabled = not require_ready or target_ready
    provider_control_blocker = None if provider_control_enabled else "target provider is not ready"
    setup_controls = []
    if not provider_control_enabled and isinstance(target_readiness.get("setup_commands"), list):
        setup_controls = [
            {
                "kind": "setup",
                "label": "Run provider setup",
                "command": str(setup_command),
                "safety": "explicit_user",
                "enabled": True,
                "blocker": None,
            }
            for setup_command in target_readiness["setup_commands"]
        ]
    return {
        "mode": "provider_switch",
        "title": "Switch Leader provider",
        "current_provider": leader.get("provider"),
        "current_model": leader.get("model"),
        "target_provider": target_provider,
        "target_model": target_model,
        "target_leader_backend": target_leader_backend,
        "target_readiness": target_readiness,
        "require_ready": require_ready,
        "command": command,
        "diagnostics_command": "agentdeck doctor",
        "safety": "explicit_user",
        "requires_explicit_user": True,
        "mutates_config": False,
        "controls": [
            {
                "kind": "inspect",
                "label": "Inspect provider setup",
                "command": "agentdeck doctor",
                "safety": "inspect",
                "enabled": True,
                "blocker": None,
            },
            {
                "kind": control_kind,
                "label": control_label,
                "command": command,
                "safety": "explicit_user",
                "enabled": provider_control_enabled,
                "blocker": provider_control_blocker,
            },
            *setup_controls,
        ],
    }


def _command_path(command: str) -> str | None:
    return shutil.which(command)


def _command_available(command: str) -> bool:
    return _command_path(command) is not None


def init_command(_args: argparse.Namespace) -> int:
    root = project_root()
    path = write_default_config(root)
    store = StateStore(root)
    state = store.load()
    store.save(state)
    store.append_event(EventRecord.create("project_initialized", {"config_path": str(path)}))
    _print_json(
        {
            "ok": True,
            "project_root": str(root),
            "agentdeck_dir": str(agentdeck_dir(root)),
            "config_path": str(path),
        }
    )
    return 0


def project_migration_preview_command(_args: argparse.Namespace) -> int:
    try:
        payload = migration_preview(project_root())
    except (OSError, TypeError, ValueError) as exc:
        print(f"migration preview failed: {exc}", file=sys.stderr)
        return 1
    validation = validate_migration_contract(payload)
    if not validation["ok"]:
        print("Migration contract validation failed", file=sys.stderr)
        for error in validation["errors"]:
            print(f"- {error}", file=sys.stderr)
        return 1
    _print_json(payload)
    return 0


def project_migrate_command(args: argparse.Namespace) -> int:
    required = (args.preview_id, args.source_hash, args.digest, args.expires_at)
    if args.confirm is not True or any(
        not isinstance(item, str) or not item for item in required
    ):
        print("migration requires exact confirmation from migration-preview", file=sys.stderr)
        return 1
    try:
        payload = confirm_migration(
            project_root(),
            preview_id=args.preview_id,
            source_hash=args.source_hash,
            digest=args.digest,
            expires_at=args.expires_at,
            confirm=True,
        )
    except (OSError, TypeError, ValueError) as exc:
        print(f"migration confirmation failed: {exc}", file=sys.stderr)
        return 1
    validation = validate_migration_contract(payload)
    if not validation["ok"]:
        print("Migration contract validation failed", file=sys.stderr)
        for error in validation["errors"]:
            print(f"- {error}", file=sys.stderr)
        return 1
    _print_json(payload)
    return 0


def status_command(_args: argparse.Namespace) -> int:
    root = project_root()
    try:
        config = load_config(root)
    except FileNotFoundError as exc:
        print(str(exc), file=sys.stderr)
        print("Run: python -m agentdeck project init", file=sys.stderr)
        return 1
    store = StateStore(root)
    payload = _project_view_payload_or_error(config, store)
    if payload is None:
        return 1
    _print_json(payload)
    return 0


def protocol_status_command(_args: argparse.Namespace) -> int:
    root = project_root()
    try:
        config = load_config(root)
    except FileNotFoundError as exc:
        print(str(exc), file=sys.stderr)
        print("Run: python -m agentdeck project init", file=sys.stderr)
        return 1
    store = StateStore.open_existing(root)
    try:
        project_view = _project_view_payload_or_error(config, store)
    except ValueError as exc:
        print(f"protocol runtime status failed: {exc}", file=sys.stderr)
        return 1
    if project_view is None:
        return 1
    payload = {
        "mode": "protocol_runtime_status",
        "contract_version": PROTOCOL_RUNTIME_CONTRACT_VERSION,
        "project": project_view["project"],
        "runtime_backend": project_view["runtime_backend"],
        "agent_sessions": project_view["agent_sessions"],
        "protocol_turns": project_view["protocol_turns"],
        "transport_updates": project_view["transport_updates"],
        "permission_requests": project_view["permission_requests"],
        "protocol_state_transitions": project_view["protocol_state_transitions"],
        "controls": deepcopy(protocol_runtime_example()["controls"]),
    }
    validation = validate_protocol_runtime_contract(payload)
    if not validation["ok"]:
        print("protocol runtime contract validation failed", file=sys.stderr)
        for error in validation["errors"]:
            print(f"- {error}", file=sys.stderr)
        return 1
    _print_json(payload)
    return 0


def _node_version_from_executable(executable: str | None) -> str | None:
    """Read Node's installed header; never execute the binary during preflight."""
    if not executable:
        return None
    binary = Path(executable).resolve()
    header = binary.parent.parent / "include" / "node" / "node_version.h"
    try:
        text = header.read_text(encoding="utf-8")
    except (OSError, UnicodeError):
        return None
    parts: list[str] = []
    for name in ("NODE_MAJOR_VERSION", "NODE_MINOR_VERSION", "NODE_PATCH_VERSION"):
        match = re.search(rf"^#define\s+{name}\s+(\d+)\s*$", text, re.MULTILINE)
        if match is None:
            return None
        parts.append(match.group(1))
    return ".".join(parts)


def _resolved_executable(command: str) -> str | None:
    found = shutil.which(command)
    return str(Path(found).expanduser().resolve(strict=False)) if found else None


def _probe_acp_sdk() -> tuple[bool, str | None]:
    try:
        if importlib.util.find_spec("acp") is None:
            return False, None
        version = importlib.metadata.version("agent-client-protocol")
    except Exception:
        return False, None
    if type(version) is not str or not version.strip():
        return False, None
    return True, version.strip()


def protocol_acp_preflight_command(args: argparse.Namespace) -> int:
    root = project_root()
    try:
        config = load_config(root)
    except (FileNotFoundError, ValueError) as exc:
        print(str(exc), file=sys.stderr)
        return 1
    StateStore.open_existing(root)  # Explicitly select the non-creating store path.
    agent = next((item for item in config.agents if item.agent_id == args.agent), None)
    if agent is None:
        print(f"unknown agent: {args.agent}", file=sys.stderr)
        return 1
    if agent.transport != "acp":
        print(f"agent {args.agent} is not configured for ACP transport", file=sys.stderr)
        return 1
    argv = list(agent.transport_command)
    if not argv:
        print(f"agent {args.agent} has an empty ACP transport_command", file=sys.stderr)
        return 1

    sdk_present, sdk_version = _probe_acp_sdk()
    executable_path = _resolved_executable(argv[0])
    blockers: list[str] = []
    if not sdk_present:
        blockers.append("ACP Python SDK is unavailable or unusable")
    elif sdk_version != ACP_RUNTIME_SDK_VERSION:
        blockers.append(f"ACP Python SDK version must be {ACP_RUNTIME_SDK_VERSION}")
    if executable_path is None:
        blockers.append("ACP adapter executable was not found")

    known_claude = acp_executable_basename(argv[0]) == "claude-agent-acp"
    node_path = _resolved_executable("node") if known_claude else None
    node_version = _node_version_from_executable(node_path) if known_claude else None
    node_ready = True
    if known_claude:
        node_major = int(node_version.split(".", 1)[0]) if node_version and node_version.split(".", 1)[0].isdigit() else None
        node_ready = node_path is not None and node_major is not None and node_major >= 22
        if not node_ready:
            blockers.append("claude-agent-acp requires Node >=22")

    payload = {
        "mode": "acp_preflight",
        "contract_version": ACP_RUNTIME_CONTRACT_VERSION,
        "project": config.name,
        "ready": not blockers,
        "agent": {"agent_id": agent.agent_id, "provider": agent.provider, "transport": agent.transport},
        "adapter": {"argv": argv, "executable_path": executable_path, "present": executable_path is not None},
        "sdk": {"module": "acp", "package": "agent-client-protocol", "present": sdk_present, "version": sdk_version},
        "node": {"required": known_claude, "minimum_major": 22 if known_claude else None, "executable_path": node_path, "version": node_version, "ready": node_ready},
        "blockers": blockers,
        "controls": [
            {"kind": "inspect", "label": "Inspect ACP preflight", "command": f"agentdeck protocol acp preflight --agent {agent.agent_id}", "safety": "inspect", "enabled": True, "blocker": None},
            {"kind": "inspect", "label": "Inspect ACP runtime contract", "command": "agentdeck contract acp-runtime", "safety": "inspect", "enabled": True, "blocker": None},
            {"kind": "inspect", "label": "Inspect protocol runtime", "command": "agentdeck protocol status", "safety": "inspect", "enabled": True, "blocker": None},
        ],
    }
    validation = validate_acp_runtime_contract(payload)
    if not validation["ok"]:
        print("ACP runtime contract validation failed", file=sys.stderr)
        for error in validation["errors"]:
            print(f"- {error}", file=sys.stderr)
        return 1
    _print_json(payload)
    return 0


def _acp_readiness(agent: AgentSpec) -> list[str]:
    blockers: list[str] = []
    sdk_present, sdk_version = _probe_acp_sdk()
    if not sdk_present:
        blockers.append("ACP Python SDK is unavailable or unusable")
    elif sdk_version != ACP_RUNTIME_SDK_VERSION:
        blockers.append(f"ACP Python SDK version must be {ACP_RUNTIME_SDK_VERSION}")
    if not agent.transport_command or _resolved_executable(agent.transport_command[0]) is None:
        blockers.append("ACP adapter executable was not found")
    if agent.transport_command and acp_executable_basename(agent.transport_command[0]) == "claude-agent-acp":
        node = _resolved_executable("node")
        version = _node_version_from_executable(node)
        major = int(version.split(".", 1)[0]) if version and version.split(".", 1)[0].isdigit() else None
        if node is None or major is None or major < 22:
            blockers.append("claude-agent-acp requires Node >=22")
    return blockers


def foreground_permission_decider(
    request: object,
    options: list[schema.PermissionOption],
    *,
    stdin: TextIO = sys.stdin,
    stderr: TextIO = sys.stderr,
    timeout_seconds: float = 60.0,
) -> PermissionDecision:
    if not stdin.isatty():
        return PermissionDecision.cancelled("non_tty")
    summary = request if isinstance(request, dict) else {}
    print(
        f"ACP permission: {summary.get('tool_name') or summary.get('title') or 'unknown tool'} "
        f"target={summary.get('target', 'unknown')} risk={summary.get('risk', 'unknown')}",
        file=stderr,
    )
    enabled: dict[int, str] = {}
    known_kinds = {"allow_once", "reject_once", "allow_always", "reject_always"}
    for index, option in enumerate(options, 1):
        marker = option.kind if option.kind in known_kinds else "unknown"
        supported = marker in {"allow_once", "reject_once"}
        suffix = "" if supported else " [disabled]"
        label = " ".join(option.name.split())[:120] or "unnamed option"
        print(f"{index}. {label} [{marker}]{suffix}", file=stderr)
        if supported:
            enabled[index] = option.option_id
    stderr.flush()
    deadline = time.monotonic() + timeout_seconds
    for _ in range(3):
        remaining = deadline - time.monotonic()
        if remaining <= 0:
            return PermissionDecision.cancelled("timeout")
        try:
            if hasattr(stdin, "fileno") and not isinstance(stdin, __import__("io").StringIO):
                ready, _, _ = select.select([stdin], [], [], remaining)
                if not ready:
                    return PermissionDecision.cancelled("timeout")
            line = stdin.readline()
        except (EOFError, KeyboardInterrupt):
            return PermissionDecision.cancelled("ctrl_c" if sys.exc_info()[0] is KeyboardInterrupt else "eof")
        if line == "":
            return PermissionDecision.cancelled("eof")
        try:
            choice = int(line.strip())
        except ValueError:
            choice = -1
        if choice in enabled:
            return PermissionDecision.select(enabled[choice])
        print("Invalid or disabled selection.", file=stderr)
        stderr.flush()
    return PermissionDecision.cancelled("invalid_input_exhausted")


class _AcpRunLedgerSink:
    def __init__(self, store: StateStore) -> None:
        self.store = store
        self.native_session_id: str | None = None
        self.session_id: str | None = None
        self.turn_id: str | None = None
        self.sequence = 0
        self.payload_bytes = 0
        self.turn_state = "created"
        self.pending_by_tool: dict[str, dict[str, Any]] = {}

    def activate(self, native_session_id: str, session_id: str, turn_id: str) -> None:
        self.native_session_id, self.session_id, self.turn_id = native_session_id, session_id, turn_id
        self.turn_state = "submitted"

    def _correlate(self, native_session_id: str) -> tuple[str, str]:
        if native_session_id != self.native_session_id or self.session_id is None or self.turn_id is None:
            raise ValueError("ACP session correlation mismatch")
        return self.session_id, self.turn_id

    def _transition_turn(self, to_state: str, reason: str | None = None) -> None:
        assert self.turn_id is not None
        self.store.record_protocol_transition("turn", self.turn_id, self.turn_state, to_state, reason, {})
        self.turn_state = to_state

    async def append_update(self, native_session_id: str, kind: str, payload: dict[str, Any]) -> object:
        session_id, turn_id = self._correlate(native_session_id)
        encoded = len(json.dumps(payload, ensure_ascii=False, sort_keys=True).encode("utf-8"))
        ensure_turn_within_bounds(
            self.payload_bytes + encoded + MAX_ACP_TERMINAL_UPDATE_BYTES,
            self.sequence + 2,
        )
        if self.turn_state == "submitted":
            self._transition_turn("streaming", "session_update_received")
        record = self.store.record_transport_update(session_id, turn_id, self.sequence, kind, payload)
        self.sequence += 1
        self.payload_bytes += encoded
        return record

    def append_terminal_error(self, reason: str) -> None:
        assert self.session_id is not None and self.turn_id is not None
        payload = {"reason": reason}
        encoded = len(json.dumps(payload, sort_keys=True).encode("utf-8"))
        ensure_turn_within_bounds(self.payload_bytes + encoded, self.sequence + 1)
        self.store.record_transport_update(
            self.session_id, self.turn_id, self.sequence, "error", payload
        )
        self.sequence += 1
        self.payload_bytes += encoded

    async def append_permission(
        self, native_session_id: str, summary: dict[str, Any], options: list[schema.PermissionOption]
    ) -> object:
        session_id, turn_id = self._correlate(native_session_id)
        result = self.store.record_acp_permission_pending(
            session_id, turn_id, self.sequence,
            tool_name=summary.get("title") or summary.get("kind") or "unknown",
            target=summary.get("target", "unknown"), risk=summary["risk"],
            tool_call_id=summary["tool_call_id"],
        )
        permission = result["permission"]
        self.pending_by_tool[summary["tool_call_id"]] = permission
        encoded = len(json.dumps(result["update"]["payload"], ensure_ascii=False, sort_keys=True).encode("utf-8"))
        self.sequence += 1
        self.payload_bytes += encoded
        self.turn_state = "waiting_permission"
        return {**summary, "permission_id": permission["permission_id"]}

    async def append_permission_decision(
        self, native_session_id: str, tool_call_id: str, decision: PermissionDecision
    ) -> None:
        self._correlate(native_session_id)
        permission = self.pending_by_tool.pop(tool_call_id)
        target = "expired" if decision.reason == "timeout" else decision.ledger_status
        self.store.record_protocol_transition(
            "permission", permission["permission_id"], "pending", target, decision.reason, {}
        )
        if self.turn_state == "waiting_permission":
            self._transition_turn("streaming", "permission_settled")


def _daemon_acp_update_digest(
    payload: Mapping[str, object], *, payload_bytes: int, update_count: int
) -> dict[str, object]:
    """Return the compact durable identity for one bounded ACP update."""
    try:
        encoded = json.dumps(
            payload,
            ensure_ascii=False,
            sort_keys=True,
            separators=(",", ":"),
            allow_nan=False,
        ).encode("utf-8")
    except (UnicodeEncodeError, ValueError, TypeError):
        raise ValueError("ACP update encoding is invalid") from None
    ensure_turn_within_bounds(
        payload_bytes + len(encoded) + MAX_ACP_TERMINAL_UPDATE_BYTES,
        update_count + 2,
    )
    return {
        "content_hash": f"sha256:{hashlib.sha256(encoded).hexdigest()}",
        "byte_count": len(encoded),
    }


class _DaemonAcpWorkerSink:
    """Queue ACP callbacks into the daemon's single authoritative writer."""

    fail_on_permission = False

    def __init__(
        self,
        *,
        service: ProjectDaemonService,
        store: StateStore,
        attempt: Mapping[str, object],
        agent: AgentSpec,
        workspace: Path,
    ) -> None:
        self.service = service
        self.store = store
        self.attempt = dict(attempt)
        self.agent = agent
        self.workspace = workspace.resolve()
        self.native_session_id: str | None = None
        self.session_id: str | None = None
        self.turn_id: str | None = None
        self.sequence = 0
        self.payload_bytes = 0
        self.turn_state = "created"
        self.session_state = "created"
        self.permission_seen = False
        self.fragments: list[str] = []
        self._permission_authority: dict[str, dict[str, object]] = {}
        self._disconnect_diagnostics: list[dict[str, str]] = []

    @property
    def disconnect_diagnostics(self) -> tuple[dict[str, str], ...]:
        return tuple(dict(item) for item in self._disconnect_diagnostics)

    async def _mutate(self, callback: Any) -> object:
        return await self.service.submit_mutation(callback)

    async def activate(self, native_session_id: str, initialized: object) -> None:
        capabilities = getattr(initialized, "capabilities", None)
        protocol_version = getattr(initialized, "protocol_version", None)
        agent_identity = getattr(initialized, "agent_identity", None)
        if (
            type(native_session_id) is not str
            or not native_session_id
            or capabilities is None
        ):
            raise ServiceError("daemon ACP session activation is invalid")
        self.native_session_id = native_session_id

        def persist() -> dict[str, object]:
            session = self.store.record_agent_session(
                self.agent.agent_id,
                self.agent.provider,
                "acp-adapter",
                native_session_id,
                str(self.workspace),
                capabilities,
            )
            self.store.record_protocol_transition(
                "session",
                session["session_id"],
                "created",
                "ready",
                "daemon_session_new_completed",
                {
                    "protocol_version": protocol_version,
                    "agent_identity": agent_identity,
                },
            )
            turn = self.store.record_protocol_turn(
                session["session_id"], str(self.attempt["dispatch_key"]), "prompt"
            )
            self.store.record_protocol_transition(
                "turn", turn["turn_id"], "created", "submitted",
                "daemon_prompt_submitted", {},
            )
            self.store.record_protocol_transition(
                "session", session["session_id"], "ready", "busy",
                "daemon_prompt_started", {},
            )
            # Publish only the exact identities whose complete activation
            # sequence has durably returned from every StateStore write.  The
            # service may cancel the awaiting Worker before its Future resumes.
            self.session_id = str(session["session_id"])
            self.turn_id = str(turn["turn_id"])
            self.turn_state = "submitted"
            self.session_state = "busy"
            return {"session_id": session["session_id"], "turn_id": turn["turn_id"]}

        persisted = await self._mutate(persist)
        if not isinstance(persisted, Mapping):
            raise ServiceError("daemon ACP session persistence failed")
        self.session_id = str(persisted["session_id"])
        self.turn_id = str(persisted["turn_id"])
        self.turn_state = "submitted"
        self.session_state = "busy"

    def _correlate(self, native_session_id: str) -> tuple[str, str]:
        if (
            native_session_id != self.native_session_id
            or self.session_id is None
            or self.turn_id is None
        ):
            raise ServiceError("daemon ACP session correlation mismatch")
        return self.session_id, self.turn_id

    async def append_update(
        self, native_session_id: str, kind: str, payload: dict[str, Any]
    ) -> object:
        session_id, turn_id = self._correlate(native_session_id)
        durable_payload = _daemon_acp_update_digest(
            payload,
            payload_bytes=self.payload_bytes,
            update_count=self.sequence,
        )
        encoded = int(durable_payload["byte_count"])
        sequence = self.sequence
        prior = self.turn_state

        def persist() -> object:
            if prior == "submitted":
                self.store.record_protocol_transition(
                    "turn", turn_id, "submitted", "streaming",
                    "daemon_session_update_received", {},
                )
            return self.store.record_transport_update(
                session_id, turn_id, sequence, kind, durable_payload
            )

        record = await self._mutate(persist)
        if prior == "submitted":
            self.turn_state = "streaming"
        self.sequence += 1
        self.payload_bytes += encoded
        content = payload.get("content") if type(payload) is dict else None
        text = content.get("text") if isinstance(content, dict) else None
        if kind == "text" and payload.get("role") == "agent" and type(text) is str:
            self.fragments.append(text)
        return record

    async def append_permission(
        self,
        native_session_id: str,
        summary: dict[str, Any],
        _options: list[schema.PermissionOption],
    ) -> object:
        session_id, turn_id = self._correlate(native_session_id)
        sequence = self.sequence

        def persist() -> dict[str, object]:
            result = self.store.record_mission_acp_permission_pending(
                attempt_id=str(self.attempt["attempt_id"]),
                session_id=session_id,
                turn_id=turn_id,
                sequence=sequence,
                tool_name=summary.get("kind") or "unknown",
                target=summary.get("target", "unknown"),
                risk=summary["risk"],
                tool_call_id=summary["tool_call_id"],
            )
            permission = result["permission"]
            return {
                "permission_id": permission["permission_id"],
                "payload": result["update"]["payload"],
            }

        persisted = await self._mutate(persist)
        if not isinstance(persisted, Mapping):
            raise ServiceError("daemon ACP permission persistence failed")
        permission_id = str(persisted["permission_id"])
        payload = persisted["payload"]
        encoded = len(
            json.dumps(payload, ensure_ascii=False, sort_keys=True).encode("utf-8")
        )
        authority = {
            "permission_id": permission_id,
            "attempt_id": str(self.attempt["attempt_id"]),
            "session_id": session_id,
            "generation": 1,
        }
        self._permission_authority[permission_id] = authority
        self.permission_seen = True
        self.turn_state = "waiting_permission"
        self.sequence += 1
        self.payload_bytes += encoded
        return {**summary, "permission_id": permission_id}

    def _read_permission(self, permission_id: str) -> str:
        state = self.store.validated_protocol_state()
        matches = [
            item for item in state.get("permission_requests", [])
            if isinstance(item, dict) and item.get("permission_id") == permission_id
        ]
        if len(matches) != 1:
            raise ServiceError("daemon ACP permission lineage is invalid")
        return self.store._derived_protocol_state(
            state, "permission", permission_id, matches[0]
        )

    async def decide(
        self, pending: dict[str, Any], options: list[schema.PermissionOption]
    ) -> PermissionDecision:
        permission_id = pending.get("permission_id")
        authority = self._permission_authority.get(str(permission_id))
        if authority is None:
            return PermissionDecision.cancelled("permission_lineage_missing")
        decision = await self.service.wait_for_permission(
            authority,
            read_decision=lambda: self._read_permission(str(permission_id)),
        )
        if decision == "approved":
            governed = await self._mutate(
                lambda: authorize_mission_acp_effect(
                    self.store,
                    attempt_id=str(self.attempt["attempt_id"]),
                    permission_id=str(permission_id),
                )
            )
            if not isinstance(governed, Mapping) or governed.get("allowed") is not True:
                gate = (
                    governed.get("gate")
                    if isinstance(governed, Mapping)
                    else "invalid"
                )
                return PermissionDecision.cancelled(f"governance_blocked:{gate}")
        wanted = "allow_once" if decision == "approved" else "reject_once"
        option = next((item for item in options if item.kind == wanted), None)
        if option is None:
            return PermissionDecision.cancelled(f"human_{decision}")
        return PermissionDecision.select(option.option_id)

    async def append_permission_decision(
        self,
        native_session_id: str,
        tool_call_id: str,
        _decision: PermissionDecision,
    ) -> None:
        _session_id, turn_id = self._correlate(native_session_id)
        if type(tool_call_id) is not str or not tool_call_id:
            raise ServiceError("daemon ACP permission decision is invalid")
        if self.turn_state == "waiting_permission":
            await self._mutate(
                lambda: self.store.record_protocol_transition(
                    "turn", turn_id, "waiting_permission", "streaming",
                    "daemon_permission_settled", {},
                )
            )
            self.turn_state = "streaming"

    async def finish(self, stop_reason: str) -> None:
        if self.session_id is None or self.turn_id is None:
            raise ServiceError("daemon ACP completion lineage is invalid")
        turn_from = self.turn_state
        turn_to, mapped_reason = map_stop_reason(stop_reason)

        def persist() -> None:
            self.store.record_protocol_transition(
                "turn", self.turn_id, turn_from, turn_to,
                f"daemon_stop_reason:{mapped_reason}", {},
            )
            self.store.record_protocol_transition(
                "session", self.session_id, "busy", "ready",
                "daemon_prompt_finished", {},
            )

        await self._mutate(persist)
        self.turn_state = turn_to
        self.session_state = "ready"

    def begin_disconnect(self, reason: str) -> object:
        """Submit cleanup while still executing as the registered Worker task."""
        if self.session_id is None:
            return None
        known_session_id = self.session_id

        def persist() -> str | None:
            state = self.store.validated_protocol_state()
            matches = [
                item for item in state.get("agent_sessions", [])
                if type(item) is dict
                and item.get("session_id") == known_session_id
            ]
            if len(matches) != 1:
                raise ServiceError("daemon ACP disconnect lineage is invalid")
            session_id = str(matches[0]["session_id"])
            current = self.store._derived_protocol_state(
                state, "session", session_id, matches[0]
            )
            if current == "disconnected":
                return session_id
            if current not in {"busy", "ready"}:
                raise ServiceError("daemon ACP disconnect lineage is invalid")
            try:
                self.store.record_protocol_transition(
                    "session", session_id, current, "disconnected",
                    f"daemon_transport_closed:{reason}", {},
                )
            except ValueError:
                latest = self.store.validated_protocol_state()
                latest_record = next(
                    (
                        item for item in latest.get("agent_sessions", [])
                        if type(item) is dict and item.get("session_id") == session_id
                    ),
                    None,
                )
                if latest_record is not None and self.store._derived_protocol_state(
                    latest, "session", session_id, latest_record
                ) == "disconnected":
                    return session_id
                raise
            return session_id

        persisted = self.service.submit_worker_cleanup(persist)

        def observe(completed: asyncio.Future[object]) -> None:
            try:
                session_id = completed.result()
            except BaseException:
                self._disconnect_diagnostics.append(
                    {
                        "status": "failed",
                        "reason": "disconnect persistence failed",
                    }
                )
            else:
                if session_id is not None:
                    self.session_id = str(session_id)
                    self.session_state = "disconnected"

        persisted.add_done_callback(observe)

        async def finish() -> None:
            await asyncio.shield(persisted)

        return finish()

    async def disconnect(self, reason: str) -> None:
        """Persist the daemon-owned ACP process boundary after transport close."""
        operation = self.begin_disconnect(reason)
        if inspect.isawaitable(operation):
            await operation


def _derived_entity_state(state: dict[str, Any], entity_type: str, entity_id: str, base: str) -> str:
    current = base
    for transition in state.get("protocol_state_transitions", []):
        if transition.get("entity_type") == entity_type and transition.get("entity_id") == entity_id:
            current = transition["to_state"]
    return current


def _latest_protocol_identity(records: list[dict[str, Any]], identity_field: str) -> str | None:
    if not records:
        return None
    latest = max(
        records,
        key=lambda item: (str(item.get("created_at", "")), str(item.get(identity_field, ""))),
    )
    value = latest.get(identity_field)
    return value if isinstance(value, str) else None


def _acp_adapter_provenance(agent: AgentSpec) -> dict[str, str]:
    encoded = json.dumps(list(agent.transport_command), ensure_ascii=False, separators=(",", ":")).encode("utf-8")
    executable = _resolved_executable(agent.transport_command[0]) or agent.transport_command[0]
    return {
        "argv_hash": hashlib.sha256(encoded).hexdigest(),
        "executable_identity": hashlib.sha256(str(Path(executable).expanduser().resolve(strict=False)).encode("utf-8")).hexdigest(),
    }


async def _governed_prompt_turn(
    store: StateStore, session: dict[str, Any], transport: AcpTransport,
    sink: _AcpRunLedgerSink, prompt: str,
) -> tuple[dict[str, Any], str, bool]:
    turn = store.record_protocol_turn(session["session_id"], new_id("msg"), "prompt")
    store.record_protocol_transition("turn", turn["turn_id"], "created", "submitted", "prompt_submitted", {})
    sink.activate(session["native_session_id"], session["session_id"], turn["turn_id"])
    store.record_protocol_transition("session", session["session_id"], "ready", "busy", "prompt_started", {})
    disconnect_reason = "clean_exit"
    cancelled = False
    try:
        result = await transport.prompt(session["native_session_id"], prompt)
        target_state, reason = map_stop_reason(result.stop_reason)
        completion_payload = {"stop_reason": result.stop_reason}
        completion_bytes = len(json.dumps(completion_payload, sort_keys=True).encode("utf-8"))
        ensure_turn_within_bounds(sink.payload_bytes + completion_bytes, sink.sequence + 1)
        store.record_transport_update(session["session_id"], turn["turn_id"], sink.sequence, "completion", completion_payload)
        sink.sequence += 1
        sink._transition_turn(target_state, reason)
        store.record_protocol_transition("session", session["session_id"], "busy", "ready", "prompt_finished", {})
    except AcpAmbiguousOutcome:
        disconnect_reason = "unexpected_eof"
        with contextlib.suppress(Exception):
            sink.append_terminal_error("unexpected_eof")
        sink._transition_turn("ambiguous", "unexpected_eof")
        print("ACP prompt outcome is ambiguous", file=sys.stderr)
    except (AcpRequestTimeout, AcpTransportError, asyncio.CancelledError, OSError, ValueError) as error:
        cancelled = isinstance(error, asyncio.CancelledError)
        disconnect_reason = "timeout" if isinstance(error, AcpRequestTimeout) else "failed"
        with contextlib.suppress(Exception):
            sink.append_terminal_error(disconnect_reason)
        sink._transition_turn("failed", disconnect_reason)
        print("ACP prompt failed: " + ("timeout" if isinstance(error, AcpRequestTimeout) else "runtime_error"), file=sys.stderr)
    return turn, disconnect_reason, cancelled


async def _settle_acp_transport_cleanup(transport: AcpTransport) -> tuple[bool, bool]:
    cleanup_failed = False
    cancellation_requested = False
    cleanup_task = transport.ensure_cleanup_task()
    while not cleanup_task.done():
        try:
            await asyncio.shield(cleanup_task)
        except asyncio.CancelledError:
            cancellation_requested = True
            continue
        except BaseException:
            cleanup_failed = True
            break
    if cleanup_task.done() and not cleanup_task.cancelled():
        try:
            cleanup_task.result()
        except BaseException:
            cleanup_failed = True
    return cleanup_failed, cancellation_requested


async def _run_acp_prompt(config: ProjectConfig, agent: AgentSpec, store: StateStore, prompt: str) -> dict[str, Any]:
    sink = _AcpRunLedgerSink(store)
    client = AgentDeckAcpClient(
        sink=sink,
        decide=lambda pending, options: foreground_permission_decider(
            pending, options, stdin=sys.stdin, stderr=sys.stderr
        ),
    )
    transport = AcpTransport(agent.transport_command, project_root(), client)
    session: dict[str, Any] | None = None
    turn: dict[str, Any] | None = None
    stop_reason: str | None = None
    disconnect_reason = "clean_exit"
    initialized = None
    cancellation_requested = False
    try:
        initialized = await transport.initialize()
        native = await transport.new_session()
        session = store.record_agent_session(
            agent.agent_id, agent.provider, "acp-adapter", native.native_session_id,
            str(project_root().resolve()), initialized.capabilities,
        )
        store.record_protocol_transition(
            "session", session["session_id"], "created", "ready",
            "session_new_completed", {
                "protocol_version": initialized.protocol_version,
                "agent_identity": initialized.agent_identity,
                "adapter_provenance": _acp_adapter_provenance(agent),
            },
        )
        turn, disconnect_reason, cancellation_requested = await _governed_prompt_turn(
            store, session, transport, sink, prompt
        )
    except AcpAmbiguousOutcome as error:
        disconnect_reason = "unexpected_eof"
        if turn is not None and sink.turn_state not in {"completed", "blocked", "failed", "ambiguous"}:
            with contextlib.suppress(Exception):
                sink.append_terminal_error("unexpected_eof")
            sink._transition_turn("ambiguous", "unexpected_eof")
        print("ACP prompt outcome is ambiguous", file=sys.stderr)
    except (AcpRequestTimeout, AcpTransportError, asyncio.CancelledError, OSError, ValueError) as error:
        cancellation_requested = isinstance(error, asyncio.CancelledError)
        disconnect_reason = "timeout" if isinstance(error, AcpRequestTimeout) else "failed"
        if turn is not None and sink.turn_state not in {"completed", "blocked", "failed", "ambiguous"}:
            with contextlib.suppress(Exception):
                sink.append_terminal_error(disconnect_reason)
            sink._transition_turn("failed", disconnect_reason)
        print(
            "ACP prompt failed: " + (
                "timeout" if isinstance(error, AcpRequestTimeout) else "runtime_error"
            ),
            file=sys.stderr,
        )
    finally:
        cleanup_failed, cleanup_cancelled = await _settle_acp_transport_cleanup(transport)
        cancellation_requested = cancellation_requested or cleanup_cancelled
        if cleanup_failed:
            print("ACP cleanup failed", file=sys.stderr)
        summary = transport.stderr_summary
        if summary["present"]:
            print("ACP adapter diagnostic: " + json.dumps(summary, sort_keys=True), file=sys.stderr)
        if session is not None:
            state = store.load()
            current = _derived_entity_state(state, "session", session["session_id"], "created")
            if current != "disconnected":
                store.record_protocol_transition(
                    "session", session["session_id"], current, "disconnected",
                    "cleanup_failed" if cleanup_failed else disconnect_reason, {},
                )
    if cancellation_requested:
        raise asyncio.CancelledError
    if session is None or turn is None or initialized is None:
        raise AcpTransportError("ACP run failed before a native session was created")
    return _acp_run_payload_from_state(store, session["session_id"], turn["turn_id"])


def _acp_run_payload_from_state(
    store: StateStore, session_id: str, turn_id: str
) -> dict[str, Any]:
    """Rebuild the public run response exclusively from durable protocol facts."""
    state = store.validated_protocol_state()
    sessions = [item for item in state["agent_sessions"] if item["session_id"] == session_id]
    turns = [item for item in state["protocol_turns"] if item["turn_id"] == turn_id]
    if len(sessions) != 1 or len(turns) != 1:
        raise ValueError("ACP run identities must resolve exactly once")
    session, turn = sessions[0], turns[0]
    if turn["session_id"] != session_id:
        raise ValueError("ACP run turn does not belong to session")
    transitions = state["protocol_state_transitions"]
    ready_items = [
        item for item in transitions
        if item["entity_type"] == "session" and item["entity_id"] == session_id
        and item["reason"] == "session_new_completed"
    ]
    if len(ready_items) != 1:
        raise ValueError("ACP run requires one negotiated session transition")
    ready = ready_items[0]
    session_transitions = [
        item for item in transitions
        if item["entity_type"] == "session" and item["entity_id"] == session_id
    ]
    disconnected_items = [
        item for item in session_transitions
        if item["to_state"] == "disconnected"
    ]
    if len(disconnected_items) != 1 or session_transitions[-1] != disconnected_items[0]:
        raise ValueError("ACP run requires one final disconnect transition")
    disconnected = disconnected_items[0]
    turn_state = _derived_entity_state(state, "turn", turn_id, turn["state"])
    updates = [item for item in state["transport_updates"] if item["turn_id"] == turn_id]
    if [item["sequence"] for item in updates] != list(range(len(updates))):
        raise ValueError("ACP run update sequence is not contiguous")
    all_transitions = state["protocol_state_transitions"]
    completions = [item for item in updates if item["kind"] == "completion"]
    if len(completions) > 1:
        raise ValueError("ACP run has conflicting completion updates")
    if turn_state in {"completed", "blocked"} and len(completions) != 1:
        raise ValueError("ACP terminal turn requires exactly one completion update")
    stop_reason = completions[-1]["payload"]["stop_reason"] if completions else None
    if stop_reason is not None and map_stop_reason(stop_reason)[0] != turn_state:
        raise ValueError("ACP stop reason conflicts with persisted turn state")
    return {
        "mode": "acp_run", "contract_version": ACP_RUNTIME_CONTRACT_VERSION,
        "agent_id": session["agent_id"], "session_id": session["session_id"],
        "native_session_id": session["native_session_id"],
        "protocol_version": ready["details"]["protocol_version"],
        "capabilities": session["capabilities"], "turn_id": turn["turn_id"], "turn_state": turn_state,
        "stop_reason": stop_reason, "session_count": len(state["agent_sessions"]),
        "turn_count": len(state["protocol_turns"]), "update_count": len(state["transport_updates"]),
        "permission_count": len(state["permission_requests"]),
        "transition_count": len(all_transitions),
        "latest_session_id": _latest_protocol_identity(state["agent_sessions"], "session_id"),
        "latest_turn_id": _latest_protocol_identity(state["protocol_turns"], "turn_id"),
        "latest_update_id": _latest_protocol_identity(state["transport_updates"], "update_id"),
        "latest_permission_id": _latest_protocol_identity(state["permission_requests"], "permission_id"),
        "latest_transition_id": _latest_protocol_identity(all_transitions, "transition_id"),
        "session_state": _derived_entity_state(state, "session", session["session_id"], session["state"]),
        "disconnect_reason": disconnected["reason"],
        "controls": [
            {"kind": "inspect", "label": "Inspect protocol runtime", "command": "agentdeck protocol status", "safety": "inspect", "enabled": True, "blocker": None},
            {"kind": "inspect", "label": "Inspect ACP runtime contract", "command": "agentdeck contract acp-runtime", "safety": "inspect", "enabled": True, "blocker": None},
        ],
    }


async def _close_reconnected_transport(
    transport: AcpTransport, store: StateStore, session_id: str, reason: str
) -> bool:
    cleanup_failed, cancellation_requested = await _settle_acp_transport_cleanup(transport)
    state = store.load()
    current = _derived_entity_state(state, "session", session_id, "created")
    if current != "disconnected":
        store.record_protocol_transition(
            "session", session_id, current, "disconnected",
            "cleanup_failed" if cleanup_failed else reason, {},
        )
    return cancellation_requested


def _acp_reconnect_payload_from_state(
    store: StateStore, session_id: str, turn_id: str, mode: str
) -> dict[str, Any]:
    state = store.validated_protocol_state()
    sessions = [item for item in state["agent_sessions"] if item["session_id"] == session_id]
    turns = [item for item in state["protocol_turns"] if item["turn_id"] == turn_id]
    if len(sessions) != 1 or len(turns) != 1:
        raise ValueError("ACP reconnect identities must resolve exactly once")
    session, turn = sessions[0], turns[0]
    if turn["session_id"] != session_id:
        raise ValueError("ACP reconnect turn does not belong to session")
    updates = [item for item in state["transport_updates"] if item["turn_id"] == turn_id]
    all_transitions = state["protocol_state_transitions"]
    if [item["sequence"] for item in updates] != list(range(len(updates))):
        raise ValueError("ACP reconnect update sequence is not contiguous")
    transitions = [item for item in state["protocol_state_transitions"] if item["entity_type"] == "session" and item["entity_id"] == session_id]
    ready_items = [
        item for item in transitions
        if item["to_state"] == "ready" and "protocol_version" in item["details"]
    ]
    if not ready_items:
        raise ValueError("ACP reconnect requires a negotiated ready transition")
    ready = ready_items[-1]
    if transitions.count(ready) != 1:
        raise ValueError("ACP reconnect ready transition is ambiguous")
    if not transitions:
        raise ValueError("ACP reconnect requires session transitions")
    disconnected = transitions[-1]
    if disconnected["to_state"] != "disconnected":
        raise ValueError("ACP reconnect requires final disconnect")
    completions = [item for item in updates if item["kind"] == "completion"]
    turn_state = _derived_entity_state(state, "turn", turn_id, turn["state"])
    if turn_state not in {"completed", "blocked", "failed", "ambiguous"} or (
        turn_state in {"completed", "blocked"} and len(completions) != 1
    ) or (turn_state in {"failed", "ambiguous"} and len(completions) > 1):
        raise ValueError("ACP reconnect terminal turn has invalid completion cardinality")
    stop_reason = completions[-1]["payload"]["stop_reason"] if completions else None
    if mode == "acp_load" and (turn["kind"] != "load_replay" or stop_reason != "loaded" or turn_state != "completed"):
        raise ValueError("ACP load replay terminal facts are inconsistent")
    if mode == "acp_resume" and (
        turn["kind"] != "prompt" or (
            stop_reason is not None and map_stop_reason(stop_reason)[0] != turn_state
        ) or (turn_state in {"completed", "blocked"} and stop_reason is None)
    ):
        raise ValueError("ACP resumed prompt terminal facts are inconsistent")
    return {
        "mode": mode, "contract_version": ACP_RUNTIME_CONTRACT_VERSION,
        "agent_id": session["agent_id"], "session_id": session_id,
        "native_session_id": session["native_session_id"],
        "protocol_version": ready["details"]["protocol_version"],
        "capabilities": session["capabilities"], "turn_id": turn_id,
        "turn_state": turn_state,
        "stop_reason": stop_reason, "session_count": len(state["agent_sessions"]),
        "turn_count": len(state["protocol_turns"]), "update_count": len(state["transport_updates"]),
        "permission_count": len(state["permission_requests"]), "transition_count": len(all_transitions),
        "latest_session_id": _latest_protocol_identity(state["agent_sessions"], "session_id"),
        "latest_turn_id": _latest_protocol_identity(state["protocol_turns"], "turn_id"),
        "latest_update_id": _latest_protocol_identity(state["transport_updates"], "update_id"),
        "latest_permission_id": _latest_protocol_identity(state["permission_requests"], "permission_id"),
        "latest_transition_id": _latest_protocol_identity(all_transitions, "transition_id"),
        "session_state": _derived_entity_state(state, "session", session_id, session["state"]),
        "disconnect_reason": disconnected["reason"],
        "controls": [
            {"kind": "inspect", "label": "Inspect protocol runtime", "command": "agentdeck protocol status", "safety": "inspect", "enabled": True, "blocker": None},
            {"kind": "inspect", "label": "Inspect ACP runtime contract", "command": "agentdeck contract acp-runtime", "safety": "inspect", "enabled": True, "blocker": None},
        ],
    }


async def _load_acp_session(
    config: ProjectConfig, agent: AgentSpec, store: StateStore, session: dict[str, Any]
) -> dict[str, Any]:
    sink = _AcpRunLedgerSink(store)
    client = AgentDeckAcpClient(sink=sink, decide=lambda *_: PermissionDecision.cancelled("load_replay"))
    transport = AcpTransport(agent.transport_command, project_root(), client)
    turn: dict[str, Any] | None = None
    try:
        initialized = await transport.initialize()
        if not initialized.load_session:
            raise AcpTransportError("ACP Agent does not support loadSession")
        store.record_protocol_transition("session", session["session_id"], "disconnected", "reconnecting", "session_load_started", {})
        turn = store.record_protocol_turn(session["session_id"], new_id("msg"), "load_replay")
        store.record_protocol_transition("turn", turn["turn_id"], "created", "submitted", "session_load_submitted", {})
        sink.activate(session["native_session_id"], session["session_id"], turn["turn_id"])
        await transport.load_session(session["native_session_id"])
        store.record_transport_update(session["session_id"], turn["turn_id"], sink.sequence, "completion", {"stop_reason": "loaded"})
        sink.sequence += 1
        sink._transition_turn("completed", "session_load_completed")
        store.record_protocol_transition("session", session["session_id"], "reconnecting", "ready", "session_load_completed", {"protocol_version": initialized.protocol_version, "agent_identity": initialized.agent_identity})
    except asyncio.CancelledError:
        if turn is not None and sink.turn_state not in {"completed", "blocked", "failed", "ambiguous"}:
            await transport.cancel_session(session["native_session_id"])
            with contextlib.suppress(Exception):
                sink.append_terminal_error("cancelled")
            sink._transition_turn("failed", "cancelled")
        raise
    except (AcpAmbiguousOutcome, AcpTransportError, AcpRequestTimeout, ValueError) as error:
        if turn is not None and sink.turn_state not in {"completed", "blocked", "failed", "ambiguous"}:
            deterministic = isinstance(error, (AcpRequestTimeout, ValueError)) or "callback rejected" in str(error)
            if isinstance(error, AcpRequestTimeout):
                await transport.cancel_session(session["native_session_id"])
            target = "failed" if deterministic else "ambiguous"
            reason = "timeout" if isinstance(error, AcpRequestTimeout) else (
                "deterministic_error" if deterministic else "unknown_load_outcome"
            )
            with contextlib.suppress(Exception):
                sink.append_terminal_error(reason)
            sink._transition_turn(target, reason)
        raise
    finally:
        cleanup_cancelled = await _close_reconnected_transport(transport, store, session["session_id"], "clean_exit")
    if cleanup_cancelled:
        raise asyncio.CancelledError
    assert turn is not None
    return _acp_reconnect_payload_from_state(store, session["session_id"], turn["turn_id"], "acp_load")


async def _resume_acp_session(
    config: ProjectConfig, agent: AgentSpec, store: StateStore,
    session: dict[str, Any], prompt: str,
) -> dict[str, Any]:
    sink = _AcpRunLedgerSink(store)
    client = AgentDeckAcpClient(
        sink=sink,
        decide=lambda pending, options: foreground_permission_decider(pending, options, stdin=sys.stdin, stderr=sys.stderr),
    )
    transport = AcpTransport(agent.transport_command, project_root(), client)
    turn: dict[str, Any] | None = None
    cancellation_requested = False
    disconnect_reason = "clean_exit"
    try:
        initialized = await transport.initialize()
        if not initialized.resume_session:
            raise AcpTransportError("ACP Agent does not support sessionCapabilities.resume")
        store.record_protocol_transition("session", session["session_id"], "disconnected", "reconnecting", "session_resume_started", {})
        await transport.resume_session(session["native_session_id"])
        store.record_protocol_transition("session", session["session_id"], "reconnecting", "ready", "session_resume_completed", {"protocol_version": initialized.protocol_version, "agent_identity": initialized.agent_identity})
        turn, disconnect_reason, cancellation_requested = await _governed_prompt_turn(
            store, session, transport, sink, prompt
        )
    except AcpTransportError as error:
        if turn is not None and sink.turn_state not in {"completed", "blocked", "failed", "ambiguous"}:
            sink.append_terminal_error(str(error))
            sink._transition_turn("ambiguous", "unexpected_resume_replay" if str(error) == "unexpected_resume_replay" else "runtime_error")
        raise
    finally:
        cleanup_cancelled = await _close_reconnected_transport(transport, store, session["session_id"], disconnect_reason)
        cancellation_requested = cancellation_requested or cleanup_cancelled
    if cancellation_requested:
        raise asyncio.CancelledError
    assert turn is not None
    return _acp_reconnect_payload_from_state(store, session["session_id"], turn["turn_id"], "acp_resume")


def protocol_acp_run_command(args: argparse.Namespace) -> int:
    if not args.confirm:
        print("--confirm is required to start an ACP Agent", file=sys.stderr)
        return 1
    if type(args.prompt) is not str or not args.prompt.strip():
        print("--prompt must be non-empty", file=sys.stderr)
        return 1
    root = project_root()
    try:
        config = load_config(root)
    except (FileNotFoundError, ValueError) as error:
        print(str(error), file=sys.stderr)
        return 1
    agent = next((item for item in config.agents if item.agent_id == args.agent), None)
    if agent is None:
        print(f"unknown agent: {args.agent}", file=sys.stderr)
        return 1
    if agent.transport != "acp":
        print(f"agent {args.agent} is not configured for ACP transport", file=sys.stderr)
        return 1
    blockers = _acp_readiness(agent)
    if blockers:
        print("ACP preflight is not ready: " + "; ".join(blockers), file=sys.stderr)
        return 1
    store = StateStore.open_existing(root)
    try:
        payload = asyncio.run(_run_acp_prompt(config, agent, store, args.prompt))
    except (AcpTransportError, ValueError, KeyError) as error:
        print(str(error), file=sys.stderr)
        return 1
    validation = validate_acp_runtime_contract(payload)
    if not validation["ok"]:
        print("ACP runtime contract validation failed", file=sys.stderr)
        for error in validation["errors"]:
            print(f"- {error}", file=sys.stderr)
        return 1
    _print_json(payload)
    return 0


def _resolve_acp_session(config: ProjectConfig, store: StateStore, session_id: str) -> tuple[dict[str, Any], AgentSpec]:
    state = store.validated_protocol_state()
    matches = [item for item in state["agent_sessions"] if item["session_id"] == session_id]
    if len(matches) != 1:
        raise ValueError(f"unknown or ambiguous ACP session: {session_id}")
    session = matches[0]
    if session.get("transport") != "acp-adapter":
        raise ValueError("session is not an ACP adapter session")
    if type(session.get("native_session_id")) is not str or not session["native_session_id"]:
        raise ValueError("ACP session has no native session id")
    agents = [item for item in config.agents if item.agent_id == session["agent_id"]]
    if len(agents) != 1 or agents[0].transport != "acp":
        raise ValueError("ACP session agent configuration is unavailable")
    if session.get("provider") != agents[0].provider:
        raise ValueError("ACP session provider does not match current agent configuration")
    if str(Path(session["workspace"]).resolve()) != str(project_root().resolve()):
        raise ValueError("ACP session workspace does not match the current project")
    created = [
        item for item in state["protocol_state_transitions"]
        if item["entity_type"] == "session" and item["entity_id"] == session_id
        and item["reason"] == "session_new_completed"
    ]
    if len(created) != 1 or created[0].get("details", {}).get("adapter_provenance") != _acp_adapter_provenance(agents[0]):
        raise ValueError("ACP adapter configuration provenance has changed")
    return session, agents[0]


def _acp_reconnect_command(args: argparse.Namespace, *, resume: bool) -> int:
    if not args.confirm:
        print("--confirm is required to start an ACP Agent", file=sys.stderr)
        return 1
    if resume and (type(args.prompt) is not str or not args.prompt.strip()):
        print("--prompt must be non-empty", file=sys.stderr)
        return 1
    try:
        config = load_config(project_root())
        store = StateStore.open_existing(project_root())
        session, agent = _resolve_acp_session(config, store, args.session_id)
    except (FileNotFoundError, KeyError, ValueError) as error:
        print(str(error), file=sys.stderr)
        return 1
    blockers = _acp_readiness(agent)
    if blockers:
        print("ACP preflight is not ready: " + "; ".join(blockers), file=sys.stderr)
        return 1
    try:
        payload = asyncio.run(_resume_acp_session(config, agent, store, session, args.prompt) if resume else _load_acp_session(config, agent, store, session))
    except (AcpTransportError, ValueError, KeyError) as error:
        print(str(error), file=sys.stderr)
        return 1
    validation = validate_acp_runtime_contract(payload)
    if not validation["ok"]:
        print("ACP runtime contract validation failed", file=sys.stderr)
        return 1
    _print_json(payload)
