def _workbench_provider_health(project_view: dict[str, object]) -> dict[str, object]:
    leader = project_view.get("leader") if isinstance(project_view.get("leader"), dict) else {}
    provider = str(leader.get("provider", ""))
    base = {
        "agent_id": leader.get("agent_id"),
        "provider": provider,
        "model": leader.get("model"),
        "approval_mode": leader.get("approval_mode"),
        "api_backed": provider in ("deepseek", "openai-compatible"),
        "provider_backend": leader_provider_backend(provider),
        "provider_transport": leader_provider_transport(provider),
        "leader_backend": leader.get("leader_backend")
        or leader_backend_identity(provider, str(leader.get("model") or "")),
        "command_path": None,
        "doctor_contract": "agentdeck contract doctor",
        "controls": _leader_provider_controls(provider),
    }
    provider_env = {
        "deepseek": "DEEPSEEK_API_KEY",
        "openai-compatible": "AGENTDECK_LEADER_API_KEY",
    }
    if provider == "fake":
        return {
            **base,
            "supported": True,
            "ready": True,
            "missing_env": [],
            "detail": "fake provider is local and ready",
            "doctor_command": "agentdeck doctor",
            "setup_commands": _provider_setup_commands(provider),
        }
    cli_command = {
        "codex-cli": "codex",
        "claude-cli": "claude",
    }.get(provider)
    if cli_command is not None:
        command_path = _command_path(cli_command)
        ready = command_path is not None
        return {
            **base,
            "supported": True,
            "ready": ready,
            "missing_env": [],
            "detail": f"{cli_command} is available" if ready else f"{cli_command} is not found on PATH",
            "command_path": command_path,
            "doctor_command": "agentdeck doctor",
            "setup_commands": _provider_setup_commands(provider),
        }
    required_env = provider_env.get(provider)
    if required_env is None:
        return {
            **base,
            "supported": False,
            "ready": False,
            "missing_env": [],
            "detail": f"unsupported leader provider: {provider}",
            "doctor_command": "agentdeck doctor",
            "setup_commands": [],
        }
    missing_env = [] if os.environ.get(required_env) else [required_env]
    ready = not missing_env
    detail = f"{required_env} is set" if ready else f"{required_env} is not set; provider calls are disabled"
    return {
        **base,
        "supported": True,
        "ready": ready,
        "missing_env": missing_env,
        "detail": detail,
        "doctor_command": "agentdeck doctor",
        "setup_commands": _provider_setup_commands(provider),
    }


def _provider_setup_commands(provider: str) -> list[str]:
    if provider == "deepseek":
        return [
            'export DEEPSEEK_API_KEY="<your-deepseek-api-key>"',
            'export DEEPSEEK_BASE_URL="https://api.deepseek.com/v1"',
            'export DEEPSEEK_MODEL="deepseek-chat"',
        ]
    if provider == "openai-compatible":
        return [
            'export AGENTDECK_LEADER_API_KEY="<your-provider-api-key>"',
            'export AGENTDECK_LEADER_BASE_URL="https://api.example.com/v1"',
            'export AGENTDECK_LEADER_MODEL="<model-name>"',
        ]
    if provider == "codex-cli":
        return ["codex login", "codex doctor"]
    if provider == "claude-cli":
        return ["claude auth", "claude doctor"]
    return []


def _provider_for_setup_command(command: str) -> str | None:
    for provider, _model, _label in LEADER_PROVIDER_SWITCHES:
        if command in _provider_setup_commands(provider):
            return provider
    return None


def _control_registry_id_for_command(
    workbench_card: dict[str, object],
    *,
    scope: str,
    kind: str,
    command: str,
) -> str | None:
    registry = workbench_card.get("control_registry") if isinstance(workbench_card.get("control_registry"), list) else []
    for item in registry:
        if not isinstance(item, dict):
            continue
        if item.get("scope") == scope and item.get("kind") == kind and item.get("command") == command:
            control_id = item.get("control_id")
            return str(control_id) if isinstance(control_id, str) and control_id else None
    return None


def _leader_chat_provider_setup_card(
    *,
    target_provider: str,
    target_model: str,
    setup_commands: list[str],
    recommended_command: str,
    recommended_control_id: str | None,
    followup_switch_command: str,
    require_ready: bool,
    control_registry_workbench: dict[str, object],
) -> dict[str, object]:
    controls: list[dict[str, object]] = []
    for setup_command in setup_commands:
        controls.append(
            {
                "kind": "setup_provider",
                "label": "Run provider setup",
                "command": setup_command,
                "safety": "explicit_user",
                "enabled": True,
                "blocker": None,
                "control_id": _control_registry_id_for_command(
                    control_registry_workbench,
                    scope="provider",
                    kind="setup_provider",
                    command=setup_command,
                ),
            }
        )
    controls.append(
        {
            "kind": "guarded_set_provider" if require_ready else "set_provider",
            "label": "Switch Leader provider if ready" if require_ready else "Switch Leader provider",
            "command": followup_switch_command,
            "safety": "explicit_user",
            "enabled": True,
            "blocker": None,
        }
    )
    return {
        "mode": "provider_setup",
        "title": "Set up Leader provider",
        "target_provider": target_provider,
        "target_model": target_model,
        "setup_commands": setup_commands,
        "recommended_command": recommended_command,
        "recommended_control_id": recommended_control_id,
        "followup_switch_command": followup_switch_command,
        "require_ready": require_ready,
        "safety": "explicit_user",
        "requires_explicit_user": True,
        "mutates_config": False,
        "controls": controls,
    }


def _workbench_queue_card(
    project_view: dict[str, object], continue_card: dict[str, object], active_queue_source: str
) -> dict[str, object]:
    leader_actions = project_view.get("leader_actions") if isinstance(project_view.get("leader_actions"), dict) else {}
    approvals = project_view.get("approvals") if isinstance(project_view.get("approvals"), dict) else {}
    inbox = project_view.get("inbox") if isinstance(project_view.get("inbox"), dict) else {}
    leader_status = leader_actions.get("by_status") if isinstance(leader_actions.get("by_status"), dict) else {}
    return {
        "active_queue_source": active_queue_source,
        "next_command": continue_card.get("next_command"),
        "leader_actions": {
            "count": int(leader_actions.get("count", 0)),
            "pending": int(leader_status.get("pending", 0)),
            "recommended_action_id": leader_actions.get("recommended_action_id"),
            "command": "agentdeck leader actions",
        },
        "approvals": {
            "count": int(approvals.get("count", 0)),
            "pending": int(approvals.get("pending", 0)),
            "approved": int(approvals.get("approved", 0)),
            "command": "agentdeck approval list",
        },
        "inbox": {
            "total": int(inbox.get("total", 0)),
            "by_agent": inbox.get("by_agent", {}),
            "command_template": "agentdeck inbox --agent <agent_id>",
        },
        "refresh_command": "agentdeck workbench",
    }


def _workbench_role_card(project_view: dict[str, object]) -> dict[str, object]:
    agents = project_view.get("agents", [])
    role_agents = []
    if isinstance(agents, list):
        for agent in agents:
            if not isinstance(agent, dict):
                continue
            agent_id = str(agent.get("agent_id"))
            role = str(agent.get("role", ""))
            role_prompt = str(agent.get("role_prompt", ""))
            role_agents.append(
                {
                    "agent_id": agent_id,
                    "role": role,
                    "provider": agent.get("provider"),
                    "workspace_mode": agent.get("workspace_mode"),
                    "role_prompt": role_prompt,
                    "assign_command": _agent_assign_role_command(agent_id, role, role_prompt),
                    "controls": _role_agent_controls(agent_id),
                }
            )
    return {
        "count": len(role_agents),
        "agents": role_agents,
        "assign_command_template": (
            "agentdeck agent assign-role --agent <agent_id> --role <role> --role-prompt <role_prompt>"
        ),
    }


def _workbench_worker_lifecycle_card(project_view: dict[str, object]) -> dict[str, object]:
    agents = project_view.get("agents", [])
    messages = project_view.get("messages") if isinstance(project_view.get("messages"), dict) else {}
    jobs = project_view.get("jobs") if isinstance(project_view.get("jobs"), dict) else {}
    replies = project_view.get("replies") if isinstance(project_view.get("replies"), dict) else {}
    artifacts = project_view.get("artifacts") if isinstance(project_view.get("artifacts"), dict) else {}
    inbox = project_view.get("inbox") if isinstance(project_view.get("inbox"), dict) else {}
    inbox_heads = inbox.get("heads") if isinstance(inbox.get("heads"), dict) else {}
    inbox_by_agent = inbox.get("by_agent") if isinstance(inbox.get("by_agent"), dict) else {}
    message_items = [item for item in _summary_items(messages) if isinstance(item, dict)]
    job_items = [item for item in _summary_items(jobs) if isinstance(item, dict)]
    reply_items = [item for item in _summary_items(replies) if isinstance(item, dict)]
    artifact_items = [item for item in _summary_items(artifacts) if isinstance(item, dict)]
    items: list[dict[str, object]] = []
    by_stage: dict[str, int] = {}
    if isinstance(agents, list):
        for agent in agents:
            if not isinstance(agent, dict):
                continue
            agent_id = str(agent.get("agent_id"))
            runtime = agent.get("runtime") if isinstance(agent.get("runtime"), dict) else {}
            runtime_status = str(runtime.get("status", "unknown"))
            pane_id = runtime.get("pane_id")
            inbox_head = inbox_heads.get(agent_id) if isinstance(inbox_heads, dict) else None
            inbox_head = inbox_head if isinstance(inbox_head, dict) else {}
            active_message = _latest_agent_message(agent_id, message_items, preferred_message_id=inbox_head.get("message_id"))
            active_message_id = active_message.get("message_id") if active_message else inbox_head.get("message_id")
            active_job = _latest_agent_job(agent_id, job_items, active_message_id)
            latest_reply = _latest_agent_reply(agent_id, reply_items, active_message_id)
            pending_inbox_count = _safe_int(inbox_by_agent.get(agent_id), default=0)
            artifact_count = _agent_artifact_count(agent_id, artifact_items)
            lifecycle_stage = _worker_lifecycle_stage(
                runtime_status=runtime_status,
                pending_inbox_count=pending_inbox_count,
                latest_reply=latest_reply,
                active_job=active_job,
                active_message=active_message,
            )
            trace_id = active_message_id or active_job.get("job_id") or latest_reply.get("reply_id") or inbox_head.get("inbox_id")
            trace_command = f"agentdeck trace --id {trace_id}" if trace_id else None
            inbox_command = f"agentdeck inbox --agent {agent_id}"
            terminal_command = f"agentdeck agent terminal --agent {agent_id}"
            capture_command = f"agentdeck agent capture --agent {agent_id} --lines 200"
            item = {
                "agent_id": agent_id,
                "role": agent.get("role"),
                "provider": agent.get("provider"),
                "runtime_status": runtime_status,
                "pane_id": pane_id,
                "lifecycle_stage": lifecycle_stage,
                "active_message_id": active_message_id,
                "active_job_id": active_job.get("job_id"),
                "latest_reply_id": latest_reply.get("reply_id"),
                "artifact_count": artifact_count,
                "pending_inbox_count": pending_inbox_count,
                "trace_command": trace_command,
                "inbox_command": inbox_command,
                "terminal_command": terminal_command,
                "capture_command": capture_command,
                "controls": _worker_lifecycle_controls(
                    trace_command=trace_command,
                    inbox_command=inbox_command,
                    terminal_command=terminal_command,
                    capture_command=capture_command,
                    can_capture=runtime_status == "running" and pane_id is not None,
                ),
            }
            items.append(item)
            by_stage[lifecycle_stage] = by_stage.get(lifecycle_stage, 0) + 1
    return {
        "mode": "worker_lifecycle",
        "title": "Worker lifecycle",
        "source_command": "agentdeck workbench",
        "count": len(items),
        "by_stage": by_stage,
        "items": items,
        "controls": [
            _control(
                kind="inspect",
                label="Refresh worker lifecycle",
                command="agentdeck workbench",
                safety="inspect",
            )
        ],
    }


def _latest_agent_message(
    agent_id: str, message_items: list[dict[str, object]], preferred_message_id: object = None
) -> dict[str, object]:
    if preferred_message_id:
        for message in reversed(message_items):
            if message.get("message_id") == preferred_message_id:
                return message
    for message in reversed(message_items):
        if message.get("to_agent") == agent_id:
            return message
    return {}


def _latest_agent_job(
    agent_id: str, job_items: list[dict[str, object]], active_message_id: object = None
) -> dict[str, object]:
    if active_message_id:
        for job in reversed(job_items):
            if job.get("message_id") == active_message_id and job.get("agent_id") == agent_id:
                return job
    for job in reversed(job_items):
        if job.get("agent_id") == agent_id:
            return job
    return {}


def _latest_agent_reply(
    agent_id: str, reply_items: list[dict[str, object]], active_message_id: object = None
) -> dict[str, object]:
    if active_message_id:
        for reply in reversed(reply_items):
            if reply.get("message_id") == active_message_id and reply.get("from_agent") == agent_id:
                return reply
    for reply in reversed(reply_items):
        if reply.get("from_agent") == agent_id:
            return reply
    return {}


def _agent_artifact_count(agent_id: str, artifact_items: list[dict[str, object]]) -> int:
    return sum(1 for artifact in artifact_items if artifact.get("from_agent") == agent_id)


def _safe_int(value: object, *, default: int = 0) -> int:
    if isinstance(value, bool):
        return int(value)
    if isinstance(value, int):
        return value
    return default


def _worker_lifecycle_stage(
    *,
    runtime_status: str,
    pending_inbox_count: int,
    latest_reply: dict[str, object],
    active_job: dict[str, object],
    active_message: dict[str, object],
) -> str:
    if runtime_status == "released":
        return "released"
    if pending_inbox_count > 0:
        return "inbox_pending"
    if latest_reply:
        return "reply_recorded"
    if active_job:
        return str(active_job.get("status") or "job_active")
    if active_message:
        return "task_dispatched"
    return "idle"


def _worker_lifecycle_controls(
    *,
    trace_command: str | None,
    inbox_command: str,
    terminal_command: str,
    capture_command: str,
    can_capture: bool,
) -> list[dict[str, object]]:
    return [
        _control(
            kind="trace",
            label="Trace active task",
            command=trace_command,
            safety="inspect",
            enabled=trace_command is not None,
            blocker=None if trace_command is not None else "no active task",
        ),
        _control(
            kind="inbox",
            label="Inspect inbox",
            command=inbox_command,
            safety="inspect",
        ),
        _control(
            kind="terminal",
            label="Open terminal",
            command=terminal_command,
            safety="inspect",
        ),
        _control(
            kind="capture",
            label="Capture pane output",
            command=capture_command,
            safety="inspect",
            enabled=can_capture,
            blocker=None if can_capture else "agent is not running",
        ),
    ]


def _workbench_review_gate_card(project_view: dict[str, object]) -> dict[str, object]:
    agents = project_view.get("agents") if isinstance(project_view.get("agents"), list) else []
    replies = project_view.get("replies") if isinstance(project_view.get("replies"), dict) else {}
    artifacts = project_view.get("artifacts") if isinstance(project_view.get("artifacts"), dict) else {}
    reply_items = [item for item in _summary_items(replies) if isinstance(item, dict)]
    artifact_items = [item for item in _summary_items(artifacts) if isinstance(item, dict)]
    artifact_count = len(artifact_items)
    code_reviewer = _review_gate_agent(agents, preferred=("code_reviewer", "reviewer"))
    round_reviewer = _review_gate_agent(agents, preferred=("round_reviewer",))
    code_review = _review_gate_stage(
        stage="code_review",
        agent=code_reviewer,
        replies=reply_items,
        artifact_count=artifact_count,
        missing_blocker="code_reviewer is not configured",
        waiting_blocker="waiting for code review reply",
    )
    round_review = _review_gate_stage(
        stage="round_review",
        agent=round_reviewer,
        replies=reply_items,
        artifact_count=artifact_count,
        missing_blocker="round_reviewer is not configured",
        waiting_blocker="waiting for round review reply",
        prerequisite_ready=code_review.get("status") == "ready",
        prerequisite_blocker="code review is not ready",
    )
    status, reason = _review_gate_status(code_review, round_review, artifact_count)
    return {
        "mode": "review_gate",
        "title": "Review gate",
        "source_command": "agentdeck workbench",
        "status": status,
        "reason": reason,
        "can_release": status == "ready",
        "artifact_count": artifact_count,
        "review_reply_count": _review_gate_reply_count(reply_items, code_reviewer, round_reviewer),
        "code_review": code_review,
        "round_review": round_review,
        "controls": [
            _control(
                kind="inspect",
                label="Inspect review gate",
                command="agentdeck workbench",
                safety="inspect",
            ),
            _control(
                kind="assign_code_reviewer",
                label="Assign code reviewer",
                command=(
                    "agentdeck agent assign-role --agent <agent_id> --role code_reviewer "
                    "--role-prompt <role_prompt>"
                ),
                safety="explicit_user",
                enabled=False,
                blocker="requires agent_id and role_prompt",
            ),
            _control(
                kind="assign_round_reviewer",
                label="Assign round reviewer",
                command=(
                    "agentdeck agent assign-role --agent <agent_id> --role round_reviewer "
                    "--role-prompt <role_prompt>"
                ),
                safety="explicit_user",
                enabled=False,
                blocker="requires agent_id and role_prompt",
            ),
        ],
    }


def _review_gate_agent(agents: list[object], *, preferred: tuple[str, ...]) -> dict[str, object]:
    for key in preferred:
        for agent in agents:
            if not isinstance(agent, dict):
                continue
            agent_id = str(agent.get("agent_id") or "")
            role = str(agent.get("role") or "")
            if agent_id == key or role == key:
                return agent
    return {}


def _review_gate_stage(
    *,
    stage: str,
    agent: dict[str, object],
    replies: list[dict[str, object]],
    artifact_count: int,
    missing_blocker: str,
    waiting_blocker: str,
    prerequisite_ready: bool = True,
    prerequisite_blocker: str | None = None,
) -> dict[str, object]:
    agent_id = str(agent.get("agent_id")) if agent else None
    role = agent.get("role") if agent else None
    latest_reply = _latest_agent_reply(agent_id, replies) if agent_id else {}
    trace_command = f"agentdeck trace --id {latest_reply.get('reply_id')}" if latest_reply.get("reply_id") else None
    inbox_command = f"agentdeck inbox --agent {agent_id}" if agent_id else None
    status = "ready"
    blocker = None
    if not agent_id:
        status = "missing_reviewer"
        blocker = missing_blocker
    elif artifact_count == 0:
        status = "waiting_for_artifacts"
        blocker = "waiting for artifacts"
    elif not prerequisite_ready:
        status = "blocked"
        blocker = prerequisite_blocker or "prerequisite is not ready"
    elif not latest_reply:
        status = "waiting_for_review"
        blocker = waiting_blocker
    return {
        "stage": stage,
        "agent_id": agent_id,
        "role": role,
        "status": status,
        "latest_reply_id": latest_reply.get("reply_id"),
        "trace_command": trace_command,
        "inbox_command": inbox_command,
        "blocker": blocker,
        "controls": _review_gate_stage_controls(
            stage, trace_command, inbox_command, blocker
        ),
    }


def _review_gate_stage_controls(
    stage: str,
    trace_command: str | None,
    inbox_command: str | None,
    blocker: str | None,
) -> list[dict[str, object]]:
    stage_label = {
        "code_review": "code review",
        "round_review": "round review",
    }[stage]
    return [
        _control(
            kind="trace",
            label=f"Trace {stage_label}",
            command=trace_command,
            safety="inspect",
            enabled=trace_command is not None,
            blocker=None if trace_command is not None else blocker or "no review reply",
        ),
        _control(
            kind="inbox",
            label=f"Inspect {stage_label.replace(' review', ' reviewer')} inbox",
            command=inbox_command,
            safety="inspect",
            enabled=inbox_command is not None,
            blocker=None if inbox_command is not None else blocker or "reviewer is not configured",
        ),
    ]


def _review_gate_status(
    code_review: dict[str, object], round_review: dict[str, object], artifact_count: int
) -> tuple[str, str | None]:
    if artifact_count == 0:
        return "blocked", "waiting for artifacts"
    if code_review.get("status") != "ready":
        return "blocked", str(code_review.get("blocker") or "code review is not ready")
    if round_review.get("status") != "ready":
        return "blocked", str(round_review.get("blocker") or "round review is not ready")
    return "ready", None


def _review_gate_reply_count(
    replies: list[dict[str, object]], code_reviewer: dict[str, object], round_reviewer: dict[str, object]
) -> int:
    reviewer_ids = {
        str(agent.get("agent_id"))
        for agent in (code_reviewer, round_reviewer)
        if isinstance(agent, dict) and agent.get("agent_id")
    }
    return sum(1 for reply in replies if reply.get("from_agent") in reviewer_ids)


def _workbench_release_preview_card(
    review_gate_card: dict[str, object], project_view: dict[str, object]
) -> dict[str, object]:
    releases = project_view.get("releases") if isinstance(project_view.get("releases"), dict) else {}
    release_items = [item for item in _summary_items(releases) if isinstance(item, dict)]
    release_count = len(release_items)
    latest_release_id = release_items[-1].get("release_id") if release_items else None
    gate_ready = review_gate_card.get("can_release") is True
    code_review = (
        review_gate_card.get("code_review") if isinstance(review_gate_card.get("code_review"), dict) else {}
    )
    round_review = (
        review_gate_card.get("round_review") if isinstance(review_gate_card.get("round_review"), dict) else {}
    )
    already_released = gate_ready and any(
        item.get("code_review_reply_id") == code_review.get("latest_reply_id")
        and item.get("round_review_reply_id") == round_review.get("latest_reply_id")
        for item in release_items
    )
    can_release = gate_ready and not already_released
    if already_released:
        status = "released"
        reason = "round already released"
    elif gate_ready:
        status = "ready"
        reason = None
    else:
        status = "blocked"
        reason = str(review_gate_card.get("reason") or "review gate is not ready")
    release_command = "agentdeck release --confirm" if status == "ready" else None
    next_round_command = "agentdeck leader plan --task <goal>" if status in {"ready", "released"} else None
    if status == "ready":
        release_label = "Release this round"
        next_round_label = "Plan next round"
    elif status == "released":
        release_label = "Round released"
        next_round_label = "Plan next round"
    else:
        release_label = "Preview release"
        next_round_label = "Preview next round"
    return {
        "mode": "release_preview",
        "title": "Release / next-round preview",
        "source_command": "agentdeck workbench",
        "status": status,
        "reason": reason,
        "review_gate_status": review_gate_card.get("status"),
        "can_release": can_release,
        "already_released": already_released,
        "release_count": release_count,
        "latest_release_id": latest_release_id,
        "next_command": release_command,
        "release_command": release_command,
        "next_round_command": next_round_command,
        "controls": [
            _control(
                kind="inspect_review_gate",
                label="Inspect review gate",
                command="agentdeck workbench",
                safety="inspect",
            ),
            _control(
                kind="release_preview",
                label=release_label,
                command=release_command,
                safety="explicit_user",
                enabled=status == "ready",
                blocker=None if status == "ready" else reason,
            ),
            _control(
                kind="next_round_preview",
                label=next_round_label,
                command=next_round_command,
                safety="explicit_user",
                enabled=False,
                blocker="requires goal text" if status in {"ready", "released"} else reason,
            ),
        ],
    }


def _golden_demo_step(
    *,
    step_id: str,
    title: str,
    status: str,
    command: str,
    enabled: bool,
    blocker: str | None,
    safety: str,
    description: str,
    checks: list[str],
) -> dict[str, object]:
    return {
        "step_id": step_id,
        "title": title,
        "status": status,
        "command": command,
        "enabled": enabled,
        "blocker": blocker,
        "safety": safety,
        "description": description,
        "checks": checks,
    }


def _golden_demo_payload(config: ProjectConfig, store: StateStore) -> dict[str, object]:
    project_view = asdict(store.project_view(config))
    provider_health = _workbench_provider_health(project_view)
    provider_ready = provider_health.get("ready") is True
    review_gate_card = _workbench_review_gate_card(project_view)
    release_ready = review_gate_card.get("can_release") is True

    agents = project_view.get("agents") if isinstance(project_view.get("agents"), list) else []
    running_agents = [
        agent
        for agent in agents
        if isinstance(agent, dict)
        and isinstance(agent.get("runtime"), dict)
        and agent["runtime"].get("status") == "running"
    ]
    plans_summary = project_view.get("plans") if isinstance(project_view.get("plans"), dict) else {}
    approvals_summary = project_view.get("approvals") if isinstance(project_view.get("approvals"), dict) else {}
    messages_summary = project_view.get("messages") if isinstance(project_view.get("messages"), dict) else {}
    replies_summary = project_view.get("replies") if isinstance(project_view.get("replies"), dict) else {}
    releases_summary = project_view.get("releases") if isinstance(project_view.get("releases"), dict) else {}
    plans = [item for item in _summary_items(plans_summary) if isinstance(item, dict)]
    approvals = [item for item in _summary_items(approvals_summary) if isinstance(item, dict)]
    pending_approvals = [item for item in approvals if item.get("status") == "pending"]
    approved_approvals = _workbench_approved_approval_items(project_view)
    dispatchable_approval = next(
        (
            approval
            for approval in approved_approvals
            if _project_view_agent_is_running(project_view, approval.get("agent_id"))
        ),
        None,
    )
    messages = [item for item in _summary_items(messages_summary) if isinstance(item, dict)]
    replies = [item for item in _summary_items(replies_summary) if isinstance(item, dict)]
    releases = [item for item in _summary_items(releases_summary) if isinstance(item, dict)]

    latest_plan = plans[-1] if plans else {}
    latest_approval = approvals[-1] if approvals else {}
    pending_approval = pending_approvals[0] if pending_approvals else {}
    latest_message = messages[-1] if messages else {}
    latest_reply = replies[-1] if replies else {}
    latest_release = releases[-1] if releases else {}
    plan_id = latest_plan.get("plan_id")
    approval_id = latest_approval.get("approval_id")
    pending_approval_id = pending_approval.get("approval_id")
    dispatch_approval_id = dispatchable_approval.get("approval_id") if dispatchable_approval else None
    message_id = latest_message.get("message_id")
    message_agent_id = latest_message.get("to_agent")

    current_status = "ready_to_plan"
    next_command = "agentdeck leader plan --task <task>"
    if releases:
        current_status = "released"
        next_command = "agentdeck workbench"
    elif release_ready or replies:
        current_status = "ready_for_review_gate"
        next_command = "agentdeck workbench"
    elif messages:
        current_status = "waiting_for_reply"
        next_command = f"agentdeck capture-reply --agent {message_agent_id} --message-id {message_id}"
    elif dispatchable_approval:
        current_status = "ready_to_dispatch"
        next_command = f"agentdeck approval dispatch --approval-id {dispatch_approval_id}"
    elif approved_approvals:
        current_status = "worker_setup_required"
        next_command = "agentdeck agent ready"
    elif pending_approvals:
        current_status = "waiting_for_approval"
        next_command = f"agentdeck approval approve --approval-id {pending_approval_id}"
    elif approvals:
        current_status = "waiting_for_approval"
        next_command = "agentdeck approval list"
    elif plans:
        current_status = "plan_ready"
        next_command = f"agentdeck approval create-from-plan --plan-id {plan_id}"
    elif not provider_ready:
        current_status = "provider_setup_required"
        next_command = "agentdeck doctor"

    provider_blocker = None if provider_ready else str(provider_health.get("detail") or "leader provider is not ready")
    workers_ready = len(running_agents) > 0
    plan_created = bool(plans)
    approval_created = bool(approvals)
    approval_ready = bool(approved_approvals)
    dispatch_ready = dispatchable_approval is not None
    dispatched = bool(messages)
    reply_recorded = bool(replies)
    released = bool(releases)

    approval_command = "agentdeck approval create-from-plan --plan-id <plan_id>"
    approval_step_safety = "explicit_user"
    if pending_approval_id:
        approval_command = f"agentdeck approval approve --approval-id {pending_approval_id}"
        approval_step_safety = "explicit_runtime"
    elif plan_id:
        approval_command = f"agentdeck approval create-from-plan --plan-id {plan_id}"
    dispatch_command = "agentdeck approval dispatch --approval-id <approval_id>"
    if dispatch_approval_id:
        dispatch_command = f"agentdeck approval dispatch --approval-id {dispatch_approval_id}"
    reply_command = (
        f"agentdeck capture-reply --agent {message_agent_id} --message-id {message_id}"
        if message_agent_id and message_id
        else "agentdeck capture-reply --agent <agent_id> --message-id <message_id>"
    )

    steps = [
        _golden_demo_step(
            step_id="doctor",
            title="Inspect environment",
            status="done" if provider_ready else "ready",
            command="agentdeck doctor",
            enabled=True,
            blocker=None,
            safety="inspect",
            description="Check tmux and configured Leader provider readiness.",
            checks=["tmux available", "configured Leader readiness is visible"],
        ),
        _golden_demo_step(
            step_id="leader_provider",
            title="Confirm Leader provider",
            status="done" if provider_ready else "blocked",
            command="agentdeck doctor",
            enabled=provider_ready,
            blocker=provider_blocker,
            safety="inspect",
            description="Ensure the configured Leader provider can create the demo plan.",
            checks=[str(provider_health.get("provider")), str(provider_health.get("detail"))],
        ),
        _golden_demo_step(
            step_id="workers",
            title="Inspect worker panes",
            status="done" if workers_ready else "inspect",
            command="agentdeck agent ready",
            enabled=True,
            blocker=None,
            safety="inspect",
            description="Review worker startup readiness before dispatching approved work.",
            checks=[f"{len(running_agents)} running agent(s)", f"{len(agents)} configured agent(s)"],
        ),
        _golden_demo_step(
            step_id="plan",
            title="Create the demo plan",
            status="done" if plan_created else "waiting_for_input",
            command="agentdeck leader plan --task <task>",
            enabled=False,
            blocker="plan already exists" if plan_created else "requires task text",
            safety="explicit_user",
            description="Ask the Leader to create a plan without dispatching workers.",
            checks=["plan is recorded", "approval remains explicit"],
        ),
        _golden_demo_step(
            step_id="approval",
            title="Create approvals",
            status=(
                "done"
                if approval_ready or dispatched or reply_recorded or released
                else "ready"
                if pending_approvals or plan_created
                else "blocked"
            ),
            command=approval_command,
            enabled=(bool(pending_approvals) or plan_created)
            and not (approval_ready or dispatched or reply_recorded or released),
            blocker=(
                "approval already approved"
                if approval_ready
                else "approval already dispatched"
                if dispatched or reply_recorded or released
                else None
                if pending_approvals or plan_created
                else "requires a plan"
            ),
            safety=approval_step_safety,
            description="Convert the saved plan into explicit human approval items.",
            checks=["approval queue is visible", "dispatch remains explicit"],
        ),
        _golden_demo_step(
            step_id="dispatch",
            title="Dispatch approved work",
            status="done" if dispatched or reply_recorded or released else "ready" if dispatch_ready else "blocked",
            command=dispatch_command,
            enabled=dispatch_ready and not (dispatched or reply_recorded or released),
            blocker=(
                "work already dispatched"
                if dispatched or reply_recorded or released
                else None
                if dispatch_ready
                else "requires running worker pane"
                if approval_ready
                else "approval is not approved"
                if approval_created
                else "requires approved work and running worker panes"
            ),
            safety="explicit_runtime",
            description="Send an approved item to a worker pane.",
            checks=["message is recorded", "worker prompt provenance is visible"],
        ),
        _golden_demo_step(
            step_id="reply",
            title="Capture worker reply",
            status="done" if reply_recorded or released else "ready" if dispatched else "blocked",
            command=reply_command,
            enabled=dispatched and not (reply_recorded or released),
            blocker=(
                "reply already recorded"
                if reply_recorded or released
                else None
                if dispatched
                else "requires a dispatched message"
            ),
            safety="explicit_runtime",
            description="Capture the worker response for the message ledger.",
            checks=["reply is recorded", "trace links message, job, and reply"],
        ),
        _golden_demo_step(
            step_id="review_gate",
            title="Inspect review gate",
            status="done" if release_ready else "ready" if reply_recorded else "blocked",
            command="agentdeck workbench",
            enabled=True,
            blocker=None if reply_recorded or release_ready else "requires a worker reply",
            safety="inspect",
            description="Inspect artifacts and reviewer replies before release.",
            checks=[str(review_gate_card.get("status")), str(review_gate_card.get("reason") or "review gate ready")],
        ),
        _golden_demo_step(
            step_id="release",
            title="Release the reviewed round",
            status="done" if released else "ready" if release_ready else "blocked",
            command="agentdeck release --confirm",
            enabled=release_ready and not released,
            blocker=(
                f"release already recorded: {latest_release.get('release_id')}"
                if released
                else None
                if release_ready
                else str(review_gate_card.get("reason") or "review gate is not ready")
            ),
            safety="explicit_user",
            description="Record the round release after the review gate is ready.",
            checks=["review gate can_release is true", "release is explicit"],
        ),
        _golden_demo_step(
            step_id="inspect",
            title="Inspect demo state",
            status="inspect",
            command="agentdeck workbench",
            enabled=True,
            blocker=None,
            safety="inspect",
            description="Refresh the read-only workbench and contract-backed status surfaces.",
            checks=["status is inspect-only", "workbench cards show provenance"],
        ),
    ]

    return {
        "ok": True,
        "mode": "golden_demo",
        "demo_name": "golden",
        "summary": {
            "project": project_view.get("project"),
            "provider_ready": provider_ready,
            "provider": provider_health.get("provider"),
            "configured_agents": len(agents),
            "running_agents": len(running_agents),
            "plans": len(plans),
            "approvals": len(approvals),
            "messages": len(messages),
            "replies": len(replies),
            "releases": len(releases),
            "latest_plan_id": plan_id,
            "latest_approval_id": approval_id,
            "latest_message_id": message_id,
            "latest_reply_id": latest_reply.get("reply_id"),
            "latest_release_id": latest_release.get("release_id"),
        },
        "current_status": current_status,
        "next_command": next_command,
        "recommended_task": GOLDEN_DEMO_TASK,
        "steps": steps,
        "inspection_commands": [
            "agentdeck status",
            "agentdeck workbench",
            "agentdeck dashboard",
            "agentdeck tui",
        ],
        "safety": "inspect",
        "source_command": "agentdeck demo golden",
    }


def _role_topology_review_stage_by_agent(
    review_gate_card: dict[str, object],
) -> dict[str, dict[str, object]]:
    stage_by_agent: dict[str, dict[str, object]] = {}
    for stage_name in ("code_review", "round_review"):
        stage = review_gate_card.get(stage_name) if isinstance(review_gate_card.get(stage_name), dict) else {}
        agent_id = stage.get("agent_id")
        if agent_id and agent_id not in stage_by_agent:
            stage_by_agent[str(agent_id)] = stage
    return stage_by_agent


def _role_topology_review_overlay(stage: dict[str, object]) -> tuple[str, object]:
    stage_status = stage.get("status")
    if stage_status == "ready":
        return "reviewed", None
    if stage_status == "waiting_for_review":
        return "reviewing", None
    return "blocked", stage.get("blocker")


def _workbench_role_topology_card(
    project_view: dict[str, object], review_gate_card: dict[str, object]
) -> dict[str, object]:
    leader = project_view.get("leader") if isinstance(project_view.get("leader"), dict) else {}
    coordination_roles = (
        leader.get("coordination_roles") if isinstance(leader.get("coordination_roles"), list) else []
    )
    plans = project_view.get("plans") if isinstance(project_view.get("plans"), dict) else {}
    plan_count = _safe_int(plans.get("count"), default=0)
    leader_actions = (
        project_view.get("leader_actions") if isinstance(project_view.get("leader_actions"), dict) else {}
    )
    pending_action = any(
        isinstance(item, dict) and item.get("status") == "pending"
        for item in _summary_items(leader_actions)
    )
    approvals = project_view.get("approvals") if isinstance(project_view.get("approvals"), dict) else {}
    pending_approval = _safe_int(approvals.get("pending"), default=0) > 0
    releases = project_view.get("releases") if isinstance(project_view.get("releases"), dict) else {}
    release_count = _safe_int(releases.get("count"), default=0)
    logical_inspect = {
        "frontdesk": ("agentdeck leader chat-history", "Inspect intake history"),
        "planner": ("agentdeck plan list", "Inspect plans"),
        "orchestrator": ("agentdeck leader actions", "Inspect Leader actions"),
    }
    roles: list[dict[str, object]] = []
    logical_count = 0
    for role in coordination_roles:
        if not isinstance(role, dict):
            continue
        logical_count += 1
        role_id = str(role.get("role_id"))
        logical_blocker: object = None
        if role_id == "planner":
            status = "planning" if plan_count > 0 else "idle"
        elif role_id == "orchestrator":
            if pending_approval:
                status = "waiting_for_approval"
                logical_blocker = "waiting for human approval"
            elif pending_action:
                status = "coordinating"
            elif release_count > 0:
                status = "released"
            else:
                status = "idle"
        else:
            status = "ready"
        inspect_command, inspect_label = logical_inspect.get(
            role_id, ("agentdeck leader status", "Inspect Leader status")
        )
        roles.append(
            {
                "role_id": role_id,
                "label": role.get("label"),
                "agent_id": None,
                "kind": "logical_role",
                "provider": role.get("provider"),
                "lifecycle": role.get("lifecycle"),
                "runtime_kind": "logical_role",
                "pane_backed": False,
                "pane_id": None,
                "status": status,
                "blocker": logical_blocker,
                "next_command": inspect_command,
                "controls": [
                    _control(
                        kind="inspect",
                        label=inspect_label,
                        command=inspect_command,
                        safety="inspect",
                    )
                ],
            }
        )
    worker_card = _workbench_worker_lifecycle_card(project_view)
    worker_items = worker_card.get("items") if isinstance(worker_card.get("items"), list) else []
    review_stage_by_agent = _role_topology_review_stage_by_agent(review_gate_card)
    worker_count = 0
    for item in worker_items:
        if not isinstance(item, dict):
            continue
        worker_count += 1
        agent_id = item.get("agent_id")
        runtime_status = str(item.get("runtime_status") or "unknown")
        pane_id = item.get("pane_id")
        inbox_command = item.get("inbox_command")
        status: object = item.get("lifecycle_stage")
        blocker: object = None
        review_stage = review_stage_by_agent.get(str(agent_id)) if agent_id else None
        if isinstance(review_stage, dict):
            status, blocker = _role_topology_review_overlay(review_stage)
        roles.append(
            {
                "role_id": item.get("role") or agent_id,
                "label": item.get("role") or agent_id,
                "agent_id": agent_id,
                "kind": "worker",
                "provider": item.get("provider"),
                "lifecycle": runtime_status,
                "runtime_kind": "worker_pane",
                "pane_backed": runtime_status == "running" and pane_id is not None,
                "pane_id": pane_id,
                "status": status,
                "blocker": blocker,
                "next_command": inbox_command,
                "controls": [
                    _control(
                        kind="inspect",
                        label="Inspect mailbox",
                        command=inbox_command,
                        safety="inspect",
                    )
                ],
            }
        )
    by_status: dict[str, int] = {}
    blocked_count = 0
    for role in roles:
        status_value = str(role.get("status"))
        by_status[status_value] = by_status.get(status_value, 0) + 1
        if role.get("blocker"):
            blocked_count += 1
    return {
        "mode": "role_topology",
        "title": "Role topology",
        "source_command": "agentdeck workbench",
        "count": logical_count + worker_count,
        "logical_role_count": logical_count,
        "worker_role_count": worker_count,
        "by_status": by_status,
        "blocked_count": blocked_count,
        "roles": roles,
        "controls": [
            _control(
                kind="inspect",
                label="Inspect role topology",
                command="agentdeck workbench",
                safety="inspect",
            )
        ],
    }


def _role_bindings_inspect(label: str, command: object, *, enabled: bool = True, blocker: object = None) -> dict[str, object]:
    return _control(
        kind="inspect", label=label, command=command, safety="inspect", enabled=enabled, blocker=blocker
    )


def _role_bindings_worker_controls(
    agent_id: str | None, runtime_status: str | None
) -> list[dict[str, object]]:
    if not agent_id:
        return [_role_bindings_inspect("Inspect agents", "agentdeck agent list")]
    # `agent_id` is free-form in `[[agents]]`, so an interpolated command can
    # come out looking like a `<placeholder>` template. A control carrying `<`
    # must never be enabled — the registry rule that catches placeholder
    # commands cannot tell the two apart, and a half-broken control would take
    # the whole read-only card (and `workbench`, and everything fed by it) down
    # with it. Show the command, disable it, and say why.
    placeholder_blocker = (
        f"agent id {agent_id!r} contains '<', which reads as a placeholder command; "
        "rename the agent in [[agents]] to use this control"
    )
    literal = "<" in agent_id
    running = runtime_status == "running"
    terminal_command = f"agentdeck agent terminal --agent {agent_id}" if running else None
    return [
        _role_bindings_inspect(
            "Inspect mailbox",
            f"agentdeck inbox --agent {agent_id}",
            enabled=not literal,
            blocker=placeholder_blocker if literal else None,
        ),
        _control(
            kind="terminal",
            label="Open terminal",
            command=terminal_command,
            safety="inspect",
            enabled=running and not literal,
            blocker=(
                placeholder_blocker
                if literal and running
                else None
                if running
                else "agent is not running"
            ),
        ),
    ]


def _role_bindings_worker_layer(
    bindings: dict[str, dict[str, object]], layer: str
) -> tuple[str | None, str, list[str], list[dict[str, object]]]:
    """Project one layer out of the one-pass worker resolution."""
    resolved = bindings.get(layer) or {}
    agent_id = resolved.get("agent_id")
    candidates = resolved.get("candidates")
    conflicts = resolved.get("conflicts")
    return (
        agent_id if isinstance(agent_id, str) else None,
        str(resolved.get("binding_status") or "unbound"),
        list(candidates) if isinstance(candidates, list) else [],
        list(conflicts) if isinstance(conflicts, list) else [],
    )


def _role_bindings_collision_blocker(conflicts: list[dict[str, object]]) -> str | None:
    """Name a cross-layer role collision, or `None` when there is none.

    A single agent whose free-text role reads as several north-star layers is
    ambiguous evidence for each of them: binding it would either send work to
    the wrong worker or let one worker review its own work. The only fix is a
    human editing the role text, so the blocker says exactly that.
    """
    described = [
        f"{conflict.get('agent_id')} reads as both the "
        + " and ".join(str(layer) for layer in conflict.get("layers") or [])
        + " layers"
        for conflict in conflicts
        if isinstance(conflict, dict)
    ]
    if not described:
        return None
    return (
        "; ".join(described)
        + "; disambiguate the role text in [[agents]] so each layer matches one agent"
    )


def _role_bindings_card(config: ProjectConfig, project_view: dict[str, object]) -> dict[str, object]:
    """Derive the north-star six-layer binding map.

    Read-only: it reuses the ProjectView `agents[]` runtime projection (never
    tmux), the already-normalized Leader backend provenance
    (`leader_backend_identity`) and the existing `[leader]` fallback rules
    (`resolved_planner_backend` / `resolved_orchestrator_backend`). It adds no
    state source, calls no provider, writes nothing. The topology is an
    observation surface, not an authorization: it changes no gate.
    """
    raw_agents = project_view.get("agents")
    agents = [agent for agent in raw_agents if isinstance(agent, dict)] if isinstance(raw_agents, list) else []
    agent_rows = [
        {"agent_id": str(agent.get("agent_id")), "role": str(agent.get("role") or "")}
        for agent in agents
        if agent.get("agent_id")
    ]
    by_agent = {str(agent.get("agent_id")): agent for agent in agents if agent.get("agent_id")}

    planner_provider, planner_model = resolved_planner_backend(config.leader)
    orchestrator_provider, orchestrator_model = resolved_orchestrator_backend(config.leader)
    logical_backends = {
        "planner": (planner_provider, planner_model),
        "orchestrator": (orchestrator_provider, orchestrator_model),
    }
    logical_controls = {
        "planner": ("Inspect plans", "agentdeck plan list"),
        "orchestrator": ("Inspect Leader actions", "agentdeck leader actions"),
    }

    reviewers = tuple(config.review.reviewers)
    round_reviewer = config.review.round_reviewer
    # Resolved in one pass so a role reading as two layers is visible as the
    # ambiguous evidence it is, instead of quietly binding whichever layer asks.
    worker_bindings = resolve_worker_roles(agent_rows)

    roles: list[dict[str, object]] = []
    for spec in ROLE_SPECS:
        role_name = spec["role"]
        binding_kind = spec["binding_kind"]
        agent_id: str | None = None
        provider: object = None
        model: object = None
        backend: object = None
        transport: object = None
        runtime_status: object = None
        pane_id: object = None
        blocker: object = None
        candidates: list[str] = []
        # Membership, not ambiguity: only a configured `[review] reviewers`
        # group fills this in, and it stays empty for every other layer.
        group_members: list[str] = []
        status = "bound"

        if binding_kind == "command":
            controls = [
                _role_bindings_inspect(
                    "Route one request",
                    "agentdeck frontdesk --message <text>",
                    enabled=False,
                    blocker="requires --message <text>",
                )
            ]
        elif binding_kind == "logical_leader":
            provider, model = logical_backends[role_name]
            identity = leader_backend_identity(provider, model)
            backend = identity["provider_backend"]
            transport = identity["provider_transport"]
            label, command = logical_controls[role_name]
            controls = [_role_bindings_inspect(label, command)]
        else:
            if role_name == "coder":
                agent_id, status, candidates, conflicts = _role_bindings_worker_layer(
                    worker_bindings, "coder"
                )
                if status == "unbound":
                    blocker = "no configured agent has an implementation role; add one to [[agents]]"
                elif status == "ambiguous":
                    blocker = _role_bindings_collision_blocker(conflicts) or (
                        "several agents share an implementation role: "
                        f"{', '.join(candidates)}; give exactly one the implementation role"
                    )
            elif role_name == "code_reviewer":
                if reviewers:
                    # The head is the binding (same primary-reviewer rule
                    # `review_group` uses), but a GUI drawing only the head
                    # would draw one reviewer for a project that really runs a
                    # serial group. Report the whole group, in configured order
                    # — that order is the dispatch order.
                    agent_id, status, candidates = reviewers[0], "bound", []
                    group_members = list(reviewers)
                else:
                    agent_id, status, candidates, conflicts = _role_bindings_worker_layer(
                        worker_bindings, "code_reviewer"
                    )
                    if status == "unbound":
                        blocker = (
                            "no configured agent has a review role; add one to [[agents]] "
                            "or set [review] reviewers"
                        )
                    elif status == "ambiguous":
                        blocker = _role_bindings_collision_blocker(conflicts) or (
                            "several agents share a review role: "
                            f"{', '.join(candidates)}; set [review] reviewers to choose"
                        )
            else:
                if round_reviewer:
                    agent_id, status = round_reviewer, "bound"
                else:
                    status = "unbound"
                    blocker = "set [review] round_reviewer to enable a dedicated acceptance reviewer"
            if agent_id:
                agent = by_agent.get(agent_id, {})
                provider = agent.get("provider")
                runtime = agent.get("runtime") if isinstance(agent.get("runtime"), dict) else {}
                runtime_status = runtime.get("status")
                pane_id = runtime.get("pane_id")
            controls = _role_bindings_worker_controls(agent_id, runtime_status if isinstance(runtime_status, str) else None)

        roles.append(
            {
                "role": role_name,
                "layer": spec["layer"],
                "binding_kind": binding_kind,
                "binding_status": status,
                "agent_id": agent_id,
                "provider": provider,
                "model": model,
                "backend": backend,
                "transport": transport,
                "lifecycle": spec["lifecycle"],
                "runtime_status": runtime_status,
                "pane_id": pane_id,
                "blocker": blocker,
                "candidates": list(candidates),
                "group_members": list(group_members),
                "controls": controls,
            }
        )

    def count(status: str) -> int:
        return sum(1 for role in roles if role["binding_status"] == status)

    return {
        "mode": "role_bindings",
        "source_command": ROLE_BINDINGS_COMMAND,
        "layer_count": len(roles),
        "bound_count": count("bound"),
        "unbound_count": count("unbound"),
        "ambiguous_count": count("ambiguous"),
        "split_enabled": leader_split_enabled(config.leader),
        "roles": roles,
        "controls": [
            _role_bindings_inspect("Inspect role bindings", ROLE_BINDINGS_COMMAND),
            _role_bindings_inspect("Open workbench", "agentdeck workbench"),
        ],
    }


def _role_agent_controls(agent_id: str) -> list[dict[str, object]]:
    return [
        _control(
            kind="assign_role",
            label="Assign role",
            command=f"agentdeck agent assign-role --agent {agent_id} --role <role> --role-prompt <role_prompt>",
            safety="explicit_user",
            enabled=False,
            blocker="requires role and role_prompt",
        )
    ]


def _agent_assign_role_command(agent_id: str, role: str, role_prompt: str) -> str:
    return " ".join(
        [
            "agentdeck",
            "agent",
            "assign-role",
            "--agent",
            _quote_assign_role_arg(agent_id),
            "--role",
            _quote_assign_role_arg(role),
            "--role-prompt",
            _quote_assign_role_arg(role_prompt),
        ]
    )


def _quote_assign_role_arg(value: str) -> str:
    if re.fullmatch(r"[\w@%+=:,./-]+", value):
        return value
    return shlex.quote(value)


