def workbench_command(args: argparse.Namespace) -> int:
    config, store, exit_code = _load_project_or_error()
    if config is None or store is None:
        return exit_code

    if args.iterations is not None and args.iterations < 1:
        print("--iterations must be greater than 0", file=sys.stderr)
        return 1
    if _reject_negative_interval(args, "workbench"):
        return 1

    iteration = 0
    while True:
        project_view = _project_view_payload_or_error(config, store)
        if project_view is None:
            return 1
        payload = _workbench_snapshot_payload(project_view, store, since_event_id=args.since_event)
        validation = validate_workbench_contract(payload)
        if not validation["ok"]:
            print("Workbench contract validation failed", file=sys.stderr)
            for error in validation["errors"]:
                print(f"- {error}", file=sys.stderr)
            return 1
        if args.watch:
            _print_json_line(payload)
        else:
            _print_json(payload)
            return 0
        iteration += 1
        if args.iterations is not None and iteration >= args.iterations:
            return 0
        if args.interval > 0:
            try:
                time.sleep(args.interval)
            except KeyboardInterrupt:
                return 130
    return 0


def dashboard_command(args: argparse.Namespace) -> int:
    config, store, exit_code = _load_project_or_error()
    if config is None or store is None:
        return exit_code
    watch = getattr(args, "watch", False)
    interval = getattr(args, "interval", 1.0)
    iterations = getattr(args, "iterations", None)
    if iterations is not None and iterations < 1:
        print("--iterations must be greater than 0", file=sys.stderr)
        return 1
    if _reject_negative_interval(args, "dashboard"):
        return 1
    rendered = 0
    while True:
        project_view = _project_view_payload_or_error(config, store)
        if project_view is None:
            return 1
        payload = _workbench_snapshot_payload(project_view, store, since_event_id=None)
        validation = validate_workbench_contract(payload)
        if not validation["ok"]:
            print("Workbench contract validation failed", file=sys.stderr)
            for error in validation["errors"]:
                print(f"- {error}", file=sys.stderr)
            return 1
        print(render_workbench_dashboard(payload), end="")
        rendered += 1
        if not watch:
            return 0
        if iterations is not None and rendered >= iterations:
            return 0
        if interval > 0:
            try:
                time.sleep(interval)
            except KeyboardInterrupt:
                return 130


def _workbench_snapshot_or_error(config: ProjectConfig, store: StateStore) -> dict[str, object] | None:
    project_view = _project_view_payload_or_error(config, store)
    if project_view is None:
        return None
    payload = _workbench_snapshot_payload(project_view, store, since_event_id=None)
    validation = validate_workbench_contract(payload)
    if not validation["ok"]:
        print("Workbench contract validation failed", file=sys.stderr)
        for error in validation["errors"]:
            print(f"- {error}", file=sys.stderr)
        return None
    return payload


def tui_command(args: argparse.Namespace) -> int:
    config, store, exit_code = _load_project_or_error()
    if config is None or store is None:
        return exit_code
    if not sys.stdout.isatty():
        print(
            "agentdeck tui requires an interactive terminal; "
            "use agentdeck dashboard for non-interactive output",
            file=sys.stderr,
        )
        return 1
    payload = _workbench_snapshot_or_error(config, store)
    if payload is None:
        return 1

    def fetch() -> dict[str, object] | None:
        return _workbench_snapshot_or_error(config, store)

    import curses

    focused_command = curses.wrapper(lambda stdscr: run_tui(stdscr, TuiModel(payload), fetch))
    if focused_command:
        # Read-only bridge from view to run: print the command the user was
        # looking at so they can run it themselves. The TUI never executes it.
        print(focused_command)
    return 0


def history_command(args: argparse.Namespace) -> int:
    config, store, exit_code = _load_project_or_error()
    if config is None or store is None:
        return exit_code
    limit = getattr(args, "limit", None)
    if limit and limit > 0:
        events = store.list_events(limit=limit)
    else:
        events = store.all_events()
    markdown = render_history_markdown(events, config.name)
    write_target = getattr(args, "write", None)
    if write_target is not None:
        target = (Path(store.deck_dir) / "HISTORY.md") if write_target == "" else Path(write_target)
        target.parent.mkdir(parents=True, exist_ok=True)
        target.write_text(markdown, encoding="utf-8")
        print(f"wrote {target}")
        return 0
    print(markdown, end="")
    return 0


