def _daemon_keepalive_view(
    state: dict[str, object], *, other_client_count: int,
) -> dict[str, object]:
    def list_field(name: str) -> list[object]:
        value = state.get(name, [])
        if not isinstance(value, list):
            raise DaemonClientRequestError(
                "daemon keepalive state is invalid", "stop_blocked"
            )
        return value

    def dict_field(name: str) -> dict[str, object]:
        value = state.get(name, {})
        if not isinstance(value, dict):
            raise DaemonClientRequestError(
                "daemon keepalive state is invalid", "stop_blocked"
            )
        return value

    def status_count(name: str, statuses: set[str]) -> int:
        items = list_field(name)
        if any(not isinstance(item, dict) for item in items):
            raise DaemonClientRequestError(
                "daemon keepalive state is invalid", "stop_blocked"
            )
        return sum(item.get("status") in statuses for item in items)

    agents = dict_field("agents")
    if any(not isinstance(value, dict) for value in agents.values()):
        raise DaemonClientRequestError(
            "daemon keepalive state is invalid", "stop_blocked"
        )
    inbox = dict_field("inbox")
    if any(not isinstance(items, list) for items in inbox.values()):
        raise DaemonClientRequestError(
            "daemon keepalive state is invalid", "stop_blocked"
        )
    pending_replies = sum(
        1
        for items in inbox.values()
        if isinstance(items, list)
        for item in items
        if isinstance(item, dict)
        and item.get("status") == "pending"
        and item.get("event_type") == "task_reply"
    )
    if any(
        not isinstance(item, dict)
        for items in inbox.values()
        if isinstance(items, list)
        for item in items
    ):
        raise DaemonClientRequestError(
            "daemon keepalive state is invalid", "stop_blocked"
        )
    outbox_count = sum(
        len(list_field(name))
        for name in (
            "daemon_event_outbox",
            "protocol_event_outbox",
            "conversation_event_outbox",
        )
    )

    decisions = list_field("decisions")
    recovery_decisions = list_field("recovery_decisions")
    if any(not isinstance(item, dict) for item in decisions + recovery_decisions):
        raise DaemonClientRequestError(
            "daemon keepalive state is invalid", "stop_blocked"
        )

    def flag(name: str) -> bool:
        value = state.get(name, False)
        if type(value) is not bool:
            raise DaemonClientRequestError(
                "daemon keepalive state is invalid", "stop_blocked"
            )
        return value

    return {
        "client_count": other_client_count,
        "active_mission_count": status_count(
            "missions", {"preparing", "running", "interrupted"}
        ),
        "active_worker_count": sum(
            1 for value in agents.values()
            if isinstance(value, dict) and value.get("status") == "running"
        ),
        "pending_approval_count": status_count("approvals", {"pending"}),
        "pending_permission_count": status_count(
            "permission_requests", {"pending"}
        ),
        "pending_reply_count": pending_replies,
        "pending_recovery_decision_count": sum(
            item.get("status") == "pending" for item in recovery_decisions
        ),
        "pending_decision_count": sum(
            item.get("status") == "pending" for item in decisions
        ),
        "ambiguous_decision_count": sum(
            item.get("status") == "ambiguous" for item in decisions
        ),
        "outbox_count": outbox_count,
        "recovery_active": flag("recovery_active"),
        "safe_shutdown_active": flag("safe_shutdown_active"),
        "atomic_write_active": flag("atomic_write_active"),
    }


def _validate_daemon_stop_gate(
    root: Path, ownership: object, store: StateStore, *, other_client_count: int,
) -> None:
    if type(other_client_count) is not int or other_client_count < 0:
        raise DaemonClientRequestError("daemon client count is invalid", "stop_blocked")
    binding = None
    try:
        binding = bind_daemon_endpoint(root)
        metadata = binding.read_metadata()
    except Exception:
        raise DaemonClientRequestError("daemon identity is unverified", "stop_blocked") from None
    finally:
        if binding is not None:
            binding.close()
    expected = {
        "instance_id": getattr(ownership, "instance_id", None),
        "project_root_hash": getattr(ownership, "project_root_hash", None),
        "start_nonce_hash": getattr(ownership, "start_nonce_hash", None),
        "pid": getattr(ownership, "pid", None),
    }
    state = store.load()
    daemon_record = state.get("daemon_runtime")
    if metadata != expected or not isinstance(daemon_record, dict) or any(
        daemon_record.get(name) != expected[name]
        for name in ("instance_id", "project_root_hash", "start_nonce_hash")
    ):
        raise DaemonClientRequestError("daemon identity is unverified", "stop_blocked")
    if not can_stop_daemon(
        _daemon_keepalive_view(state, other_client_count=other_client_count)
    ):
        raise DaemonClientRequestError("daemon has active keepalive work", "stop_blocked")


def _commit_daemon_shutdown(
    commit: Any,
    stop_event: asyncio.Event,
    *,
    shutdown_on_failure: bool = False,
) -> object:
    """Signal process shutdown only after the durable stop commit succeeds."""
    if not callable(commit) or not isinstance(stop_event, asyncio.Event):
        raise TypeError("daemon shutdown commit boundary is invalid")
    try:
        result = commit()
    except BaseException:
        if shutdown_on_failure:
            stop_event.set()
        raise
    else:
        stop_event.set()
        return result


def _finalize_force_stop_shutdown(
    store: StateStore,
    *,
    lease_id: str,
    generation: int,
    now: datetime,
    commit_and_flush: Any,
    stop_event: asyncio.Event,
) -> object:
    """Always request exit after force-stop already committed durable stopping."""
    def release_and_flush() -> object:
        current = controller_lease_from_summary(
            store.load().get("controller_lease")
        )
        if current is None:
            raise LeaseError("controller lease required")
        transition = release_controller(
            current,
            lease_id=lease_id,
            generation=generation,
            now=now,
        )
        return commit_and_flush(transition)

    try:
        _commit_daemon_shutdown(
            release_and_flush, stop_event, shutdown_on_failure=True
        )
    except BaseException:
        # The force-stop domain transition is already durable.  Cleanup
        # failure is diagnostic, never a retroactive rejection of that stop.
        return {
            "status": "failed",
            "reason": "controller cleanup incomplete",
            "recovery": "daemon restart reconciliation required",
        }
    return {"status": "completed"}


async def _request_daemon_stop(
    root: Path, config: ProjectConfig, *,
    lease_id: str | None, lease_generation: int | None,
) -> dict[str, object]:
    client = await DaemonClient.connect_verified(
        root, max_frame_bytes=config.daemon.max_frame_bytes,
        timeout_seconds=config.daemon.start_timeout_seconds,
    )
    temporary_controller = False
    try:
        if lease_id is None and lease_generation is None:
            acquired = await client.request(
                "controller.acquire",
                {"client_id": f"client_stop_{secrets.token_hex(12)}"},
            )
            acquired_lease_id = acquired.get("lease_id")
            acquired_generation = acquired.get("generation")
            lease_id = (
                acquired_lease_id if type(acquired_lease_id) is str else None
            )
            lease_generation = (
                acquired_generation if type(acquired_generation) is int else None
            )
            if type(lease_id) is not str or type(lease_generation) is not int:
                raise DaemonUnavailable("daemon controller acquisition failed")
            temporary_controller = True
        assert lease_id is not None and lease_generation is not None
        try:
            result = await client.request(
                "daemon.stop",
                {"lease_id": lease_id, "generation": lease_generation},
                lease_id=lease_id,
                lease_generation=lease_generation,
            )
            if result != {"accepted": True, "state": "stopping"}:
                raise DaemonUnavailable("verified daemon stop was rejected")
            return result
        except Exception as stop_error:
            if not temporary_controller:
                raise
            try:
                released = await client.request(
                    "controller.release",
                    {"lease_id": lease_id, "generation": lease_generation},
                    lease_id=lease_id,
                    lease_generation=lease_generation,
                )
                if (
                    released.get("released") is not True
                    or released.get("lease_id") != lease_id
                    or released.get("generation") != lease_generation
                    or type(released.get("expires_at")) is not str
                ):
                    raise DaemonUnavailable("temporary controller cleanup was not confirmed")
            except Exception:
                raise DaemonUnavailable(
                    f"{stop_error}; temporary controller cleanup failed"
                ) from None
            raise
    finally:
        await client.close()


def daemon_stop_command(args: argparse.Namespace) -> int:
    config, _store, exit_code = _load_project_or_error()
    if config is None:
        return exit_code
    if (args.lease_id is None) != (args.lease_generation is None):
        print("--lease-id and --lease-generation must be provided together", file=sys.stderr)
        return 1
    root = Path(config.root)
    if not _endpoint_files_exist_without_mutation(root):
        print("verified daemon is unavailable", file=sys.stderr)
        return 1
    try:
        result = asyncio.run(_request_daemon_stop(
            root, config, lease_id=args.lease_id,
            lease_generation=args.lease_generation,
        ))
    except Exception as exc:
        message = str(exc)
        if message not in {
            "controller lease required", "stale controller lease",
            "controller lease expired", "controller lease is already held",
            "daemon has active keepalive work",
            "daemon identity is unverified", "daemon keepalive state is invalid",
        } and not message.endswith("; temporary controller cleanup failed"):
            message = "verified daemon stop was rejected"
        print(message, file=sys.stderr)
        return 1
    if result != {"accepted": True, "state": "stopping"}:
        print("verified daemon stop was rejected", file=sys.stderr)
        return 1
    _print_json({"ok": True, "mode": "daemon_stop", "accepted": True})
    return 0


def _read_daemon_log(root: Path, name: str, lines: int) -> list[str]:
    directory_flags = os.O_RDONLY | getattr(os, "O_DIRECTORY", 0) | getattr(os, "O_NOFOLLOW", 0)
    file_flags = os.O_RDONLY | getattr(os, "O_NOFOLLOW", 0)
    descriptors: list[int] = []
    try:
        descriptors.append(os.open(root, directory_flags))
        descriptors.append(os.open(".agentdeck", directory_flags, dir_fd=descriptors[-1]))
        descriptors.append(os.open("runtime", directory_flags, dir_fd=descriptors[-1]))
        try:
            descriptors.append(os.open(name, file_flags, dir_fd=descriptors[-1]))
        except FileNotFoundError:
            return []
        metadata = os.fstat(descriptors[-1])
        if not stat.S_ISREG(metadata.st_mode) or metadata.st_size > 1024 * 1024:
            raise ValueError("daemon log is not a bounded regular file")
        content = os.read(descriptors[-1], 1024 * 1024 + 1)
    except FileNotFoundError:
        return []
    finally:
        for descriptor in reversed(descriptors):
            os.close(descriptor)
    values = content.decode("utf-8", errors="replace").splitlines()[-lines:]
    return [re.sub(r"(?i)(token|secret|password|api[_-]?key)=\S+", r"\1=<redacted>", value[:500]) for value in values]


def daemon_logs_command(args: argparse.Namespace) -> int:
    config, _store, exit_code = _load_project_or_error()
    if config is None:
        return exit_code
    if args.lines < 1 or args.lines > 1000:
        print("--lines must be between 1 and 1000", file=sys.stderr)
        return 1
    root = Path(config.root)
    try:
        payload = {
            "ok": True, "mode": "daemon_logs", "lines": args.lines,
            "stdout": _read_daemon_log(root, "daemon.stdout.log", args.lines),
            "stderr": _read_daemon_log(root, "daemon.stderr.log", args.lines),
        }
    except (OSError, ValueError) as exc:
        print(str(exc), file=sys.stderr)
        return 1
    _print_json(payload)
    return 0


def _daemon_worker_transport_for(
    *, store: StateStore, service: ProjectDaemonService, root: Path,
    attempt: dict[str, object],
):
    """Build one Worker transport from freshly reloaded frozen authority."""
    current_config = load_config(root)
    mission = store.mission_by_id(str(attempt["mission_id"]))
    try:
        snapshot = validate_execution_snapshot(mission.get("execution_snapshot"))
    except (TypeError, ValueError):
        raise ServiceError("Worker execution snapshot is invalid") from None
    mission_snapshot = snapshot["mission"]
    step = next(
        (
            item
            for item in mission_snapshot.get("steps", [])
            if isinstance(item, dict)
            and item.get("step_id") == attempt.get("step_id")
        ),
        None,
    )
    agent = next(
        (
            item for item in current_config.agents
            if item.agent_id == attempt.get("agent_id")
        ),
        None,
    )
    if step is None or agent is None:
        raise ServiceError("Worker execution authority is invalid")
    plan = store.plan_by_id(str(mission_snapshot.get("plan_id") or ""))
    raw_plan = plan.get("plan")
    raw_steps = raw_plan.get("steps", []) if isinstance(raw_plan, dict) else []
    raw_step = next(
        (
            item
            for item in raw_steps
            if isinstance(item, dict)
            and item.get("step") == step.get("position")
            and item.get("agent_id") == step.get("agent_id")
        ),
        None,
    )
    if raw_step is None or not isinstance(raw_step.get("task"), str):
        raise ServiceError("Worker task authority is invalid")
    worker = next(
        (
            item for item in snapshot.get("workers", [])
            if isinstance(item, dict) and item.get("agent_id") == agent.agent_id
        ),
        None,
    )
    semantic_active = "semantic_authority_schema_version" in mission_snapshot
    persisted_attempt: dict[str, object] | Mapping[str, object] = attempt

    def semantic_drift() -> None:
        try:
            store.record_semantic_worker_dispatch_event(
                "semantic_authority_drift_detected",
                mission_id=str(attempt.get("mission_id") or ""),
                attempt_id=str(attempt.get("attempt_id") or ""),
                step_id=str(attempt.get("step_id") or ""),
                agent_id=str(attempt.get("agent_id") or ""),
                code="semantic_compilation_drift",
            )
        except Exception:
            pass
        raise ServiceError("semantic_compilation_drift")

    if semantic_active:
        try:
            persisted_attempt = store.mission_attempt_by_id(
                str(attempt.get("attempt_id") or "")
            )
            if (
                type(raw_plan) is not dict
                or set(raw_plan)
                != {"goal", "summary", "steps", "semantic_authority", "semantic_steps"}
                or type(raw_plan.get("semantic_steps")) is not list
                or type(raw_plan.get("steps")) is not list
                or len(raw_plan["semantic_steps"]) != len(raw_plan["steps"])
                or mission.get("semantic_authority_hash")
                != mission_snapshot.get("semantic_authority_hash")
            ):
                raise ValueError
            authority = validate_semantic_authority(raw_plan["semantic_authority"])
            current_policy = execution_policy_snapshot(current_config)
            if (
                authority["schema_version"]
                != mission_snapshot.get("semantic_authority_schema_version")
                or semantic_authority_hash(authority)
                != mission_snapshot.get("semantic_authority_hash")
                or current_policy != snapshot["policy"]
                or canonical_snapshot_hash(current_policy) != snapshot["policy_hash"]
            ):
                raise ValueError
            position = step.get("position")
            if type(position) is not int or position < 1:
                raise ValueError
            semantic = raw_plan["semantic_steps"][position - 1]
            actual_semantic_hash = semantic_step_hash(semantic)
            compiled_task = compile_worker_task(semantic)
            actual_task_hash = canonical_snapshot_hash({"task": compiled_task})
            requirements = {
                item["requirement_id"]: item for item in authority["requirements"]
            }
            if (
                semantic.get("step") != position
                or semantic.get("agent_id") != step.get("agent_id")
                or semantic.get("role") != step.get("role")
                or [requirements.get(item) for item in semantic.get("authority_refs", [])]
                != semantic.get("required_effects")
                or raw_step.get("task") != compiled_task
                or actual_task_hash != step.get("task_hash")
                or actual_semantic_hash != step.get("semantic_step_hash")
                or persisted_attempt.get("semantic_step_hash") != actual_semantic_hash
                or attempt.get("semantic_step_hash") != actual_semantic_hash
                or persisted_attempt != attempt
                or mission.get("snapshot_hash") != snapshot["execution_hash"]
                or mission.get("execution_authority_hash") != snapshot["execution_hash"]
                or persisted_attempt.get("snapshot_hash") != snapshot["execution_hash"]
                or _worker_ownership_state(store.load(), agent.agent_id)
                != "agentdeck_owned"
            ):
                raise ValueError
        except (
            AttributeError, IndexError, KeyError, SemanticPlanningError,
            TypeError, ValueError,
        ):
            semantic_drift()
        task = compiled_task
        task_hash = actual_task_hash
        current_semantic_hash: str | None = actual_semantic_hash
    else:
        task = raw_step["task"]
        task_hash = canonical_snapshot_hash({"task": task})
        current_semantic_hash = None

    if (
        task_hash != step.get("task_hash")
        or not isinstance(worker, dict)
        or worker.get("configured_transport") != agent.transport
        or any(
            worker.get(field) != getattr(agent, field)
            for field in ("provider", "role", "workspace_mode")
        )
        or worker_runtime_identity_hash(agent, current_config.runtime)
        != worker.get("runtime_identity_hash")
    ):
        if semantic_active:
            semantic_drift()
        raise ServiceError("Worker execution authority drift")
    try:
        previous_handoff = resolve_previous_handoff(store.load(), persisted_attempt)
    except ServiceError:
        if semantic_active:
            semantic_drift()
        raise
    if semantic_active:
        try:
            store.record_semantic_worker_dispatch_event(
                "worker_task_compiled",
                mission_id=str(attempt["mission_id"]),
                attempt_id=str(attempt["attempt_id"]),
                step_id=str(attempt["step_id"]),
                agent_id=str(attempt["agent_id"]),
                task_hash=task_hash,
                semantic_step_hash=current_semantic_hash,
            )
        except (TypeError, ValueError):
            semantic_drift()
    effective_agent = replace(
        agent, transport=str(attempt["configured_transport"])
    )
    prompt = build_worker_prompt(
        persisted_attempt,
        effective_agent,
        task=task,
        previous_handoff=previous_handoff,
        semantic_step_hash=current_semantic_hash,
    )
    if attempt["configured_transport"] == "acp":
        sink = _DaemonAcpWorkerSink(
            service=service,
            store=store,
            attempt=attempt,
            agent=effective_agent,
            workspace=root,
        )
        return AcpWorkerTransport(
            argv=effective_agent.transport_command,
            workspace=root,
            prompt=prompt,
            request_timeout=float(mission.get("timeout_seconds") or 180),
            sink=sink,
            decide=sink.decide,
        )
    project_view = store.project_view(current_config)
    pane_id = next(
        (
            item.get("runtime", {}).get("pane_id")
            for item in project_view.agents
            if isinstance(item, dict)
            and item.get("agent_id") == effective_agent.agent_id
            and isinstance(item.get("runtime"), dict)
        ),
        None,
    )
    if not isinstance(pane_id, str):
        raise ServiceError("tmux Worker pane is not ready")
    timeout_seconds = int(mission.get("timeout_seconds") or 180)
    return TmuxWorkerTransport(
        config=current_config.runtime,
        pane_id=pane_id,
        prompt=prompt,
        max_polls=max(1, timeout_seconds),
        poll_interval_seconds=1,
    )


def _cleanup_permission_confirmation_controller(
    store: StateStore,
    record: dict[str, object],
    *,
    now: datetime,
    commit_and_flush: Any,
) -> dict[str, object]:
    """Durably retire only the controller generation held by one handle."""
    lease_id = record.get("lease_id")
    generation = record.get("generation")
    if type(lease_id) is not str or type(generation) is not int:
        raise ServiceError("permission confirmation controller cleanup incomplete")
    terminal = store.controller_lease_terminal_state(
        lease_id=lease_id, generation=generation
    )
    if terminal in {"released", "expired"}:
        return {"status": "already_inactive"}
    current = controller_lease_from_summary(
        store.load().get("controller_lease")
    )
    if (
        current is None
        or current.lease_id != lease_id
        or current.generation != generation
    ):
        return {"status": "already_inactive"}
    try:
        expires_at = datetime.fromisoformat(current.expires_at)
    except (TypeError, ValueError):
        raise ServiceError(
            "permission confirmation controller cleanup incomplete"
        ) from None
    if expires_at.tzinfo is None or expires_at.utcoffset() is None:
        raise ServiceError("permission confirmation controller cleanup incomplete")
    if expires_at.astimezone(timezone.utc) <= now.astimezone(timezone.utc):
        transition = expire_controller(current, now=now)
        status = "expired"
    else:
        transition = release_controller(
            current,
            lease_id=lease_id,
            generation=generation,
            now=now,
        )
        status = "released"
    commit_and_flush(transition)
    return {"status": status}


async def _serve_daemon(root: Path, config: ProjectConfig, store: StateStore) -> int:
    ownership = acquire_daemon_ownership(
        root, start_nonce=secrets.token_hex(32), health_probe=lambda _metadata: None,
        wait_timeout_seconds=config.daemon.start_timeout_seconds,
    )
    if ownership.role != "owner":
        ownership.release()
        return 0
    stop_event = asyncio.Event()
    loop = asyncio.get_running_loop()
    for signum in (signal.SIGINT, signal.SIGTERM):
        with contextlib.suppress(NotImplementedError):
            loop.add_signal_handler(signum, stop_event.set)
    server: DaemonServer | None = None
    service: ProjectDaemonService | None = None
    created_at: str | None = None
    try:
        status: dict[str, object] = {}
        def current_status() -> dict[str, object]:
            snapshot = dict(status)
            if server is not None:
                other_clients = max(0, server.connection_count - 1)
                keepalive = _daemon_keepalive_view(
                    store.load(), other_client_count=other_clients
                )
                snapshot.update(keepalive)
                reasons = daemon_keepalive_reasons(keepalive)
                nonclient_reasons = tuple(
                    reason for reason in reasons if reason != "clients_connected"
                )
                if nonclient_reasons:
                    snapshot["state"] = "busy"
                    snapshot["idle_exit_pending"] = False
                elif server.connection_count:
                    snapshot["state"] = "ready"
                    snapshot["idle_exit_pending"] = False
                snapshot["controller_present"] = _controller_lease_is_active(
                    store.load()
                )
            return snapshot

        def lease_validator(lease_id: str, generation: int) -> None:
            _validate_daemon_controller_lease(store, lease_id, generation)

        live_permission_authorities: dict[str, dict[str, object]] = {}

        def refresh_recovery_authority() -> None:
            reconcile_startup(store, enable_scheduler=lambda: None)
            for authority in tuple(live_permission_authorities.values()):
                store.record_live_permission_recovery(
                    authority=dict(authority),
                    daemon_instance_id=ownership.instance_id,
                )

        def publish_live_permission_waiter(
            authority: dict[str, object], active: bool
        ) -> None:
            if active:
                store.record_live_permission_recovery(
                    authority=authority,
                    daemon_instance_id=ownership.instance_id,
                )
                live_permission_authorities[str(authority["permission_id"])] = dict(
                    authority
                )
            else:
                live_permission_authorities.pop(
                    str(authority["permission_id"]), None
                )
                refresh_recovery_authority()

        def admit_and_reconcile(params: dict[str, object]) -> dict[str, object]:
            result = validate_confirmed_mission_admission(store, params)
            refresh_recovery_authority()
            return result

        def lease_result(lease: ControllerLease) -> dict[str, object]:
            return {
                "lease_id": lease.lease_id,
                "generation": lease.generation,
                "expires_at": lease.expires_at,
            }

        def commit_and_flush(transition: LeaseTransition) -> dict[str, object]:
            store.commit_controller_lease(transition)
            store.flush_daemon_event_outbox()
            current = transition.current
            assert current is not None
            return lease_result(current)

        def refresh_controller(now: datetime) -> bool:
            state = store.load()
            lease = controller_lease_from_summary(state.get("controller_lease"))
            if lease is None or not lease.lease_id.startswith("lse_"):
                return False
            try:
                validate_controller(
                    lease,
                    lease_id=lease.lease_id,
                    generation=lease.generation,
                    now=now,
                )
            except LeaseError as exc:
                if str(exc) != "controller lease expired":
                    raise
                if store.controller_lease_terminal_state(
                    lease_id=lease.lease_id, generation=lease.generation
                ) == "released":
                    return False
                commit_and_flush(expire_controller(lease, now=now))
                return False
            return True

        def lease_params(params: dict[str, object]) -> tuple[str, int]:
            lease_id = params.get("lease_id")
            generation = params.get("generation")
            if type(lease_id) is not str or type(generation) is not int:
                raise LeaseError("stale controller lease")
            return lease_id, generation

        def apply_mutation(method: str, params: dict[str, object]) -> dict[str, object]:
            try:
                now = datetime.now(timezone.utc)
                params = dict(params)
                if method not in {
                    "controller.acquire", "permission.confirm-handle"
                }:
                    authority = params.pop("_lease", None)
                    if not isinstance(authority, Mapping):
                        raise LeaseError("controller lease required")
                    lease_id, generation = lease_params(dict(authority))
                    _validate_daemon_controller_lease(
                        store, lease_id, generation, now=now
                    )
                if method == "permission.confirm-handle":
                    if service is None or set(params) != {"handle"}:
                        raise DaemonClientRequestError(
                            "permission confirmation handle is invalid",
                            "permission_confirmation_blocked",
                        )
                    record: dict[str, object] | None = None
                    committed = False
                    response: dict[str, object] | None = None
                    failure: DaemonClientRequestError | None = None
                    try:
                        record = service.consume_permission_confirmation(
                            params["handle"], now=now
                        )
                        target = record.get("target")
                        stored_waiter = record.get("live_waiter_authority")
                        stored_binding = record.get("permission_binding")
                        stored_lease_id = record.get("lease_id")
                        stored_generation = record.get("generation")
                        stored_preview_id = record.get("preview_id")
                        if (
                            type(target) is not dict
                            or type(stored_waiter) is not dict
                            or type(stored_binding) is not dict
                            or type(stored_lease_id) is not str
                            or type(stored_generation) is not int
                            or type(stored_preview_id) is not str
                        ):
                            raise ServiceError(
                                "permission confirmation handle is invalid"
                            )
                        _validate_daemon_controller_lease(
                            store, stored_lease_id, stored_generation, now=now
                        )
                        permission_id = target.get("permission_id")
                        current_waiter = (
                            service.live_permission_waiter_authority(permission_id)
                            if isinstance(permission_id, str)
                            else None
                        )
                        state = store.validated_protocol_state()
                        current_bindings = [
                            item
                            for item in state.get(
                                "mission_permission_bindings", []
                            )
                            if type(item) is dict
                            and item == stored_binding
                        ]
                        if current_waiter != stored_waiter or len(current_bindings) != 1:
                            raise ServiceError(
                                "permission confirmation authority is stale"
                            )
                        result = apply_permission_decision_request(
                            store,
                            {**target, "preview_id": stored_preview_id},
                            generation=stored_generation,
                            now=now,
                            live_waiter_authority=current_waiter,
                        )
                        committed = True
                        if result.get("state") not in {"approved", "denied"}:
                            raise ServiceError(
                                "permission confirmation result is invalid"
                            )
                        if service.notify_permission_decision(
                            str(result["permission_id"]), str(result["state"])
                        ) is not True:
                            raise ServiceError(
                                "live permission waiter notification failed"
                            )
                        response = {
                            "confirmation_handle": params["handle"],
                            "preview_id": stored_preview_id,
                            **target,
                            "state": result["state"],
                        }
                    except PermissionConfirmationExpired:
                        failure = DaemonClientRequestError(
                            "permission confirmation handle is unavailable",
                            "permission_confirmation_blocked",
                        )
                    except (LeaseError, ServiceError) as exc:
                        if str(exc) == (
                            "permission confirmation controller cleanup incomplete"
                        ):
                            failure = DaemonClientRequestError(
                                "permission confirmation failed; controller cleanup incomplete",
                                "permission_confirmation_cleanup_incomplete",
                            )
                        else:
                            failure = DaemonClientRequestError(
                                "permission confirmation handle is unavailable",
                                "permission_confirmation_blocked",
                            )
                    except Exception:
                        failure = DaemonClientRequestError(
                            "permission confirmation handle is unavailable",
                            "permission_confirmation_blocked",
                        )
                    if record is not None:
                        try:
                            service.finalize_permission_confirmation(
                                str(params["handle"]), record
                            )
                        except ServiceError:
                            message = (
                                "permission state committed; controller cleanup incomplete"
                                if committed
                                else "permission confirmation failed; controller cleanup incomplete"
                            )
                            raise DaemonClientRequestError(
                                message,
                                "permission_confirmation_cleanup_incomplete",
                            ) from None
                    if failure is not None:
                        raise failure
                    if response is None:
                        raise DaemonClientRequestError(
                            "permission confirmation handle is unavailable",
                            "permission_confirmation_blocked",
                        )
                    return response
                if method == "mission.admit":
                    if service is None:
                        raise DaemonClientRequestError(
                            "daemon service is unavailable", "unavailable"
                        )
                    try:
                        result = admit_and_reconcile(params)
                    except ServiceError as exc:
                        raise DaemonClientRequestError(
                            str(exc), "mission_admission_blocked"
                        ) from None
                    if not isinstance(result, dict):
                        raise DaemonClientRequestError(
                            "Mission admission result is invalid", "invalid_result"
                        )
                    return result
                if method == "mission.pause":
                    try:
                        return apply_mission_pause_request(
                            store,
                            params,
                            generation=generation,
                            now=now,
                        )
                    except ServiceError as exc:
                        raise DaemonClientRequestError(
                            str(exc), "mission_pause_blocked"
                        ) from None
                if method in {"mission.resume", "mission.cancel"}:
                    try:
                        current = controller_lease_from_summary(
                            store.load().get("controller_lease")
                        )
                        if current is None:
                            raise LeaseError("controller lease required")
                        return apply_mission_state_request(
                            store,
                            action=method.replace(".", "_"),
                            params=params,
                            generation=generation,
                            now=now,
                            current_authority={
                                **current.summary(),
                                "daemon_instance_id": ownership.instance_id,
                            },
                        )
                    except ServiceError as exc:
                        raise DaemonClientRequestError(
                            str(exc), "mission_governance_blocked"
                        ) from None
                if method in {"permission.decide", "permission.preview-handle"}:
                    try:
                        permission_id = params.get("permission_id")
                        live_waiter = (
                            service.live_permission_waiter_authority(permission_id)
                            if service is not None and isinstance(permission_id, str)
                            else None
                        )
                        result = apply_permission_decision_request(
                            store,
                            params,
                            generation=generation,
                            now=now,
                            live_waiter_authority=live_waiter,
                        )
                        if method == "permission.preview-handle":
                            if service is None:
                                raise ServiceError("daemon service is unavailable")
                            current = controller_lease_from_summary(
                                store.load().get("controller_lease")
                            )
                            if current is None:
                                raise ServiceError(
                                    "permission confirmation controller is invalid"
                                )
                            state = store.validated_protocol_state()
                            bindings = [
                                item
                                for item in state.get(
                                    "mission_permission_bindings", []
                                )
                                if type(item) is dict
                                and item.get("mission_id") == params.get("mission_id")
                                and item.get("attempt_id") == params.get("attempt_id")
                                and item.get("permission_id")
                                == params.get("permission_id")
                            ]
                            if len(bindings) != 1 or live_waiter is None:
                                raise ServiceError(
                                    "permission confirmation binding is invalid"
                                )
                            return service.register_permission_confirmation(
                                target=params,
                                preview=result,
                                controller_authority=current.summary(),
                                live_waiter_authority=live_waiter,
                                permission_binding=bindings[0],
                                now=now,
                            )
                        if result.get("state") in {"approved", "denied"}:
                            if service is None:
                                raise ServiceError("daemon service is unavailable")
                            notified = service.notify_permission_decision(
                                str(result["permission_id"]), str(result["state"])
                            )
                            if notified is not True:
                                raise ServiceError(
                                    "live permission waiter notification failed"
                                )
                        return result
                    except ServiceError as exc:
                        raise DaemonClientRequestError(
                            str(exc), "permission_decision_blocked"
                        ) from None
                if method in {"worker.takeover", "worker.return-control"}:
                    try:
                        return apply_worker_ownership_request(
                            store,
                            action=(
                                "takeover"
                                if method == "worker.takeover"
                                else "return_control"
                            ),
                            params=params,
                            generation=generation,
                            now=now,
                        )
                    except ServiceError as exc:
                        raise DaemonClientRequestError(
                            str(exc), "worker_ownership_blocked"
                        ) from None
                if method == "worker.reroute":
                    try:
                        return apply_transport_reroute_request(
                            store,
                            params,
                            generation=generation,
                            now=now,
                        )
                    except ServiceError as exc:
                        raise DaemonClientRequestError(
                            str(exc), "worker_reroute_blocked"
                        ) from None
                if method == "controller.acquire" and set(params) == {"client_id"}:
                    transition = grant_controller(
                        client_id=params["client_id"],  # type: ignore[arg-type]
                        now=now,
                        ttl_seconds=config.daemon.controller_ttl_seconds,
                        previous=controller_lease_from_summary(
                            store.load().get("controller_lease")
                        ),
                    )
                    return commit_and_flush(transition)
                if method == "controller.renew" and set(params) == {
                    "lease_id", "generation"
                }:
                    lease_id, generation = lease_params(params)
                    current = controller_lease_from_summary(
                        store.load().get("controller_lease")
                    )
                    if current is None:
                        raise LeaseError("controller lease required")
                    transition = renew_controller(
                        current,
                        lease_id=lease_id,
                        generation=generation,
                        now=now,
                        ttl_seconds=config.daemon.controller_ttl_seconds,
                    )
                    return commit_and_flush(transition)
                if method == "controller.release" and set(params) == {
                    "lease_id", "generation"
                }:
                    lease_id, generation = lease_params(params)
                    current = controller_lease_from_summary(
                        store.load().get("controller_lease")
                    )
                    if current is None:
                        raise LeaseError("controller lease required")
                    transition = release_controller(
                        current,
                        lease_id=lease_id,
                        generation=generation,
                        now=now,
                    )
                    return {"released": True, **commit_and_flush(transition)}
                if method == "daemon.stop" and set(params) == {
                    "lease_id", "generation"
                }:
                    lease_id, generation = lease_params(params)
                    _validate_daemon_controller_lease(
                        store, lease_id, generation, now=now
                    )
                    assert server is not None
                    _validate_daemon_stop_gate(
                        root,
                        ownership,
                        store,
                        other_client_count=max(0, server.connection_count - 1),
                    )
                    current = controller_lease_from_summary(
                        store.load().get("controller_lease")
                    )
                    if current is None:
                        raise LeaseError("controller lease required")
                    transition = release_controller(
                        current,
                        lease_id=lease_id,
                        generation=generation,
                        now=now,
                    )
                    _commit_daemon_shutdown(
                        lambda: commit_and_flush(transition), stop_event
                    )
                    return {"accepted": True, "state": "stopping"}
                if method == "daemon.force-stop":
                    try:
                        result = apply_force_stop_request(
                            store,
                            params,
                            generation=generation,
                            now=now,
                        )
                    except ServiceError as exc:
                        raise DaemonClientRequestError(
                            str(exc), "force_stop_blocked"
                        ) from None
                    if result.get("state") == "stopping":
                        cleanup = _finalize_force_stop_shutdown(
                            store,
                            lease_id=lease_id,
                            generation=generation,
                            now=now,
                            commit_and_flush=commit_and_flush,
                            stop_event=stop_event,
                        )
                        if cleanup.get("status") != "completed":
                            result = {**result, "cleanup": cleanup}
                    return result
            except LeaseError as exc:
                raise DaemonClientRequestError(str(exc), "lease_required") from None
            raise DaemonClientRequestError("daemon mutation is unavailable", "unavailable")

        async def mutation_handler(method: str, params: dict[str, object]) -> dict[str, object]:
            if service is None:
                raise DaemonClientRequestError("daemon service is unavailable", "unavailable")
            result = await service.submit_mutation(lambda: apply_mutation(method, params))
            assert isinstance(result, dict)
            return result

        server = DaemonServer(
            endpoint=ownership.endpoint.socket_path, instance_id=ownership.instance_id,
            project_root_hash=ownership.project_root_hash,
            start_nonce_hash=ownership.start_nonce_hash, daemon_version=__version__,
            project_view_schema_version=PROJECT_VIEW_SCHEMA_VERSION,
            max_frame_bytes=config.daemon.max_frame_bytes,
            allowed_methods={
                "handshake", "status", "subscribe", "mission.pause",
                "mission.resume", "mission.cancel",
                "mission.admit",
                "permission.decide", "permission.preview-handle",
                "permission.confirm-handle",
                "worker.takeover", "worker.return-control",
                "worker.reroute",
                "controller.acquire", "controller.renew", "controller.release",
                "daemon.stop",
                "daemon.force-stop",
            },
            lease_exempt_methods={
                "controller.acquire", "permission.confirm-handle"
            },
            status_provider=current_status,
            mutation_handler=mutation_handler,
            lease_validator=lease_validator,
        )
        def flush_pending_outboxes() -> None:
            state = store.load()
            flushes = (
                ("daemon_event_outbox", store.flush_daemon_event_outbox),
                ("conversation_event_outbox", store.flush_conversation_event_outbox),
                ("protocol_event_outbox", store.flush_protocol_event_outbox),
            )
            for field, flush in flushes:
                pending = state.get(field, [])
                if type(pending) is not list:
                    raise ValueError("daemon outbox state is invalid")
                if pending:
                    flush()
                    state = store.load()

        effects: DaemonTransitionEffects
        daemon_tmux_backend = TmuxBackend()
        service = ProjectDaemonService(
            server=server,
            reconcile_all=lambda: reconcile_startup(
                store, enable_scheduler=lambda: None
            ),
            flush_safe_outboxes=flush_pending_outboxes,
            load_scheduler_facts=lambda: scheduler_facts_from_store(
                store, tmux_backend=daemon_tmux_backend
            ),
            apply_transition=lambda decision: effects.apply(decision),
            permission_waiter_changed=publish_live_permission_waiter,
            permission_confirmation_cleanup=lambda record: (
                _cleanup_permission_confirmation_controller(
                    store,
                    record,
                    now=datetime.now(timezone.utc),
                    commit_and_flush=commit_and_flush,
                )
            ),
        )
        def transport_for(attempt: dict[str, object]):
            return _daemon_worker_transport_for(
                store=store,
                service=service,
                root=root,
                attempt=attempt,
            )

        coordinator = DaemonWorkerCoordinator(
            service=service,
            store=store,
            transport_for=transport_for,
            refresh_recovery=refresh_recovery_authority,
        )
        effects = DaemonTransitionEffects(
            store,
            launch_attempt=coordinator.launch,
            start_worker=DaemonTmuxWorkerStarter(store, daemon_tmux_backend),
            refresh_recovery=refresh_recovery_authority,
        )
        await service.start()
        status.update({
            "mode": "daemon_status", "state": "ready", "health": "healthy",
            "client_count": 0,
            "controller_present": _controller_lease_is_active(store.load()),
            "idle_exit_pending": False, "blockers": [],
            "active_mission_count": 0, "active_worker_count": 0,
            "pending_approval_count": 0, "pending_permission_count": 0,
            "pending_reply_count": 0, "pending_recovery_decision_count": 0,
            "pending_decision_count": 0, "ambiguous_decision_count": 0,
            "outbox_count": 0, "recovery_active": False,
            "safe_shutdown_active": False, "atomic_write_active": False,
        })
        now = utc_now()
        created_at = now
        store.record_daemon_state({
            "instance_id": ownership.instance_id,
            "project_root_hash": ownership.project_root_hash,
            "start_nonce_hash": ownership.start_nonce_hash,
            "state": "ready", "created_at": now, "updated_at": now,
        }, expected_project_root_hash=ownership.project_root_hash)
        idle_since: float | None = None
        current_state = "ready"
        last_activity_generation = server.activity_generation
        while not stop_event.is_set():
            await service.tick()
            # A queued RPC mutation resolves its server-side Future from tick().
            # Yield once so a queued RPC mutation can write its response before
            # a durably committed stop request closes the server.
            await asyncio.sleep(0)
            activity_generation = server.activity_generation
            if activity_generation != last_activity_generation:
                idle_since = None
                last_activity_generation = activity_generation
            status["controller_present"] = refresh_controller(
                datetime.now(timezone.utc)
            )
            keepalive = _daemon_keepalive_view(
                store.load(), other_client_count=server.connection_count
            )
            status.update(keepalive)
            reasons = daemon_keepalive_reasons(keepalive)
            nonclient_reasons = tuple(
                reason for reason in reasons if reason != "clients_connected"
            )
            if nonclient_reasons:
                idle_since = None
                desired_state = "busy"
            elif server.connection_count:
                idle_since = None
                desired_state = "ready"
            elif idle_since is None:
                idle_since = loop.time()
                desired_state = "idle_grace"
            else:
                desired_state = "idle_grace"
            if desired_state != current_state:
                status["state"] = desired_state
                status["idle_exit_pending"] = desired_state == "idle_grace"
                store.record_daemon_state({
                    "instance_id": ownership.instance_id,
                    "project_root_hash": ownership.project_root_hash,
                    "start_nonce_hash": ownership.start_nonce_hash,
                    "state": desired_state, "created_at": created_at,
                    "updated_at": utc_now(),
                }, expected_project_root_hash=ownership.project_root_hash)
                current_state = desired_state
            if idle_since is not None and loop.time() - idle_since >= config.daemon.idle_grace_seconds:
                break
            await service.wait_for_work(timeout_seconds=0.1)
        return 0
    finally:
        close_error: BaseException | None = None
        try:
            if service is not None:
                await service.close()
            elif server is not None:
                await server.close()
        except BaseException as exc:
            close_error = exc
        if created_at is not None:
            stopped_at = utc_now()
            with contextlib.suppress(Exception):
                store.record_daemon_state({
                    "instance_id": ownership.instance_id,
                    "project_root_hash": ownership.project_root_hash,
                    "start_nonce_hash": ownership.start_nonce_hash,
                    "state": "stopped", "created_at": created_at,
                    "updated_at": stopped_at,
                }, expected_project_root_hash=ownership.project_root_hash)
        cleanup_error: BaseException | None = None
        try:
            cleanup_daemon_endpoint(ownership)
        except BaseException as exc:
            cleanup_error = exc
        if close_error is not None:
            raise close_error
        if cleanup_error is not None:
            raise cleanup_error


def _run_daemon_event_loop(
    operation: Any,
    *,
    shutdown_grace_seconds: float = 5.0,
) -> Any:
    """Run the daemon process loop without unbounded asyncio teardown."""
    loop = asyncio.new_event_loop()
    asyncio.set_event_loop(loop)
    main_task = loop.create_task(operation)
    try:
        return loop.run_until_complete(main_task)
    finally:
        pending = {task for task in asyncio.all_tasks(loop) if not task.done()}
        for task in pending:
            task.cancel()
        if pending:
            done, _ = loop.run_until_complete(
                asyncio.wait(pending, timeout=shutdown_grace_seconds)
            )
            for task in done:
                if not task.cancelled():
                    task.exception()
        remaining = {task for task in asyncio.all_tasks(loop) if not task.done()}
        if remaining:
            print(
                "daemon shutdown incomplete: "
                f"pending_task_count={len(remaining)}",
                file=sys.stderr,
            )
            for task in remaining:
                # The bounded diagnostic above replaces asyncio's noisy,
                # potentially sensitive pending-task repr at process teardown.
                task._log_destroy_pending = False
        asyncio.set_event_loop(None)
        loop.close()


def daemon_serve_command(args: argparse.Namespace) -> int:
    root = Path(args.project).expanduser().resolve()
    try:
        config = load_config(root)
        store = StateStore(root)
        install_bounded_daemon_stdio_from_env(root)
        return _run_daemon_event_loop(_serve_daemon(root, config, store))
    except Exception as exc:
        print(f"daemon serve failed: {type(exc).__name__}", file=sys.stderr)
        return 1


