def skills_catalog_command(args: argparse.Namespace) -> int:
    config, store, exit_code = _load_project_or_error()
    if config is None or store is None:
        return exit_code
    source_dir = Path(args.source)
    try:
        catalog = browse_skill_source(source_dir)
    except FileNotFoundError:
        print(f"skill source not found: {source_dir}", file=sys.stderr)
        return 1
    project = _project_skill_hashes(config)
    items: list[dict[str, object]] = []
    for snapshot in catalog:
        item = snapshot.summary()
        status = _catalog_import_status(snapshot, project)
        preview_command = f"agentdeck skills import-preview --path {snapshot.path}"
        import_command = f"agentdeck skills import --path {snapshot.path}"
        item["import_status"] = status
        item["import_preview_command"] = preview_command
        item["import_command"] = import_command
        item["controls"] = list(item.get("controls", [])) + [
            _control(kind="import_preview", label="Preview import", command=preview_command, safety="inspect"),
            _control(kind="import", label="Import skill", command=import_command, safety="explicit_user"),
        ]
        items.append(item)
    _print_json({
        "ok": True,
        "mode": "skills_catalog",
        "source": str(source_dir),
        "source_allowlisted": _source_is_allowlisted(source_dir, config),
        "skill_count": len(items),
        "imported_count": sum(1 for item in items if item["import_status"] != "not_imported"),
        "controls": [
            _control(kind="import", label="Import skill",
                     command="agentdeck skills import --path <SKILL.md>",
                     safety="explicit_user", enabled=False, blocker="requires SKILL.md path"),
        ],
        "items": items,
    })
    return 0


def _allowed_skill_sources(config) -> list[str]:
    skills = getattr(config, "skills", None) or {}
    sources = skills.get("allowed_sources", []) if isinstance(skills, dict) else []
    return [str(src) for src in sources]


def _source_is_allowlisted(source_dir: Path, config) -> bool:
    """Non-enforcing marker: True when source_dir equals or sits under a configured allowed source."""
    try:
        resolved = Path(source_dir).resolve()
    except OSError:
        return False
    for allowed in _allowed_skill_sources(config):
        try:
            allowed_resolved = Path(allowed).resolve()
        except OSError:
            continue
        if resolved == allowed_resolved or resolved.is_relative_to(allowed_resolved):
            return True
    return False


def _project_skill_hashes(config) -> dict[str, str]:
    """Map of project-imported skill name -> content_hash for import_status compares."""
    return {
        skill.name: skill.content_hash
        for skill in discover_skills(Path(config.root))
        if skill.source == "project"
    }


def _catalog_import_status(snapshot, project: dict[str, str]) -> str:
    if snapshot.name in project:
        return "imported_identical" if project[snapshot.name] == snapshot.content_hash else "imported_differs"
    return "not_imported"


def _skills_catalog_card(config) -> dict[str, object]:
    """Read-only overview of configured skill sources ([skills] allowed_sources).

    No file copy, no state write, no event, no provider, no tmux.
    """
    project = _project_skill_hashes(config)
    sources: list[dict[str, object]] = []
    total_skill_count = 0
    imported_total = 0
    for path in _allowed_skill_sources(config):
        source_dir = Path(path)
        catalog_command = f"agentdeck skills catalog --source {path}"
        exists = source_dir.exists() and source_dir.is_dir()
        skill_count = 0
        imported_count = 0
        if exists:
            try:
                catalog = browse_skill_source(source_dir)
            except FileNotFoundError:
                catalog = []
                exists = False
            for snapshot in catalog:
                skill_count += 1
                if _catalog_import_status(snapshot, project) != "not_imported":
                    imported_count += 1
        sources.append({
            "path": str(path),
            "exists": exists,
            "skill_count": skill_count,
            "imported_count": imported_count,
            "catalog_command": catalog_command,
        })
        total_skill_count += skill_count
        imported_total += imported_count
    return {
        "mode": "skills_catalog",
        "source_count": len(sources),
        "total_skill_count": total_skill_count,
        "imported_count": imported_total,
        "sources": sources,
    }


