def _find_skill_suggestion(store: StateStore, suggestion_id: str) -> dict[str, object] | None:
    suggestions = store.load().get("skill_suggestions", [])
    if not isinstance(suggestions, list):
        return None
    for suggestion in suggestions:
        if isinstance(suggestion, dict) and suggestion.get("suggestion_id") == suggestion_id:
            return suggestion
    return None


def _skill_title(name: str) -> str:
    words = [word for word in re.split(r"[-_.\\s]+", name) if word]
    return " ".join(word.capitalize() for word in words) if words else "Skill"


def _skill_draft_content(suggestion: dict[str, object]) -> str:
    name = str(suggestion.get("name") or "suggested-skill")
    summary = str(suggestion.get("summary") or "")
    rationale = str(suggestion.get("rationale") or "")
    lines = [
        "---",
        f"name: {name}",
        f"description: {summary}",
        "required_tools:",
        "risk: inspect",
        "---",
        f"# {_skill_title(name)}",
        "",
        summary,
        "",
        "## Rationale",
        "",
        rationale,
        "",
        "## Provenance",
        "",
        f"- source: {suggestion.get('source') or ''}",
    ]
    if suggestion.get("agent_id"):
        lines.append(f"- agent_id: {suggestion['agent_id']}")
    if suggestion.get("trace_id"):
        lines.append(f"- trace_id: {suggestion['trace_id']}")
    return "\n".join(lines) + "\n"


def skills_draft_preview_command(args: argparse.Namespace) -> int:
    _config, store, exit_code = _load_project_or_error()
    if store is None:
        return exit_code
    suggestion = _find_skill_suggestion(store, args.suggestion_id)
    if suggestion is None:
        print(f"unknown skill suggestion: {args.suggestion_id}", file=sys.stderr)
        return 1
    target = str(suggestion.get("draft_path") or f".agentdeck/skills/{suggestion.get('name')}/SKILL.md")
    target_path = store.root / target
    proposed_content = _skill_draft_content(suggestion)
    create_command = f"agentdeck skills create --suggestion-id {args.suggestion_id} --confirm"
    _print_json(
        {
            "ok": True,
            "mode": "skill_draft_preview",
            "suggestion_id": args.suggestion_id,
            "suggestion": suggestion,
            "name": suggestion.get("name"),
            "target_path": target,
            "would_create": not target_path.exists(),
            "would_overwrite": target_path.exists(),
            "source": suggestion.get("source"),
            "agent_id": suggestion.get("agent_id"),
            "trace_id": suggestion.get("trace_id"),
            "proposed_content": proposed_content,
            "proposed_content_hash": "sha256:" + hashlib.sha256(proposed_content.encode("utf-8")).hexdigest(),
            "create_command": create_command,
            "controls": [
                _control(
                    kind="create_skill",
                    label="Create skill",
                    command=create_command,
                    safety="explicit_user",
                    enabled=True,
                    blocker=None,
                ),
                _control(
                    kind="list_suggestions",
                    label="List skill suggestions",
                    command="agentdeck skills suggestions",
                    safety="inspect",
                ),
            ],
        }
    )
    return 0


def _skill_create_preview_card(store: StateStore, suggestion_id: str) -> dict[str, object]:
    suggestion = _find_skill_suggestion(store, suggestion_id)
    if suggestion is None:
        raise KeyError(suggestion_id)
    target = str(suggestion.get("draft_path") or f".agentdeck/skills/{suggestion.get('name')}/SKILL.md")
    target_path = store.root / target
    proposed_content = _skill_draft_content(suggestion)
    draft_preview_command = f"agentdeck skills draft-preview --suggestion-id {suggestion_id}"
    create_command = f"agentdeck skills create --suggestion-id {suggestion_id} --confirm"
    pending = suggestion.get("status") == "pending"
    return {
        "mode": "skill_create_preview",
        "suggestion_id": suggestion_id,
        "suggestion": suggestion,
        "name": suggestion.get("name"),
        "target_path": target,
        "would_create": not target_path.exists(),
        "would_overwrite": target_path.exists(),
        "source": suggestion.get("source"),
        "agent_id": suggestion.get("agent_id"),
        "trace_id": suggestion.get("trace_id"),
        "proposed_content": proposed_content,
        "proposed_content_hash": "sha256:" + hashlib.sha256(proposed_content.encode("utf-8")).hexdigest(),
        "draft_preview_command": draft_preview_command,
        "create_command": create_command,
        "controls": [
            _control(
                kind="create_skill",
                label="Create skill",
                command=create_command,
                safety="explicit_user",
                enabled=pending,
                blocker=None if pending else "skill suggestion is not pending",
            ),
            _control(
                kind="draft_preview",
                label="Preview skill draft",
                command=draft_preview_command,
                safety="inspect",
            ),
            _control(
                kind="list_suggestions",
                label="List skill suggestions",
                command="agentdeck skills suggestions",
                safety="inspect",
            ),
        ],
    }


def _mark_skill_suggestion_created(
    store: StateStore,
    suggestion_id: str,
    *,
    created_skill_path: str,
    created_content_hash: str,
) -> dict[str, object]:
    state = store.load()
    suggestions = state.get("skill_suggestions", [])
    if not isinstance(suggestions, list):
        raise KeyError(suggestion_id)
    for suggestion in suggestions:
        if not isinstance(suggestion, dict) or suggestion.get("suggestion_id") != suggestion_id:
            continue
        if suggestion.get("status") != "pending":
            raise ValueError(f"skill suggestion is not pending: {suggestion_id}")
        suggestion["status"] = "created"
        suggestion["created_skill_path"] = created_skill_path
        suggestion["created_content_hash"] = created_content_hash
        suggestion["created_at"] = utc_now()
        store.save(state)
        return suggestion
    raise KeyError(suggestion_id)


def skills_create_command(args: argparse.Namespace) -> int:
    _config, store, exit_code = _load_project_or_error()
    if store is None:
        return exit_code
    if not args.confirm:
        print("skills create requires --confirm", file=sys.stderr)
        return 1
    suggestion = _find_skill_suggestion(store, args.suggestion_id)
    if suggestion is None:
        print(f"unknown skill suggestion: {args.suggestion_id}", file=sys.stderr)
        return 1
    if suggestion.get("status") != "pending":
        print(f"skill suggestion is not pending: {args.suggestion_id}", file=sys.stderr)
        return 1
    name = str(suggestion.get("name") or "")
    if not re.fullmatch(r"[A-Za-z0-9._-]+", name):
        print(f"invalid skill name: {name}", file=sys.stderr)
        return 1
    target = str(suggestion.get("draft_path") or f".agentdeck/skills/{name}/SKILL.md")
    target_path = store.root / target
    proposed_content = _skill_draft_content(suggestion)
    content_hash = "sha256:" + hashlib.sha256(proposed_content.encode("utf-8")).hexdigest()
    overwritten = target_path.exists()
    target_path.parent.mkdir(parents=True, exist_ok=True)
    target_path.write_text(proposed_content, encoding="utf-8")
    created = _mark_skill_suggestion_created(
        store,
        args.suggestion_id,
        created_skill_path=target,
        created_content_hash=content_hash,
    )
    store.append_event(
        EventRecord.create(
            "skill_created",
            {
                "suggestion_id": args.suggestion_id,
                "name": name,
                "path": target,
                "content_hash": content_hash,
                "source": suggestion.get("source"),
                "agent_id": suggestion.get("agent_id"),
                "trace_id": suggestion.get("trace_id"),
            },
        )
    )
    show_command = f"agentdeck skills show --name {name}"
    load_command = f"agentdeck skills load --name {name}"
    _print_json(
        {
            "ok": True,
            "mode": "skill_created",
            "suggestion_id": args.suggestion_id,
            "suggestion": created,
            "name": name,
            "path": target,
            "overwritten": overwritten,
            "content_hash": content_hash,
            "show_command": show_command,
            "load_command": load_command,
            "controls": [
                _control(kind="show", label="Show skill", command=show_command, safety="inspect"),
                _control(kind="load", label="Load skill", command=load_command, safety="explicit_user"),
            ],
        }
    )
    return 0


