def agent_send_command(args: argparse.Namespace) -> int:
    config, store, exit_code = _load_project_or_error()
    if config is None or store is None:
        return exit_code
    binding, exit_code = _running_binding_or_error(store, args.agent)
    if binding is None:
        return exit_code
    pane_id = str(binding["pane_id"])
    TmuxBackend().send_input(config.runtime, pane_id, args.text)
    store.append_event(
        EventRecord.create(
            "agent_input_sent",
            {
                "agent_id": args.agent,
                "pane_id": pane_id,
                "text_length": len(args.text),
            },
        )
    )
    _print_json({"ok": True, "agent_id": args.agent, "pane_id": pane_id})
    return 0


def agent_refresh_command(_args: argparse.Namespace) -> int:
    config, store, exit_code = _load_project_or_error()
    if config is None or store is None:
        return exit_code
    backend = TmuxBackend()
    agents = []
    stale_count = 0
    running_count = 0
    for agent in config.agents:
        binding = store.agent_binding(agent.agent_id) or {}
        previous_status = str(binding.get("status", "configured"))
        pane_id = binding.get("pane_id")
        pane_exists = None
        status = previous_status
        changed = False
        if pane_id and previous_status == "running":
            pane_exists = backend.pane_exists(config.runtime, str(pane_id))
            if pane_exists:
                running_count += 1
            else:
                stale_count += 1
                status = "stale"
                changed = True
                store.mark_agent_stale(agent.agent_id)
                store.append_event(
                    EventRecord.create(
                        "agent_runtime_stale",
                        {
                            "agent_id": agent.agent_id,
                            "pane_id": pane_id,
                            "previous_status": previous_status,
                        },
                    )
                )
        agents.append(
            {
                "agent_id": agent.agent_id,
                "previous_status": previous_status,
                "status": status,
                "pane_id": pane_id,
                "pane_exists": pane_exists,
                "changed": changed,
            }
        )
    _print_json({"ok": True, "agents": agents, "stale_count": stale_count, "running_count": running_count})
    return 0


def agent_stop_command(args: argparse.Namespace) -> int:
    config, store, exit_code = _load_project_or_error()
    if config is None or store is None:
        return exit_code
    binding, exit_code = _running_binding_or_error(store, args.agent)
    if binding is None:
        return exit_code
    pane_id = str(binding["pane_id"])
    TmuxBackend().kill_pane(config.runtime, pane_id)
    store.mark_agent_stopped(args.agent)
    store.append_event(
        EventRecord.create(
            "agent_stopped",
            {
                "agent_id": args.agent,
                "pane_id": pane_id,
            },
        )
    )
    _print_json({"ok": True, "agent_id": args.agent, "pane_id": pane_id, "status": "stopped"})
    return 0


def agent_release_command(args: argparse.Namespace) -> int:
    config, store, exit_code = _load_project_or_error()
    if config is None or store is None:
        return exit_code
    if _agent_by_id(config, args.agent) is None:
        print(f"unknown agent: {args.agent}", file=sys.stderr)
        return 1
    if not args.confirm:
        print("agent release requires --confirm", file=sys.stderr)
        return 1
    state = store.load()
    open_jobs = [
        job
        for job in state.get("jobs", [])
        if job.get("agent_id") == args.agent and job.get("status") != "completed"
    ]
    inbox_state = state.get("inbox", {})
    agent_inbox = inbox_state.get(args.agent, []) if isinstance(inbox_state, dict) else []
    pending_inbox = [
        item
        for item in agent_inbox
        if isinstance(item, dict) and item.get("status") == "pending"
    ]
    if open_jobs or pending_inbox:
        print(
            f"agent has unresolved work: {args.agent} "
            f"(open jobs: {len(open_jobs)}, pending inbox: {len(pending_inbox)})",
            file=sys.stderr,
        )
        return 1
    binding = store.agent_binding(args.agent)
    pane_id = str(binding["pane_id"]) if binding and binding.get("pane_id") else None
    if pane_id and binding.get("status") == "running":
        TmuxBackend().kill_pane(config.runtime, pane_id)
    store.mark_agent_released(args.agent)
    dirty_worktrees: list[dict[str, object]] = []
    for message in _worktree_messages(state):
        if message.get("to_agent") != args.agent:
            continue
        item = _worktree_item(config, state, message)
        if item["exists"] and not item["abandoned"] and (item["dirty"] or not item["merged"]):
            dirty_worktrees.append(
                {
                    "message_id": item["message_id"],
                    "branch": item["branch"],
                    "path": item["path"],
                }
            )
    store.append_event(
        EventRecord.create(
            "agent_released",
            {
                "agent_id": args.agent,
                "pane_id": pane_id,
                "dirty_worktree_count": len(dirty_worktrees),
            },
        )
    )
    _print_json(
        {
            "ok": True,
            "mode": "agent_released",
            "agent_id": args.agent,
            "pane_id": pane_id,
            "status": "released",
            "dirty_worktrees": dirty_worktrees,
        }
    )
    return 0


