def _reply_file_path(root: str | Path, message_id: str) -> Path:
    return Path(root) / ".agentdeck" / "replies" / f"{message_id}.reply.txt"


def _approval_is_rework_step(store: StateStore, approval: dict[str, object]) -> bool:
    """该审批指向的 plan step 是否为迭代对的 rework 成员(单一来源判定
    `rework_step_numbers`;非迭代 step 与 re-review step 一律 False)。"""
    plan_id = approval.get("plan_id")
    if not plan_id:
        return False
    plan = next(
        (
            item
            for item in store.load().get("plans", [])
            if isinstance(item, dict) and item.get("plan_id") == plan_id
        ),
        None,
    )
    body = (plan or {}).get("plan")
    steps = body.get("steps", []) if isinstance(body, dict) else []
    return approval.get("step") in rework_step_numbers(steps)


def _plan_base_worktree_branch(store: StateStore, plan_id: object, step: object) -> str | None:
    """Latest earlier-step worktree branch of the same plan (decision D).

    Lets a review-step worktree check out the implementing step's branch so the
    reviewer can run the real artifact without touching the coder's directory.

    A review-group member skips its own siblings: every member reviews the same
    finished implementation. Since the DAG guard fans a group out inside one
    wave, member 1's brand-new branch would otherwise be the newest earlier step
    when member 2's base is computed moments later -- which both leaks member 1's
    review into member 2's tree (`any_fail_blocks` aggregation is only meaningful
    over independent judgements) and, once a digest is bound to that base, makes
    member 1's own commit read as the reviewed code drifting. Plans without
    `[review].reviewers` carry no group markers, so this is the old behaviour
    byte for byte."""
    if not plan_id:
        return None
    try:
        current_step = int(step or 0)
    except (TypeError, ValueError):
        return None
    groups = review_group_numbers(_plan_body_steps(store, str(plan_id)))
    current_group = groups.get(current_step)
    siblings = (
        {number for number, group in groups.items() if group == current_group}
        if current_group is not None
        else set()
    )
    state = store.load()
    messages_by_id = {
        str(message.get("message_id")): message
        for message in state.get("messages", [])
        if isinstance(message, dict)
    }
    best: tuple[int, str] | None = None
    for approval in state.get("approvals", []):
        if not isinstance(approval, dict) or approval.get("plan_id") != plan_id:
            continue
        try:
            approval_step = int(approval.get("step") or 0)
        except (TypeError, ValueError):
            continue
        if approval_step >= current_step or approval_step in siblings:
            continue
        message = messages_by_id.get(str(approval.get("message_id")))
        branch = (message or {}).get("worktree_branch")
        if branch and (best is None or approval_step > best[0]):
            best = (approval_step, str(branch))
    return best[1] if best else None


def _resolve_git_commit(root: object, ref: str | None) -> str | None:
    """`git rev-parse <ref>` in the project root, or None when it cannot be read.

    None means "could not resolve", never "unchanged". Callers must keep those
    two apart -- collapsing them is how a gate ends up reporting that something
    was verified when it was only unreadable.
    """
    if not ref:
        return None
    done = subprocess.run(
        ["git", "rev-parse", str(ref)],
        cwd=str(root),
        capture_output=True,
        text=True,
    )
    if done.returncode != 0:
        return None
    return done.stdout.strip() or None


def _create_task_worktree(
    config: ProjectConfig, agent: AgentSpec, message_id: str, base_branch: str | None = None
) -> tuple[dict[str, str] | None, str | None]:
    """Create a per-task git worktree for a worktree-mode agent.

    Returns (info, skip_reason): info={"path","branch"} on success; when the
    agent is worktree-mode but creation is not possible, info is None and
    skip_reason explains the auditable degradation. Shared-mode agents get
    (None, None) with no event expected."""
    if agent.workspace_mode != "worktree":
        return None, None
    probe = subprocess.run(
        ["git", "rev-parse", "--git-dir"],
        cwd=config.root,
        capture_output=True,
        text=True,
    )
    if probe.returncode != 0:
        return None, "not a real git repository"
    branch = f"agentdeck/{agent.agent_id}/{message_id}"
    path = Path(config.root) / ".agentdeck" / "worktrees" / agent.agent_id / message_id
    path.parent.mkdir(parents=True, exist_ok=True)
    add_command = ["git", "worktree", "add", "-b", branch, str(path)]
    if base_branch:
        add_command.append(base_branch)
    created = subprocess.run(
        add_command,
        cwd=config.root,
        capture_output=True,
        text=True,
    )
    if created.returncode != 0:
        detail = " ".join((created.stderr or created.stdout or "").split())[:200]
        return None, f"git worktree add failed: {detail}"
    return {"path": str(path), "branch": branch}, None


def delegation_grant_command(args: argparse.Namespace) -> int:
    config, store, exit_code = _load_project_or_error()
    if config is None or store is None:
        return exit_code
    if not args.confirm:
        print("delegation grant requires --confirm", file=sys.stderr)
        return 1
    prefix = args.prefix.strip() if args.prefix is not None else None
    mcp_server = args.mcp_server.strip() if args.mcp_server is not None else None
    mcp_tool = args.mcp_tool.strip() if args.mcp_tool is not None else None
    exact_command = (
        args.exact_command.strip() if args.exact_command is not None else None
    )
    wants_prefix = args.prefix is not None
    wants_mcp = args.mcp_server is not None or args.mcp_tool is not None
    wants_exact = args.exact_command is not None
    if sum((wants_prefix, wants_mcp, wants_exact)) != 1:
        print(
            "delegation grant requires exactly one of --prefix, --exact-command "
            "or --mcp-server/--mcp-tool",
            file=sys.stderr,
        )
        return 1
    if wants_prefix and not prefix:
        print("delegation prefix must not be empty", file=sys.stderr)
        return 1
    if wants_exact and not exact_command:
        # 空值永远匹配不到屏上框，委托会在 walk-away 期间静默失效——
        # 与 MCP 字符集校验同一条理由，grant 时即拒绝零写。
        print("delegation exact command must not be empty", file=sys.stderr)
        return 1
    if wants_mcp and (not mcp_server or not mcp_tool):
        print(
            "mcp delegation requires non-empty --mcp-server and --mcp-tool",
            file=sys.stderr,
        )
        return 1
    known_agents = {agent.agent_id for agent in config.agents}
    if args.agent not in known_agents:
        print(f"unknown agent: {args.agent}", file=sys.stderr)
        return 1
    if wants_mcp:
        # box 提取器字符集是 [A-Za-z0-9_-]+：越界值永远匹配不到屏上框，
        # 委托会在 walk-away 期间静默失效——grant 时即拒绝零写。
        for label, value in (("--mcp-server", mcp_server), ("--mcp-tool", mcp_tool)):
            if not re.fullmatch(r"[A-Za-z0-9_\-]+", value or ""):
                print(
                    f"{label} must match [A-Za-z0-9_-]+ (the box extractor charset); got: {value}",
                    file=sys.stderr,
                )
                return 1
    try:
        record = store.grant_delegation(
            args.agent,
            prefix,
            mcp_server=mcp_server,
            mcp_tool=mcp_tool,
            exact_command=exact_command,
        )
    except ValueError as exc:
        print(str(exc), file=sys.stderr)
        return 1
    store.append_event(
        EventRecord.create(
            "delegation_granted",
            {
                "delegation_id": record["delegation_id"],
                "agent_id": record["agent_id"],
                "prefix": record["prefix"],
                "exact_command": record["exact_command"],
                "kind": record["kind"],
                "mcp_server": record["mcp_server"],
                "mcp_tool": record["mcp_tool"],
            },
        )
    )
    _print_json({"ok": True, "mode": "delegation_granted", **record})
    return 0


def _delegation_list_items(store: StateStore) -> list[dict[str, object]]:
    """`delegation list` 的数据源单一来源;其它只读面复用它,绝不另查一遍。"""
    return [
        {
            **item,
            "kind": item.get("kind") or "command_prefix",
            "mcp_server": item.get("mcp_server"),
            "mcp_tool": item.get("mcp_tool"),
            "active": not item.get("revoked_at"),
        }
        for item in store.load().get("delegations", [])
        if isinstance(item, dict)
    ]


