# 空态退出码:没有门可预览不是崩溃,但也绝不是成功——固定 1,让脚本可判。
_GATE_PREVIEW_NOTHING_TO_PREVIEW = 1


def _gate_preview_from_host_record() -> tuple[dict[str, object] | None, int]:
    """缺省来源:走开段的宿主记录。**零 pane 读取**——连 tmux 都不实例化。"""
    record = read_host_record(project_root())
    if record is None:
        print(
            "no run-loop host record at .agentdeck/run-loop-host/host.json",
            file=sys.stderr,
        )
        print(
            "  a foreground run-loop --follow never writes one; preview its box with: "
            "agentdeck delegation gate-preview --agent <agent_id>",
            file=sys.stderr,
        )
        return None, _GATE_PREVIEW_NOTHING_TO_PREVIEW
    gate = record.get("human_gate")
    if not isinstance(gate, dict) or not gate.get("agent_id"):
        print(
            "no human gate in the run-loop host record "
            f"(stopped_reason={record.get('stopped_reason')})",
            file=sys.stderr,
        )
        return None, _GATE_PREVIEW_NOTHING_TO_PREVIEW
    return gate, 0


def _gate_preview_from_agent_scan(agent_id: str) -> tuple[dict[str, object] | None, int]:
    """`--agent` 来源:一次只读实时框扫描。

    复用既有 `agent boxes` 命令核心(仓库既有的 `_run_reused_command` 纪律),
    绝不复制它的框解析逻辑,也绝不新增第二个 pane 读取面。`--follow` 不写
    宿主记录,它的用户只能走这条路,所以这条必须有。
    """
    exit_code, box = _run_reused_command(
        agent_boxes_command, argparse.Namespace(agent=agent_id)
    )
    if exit_code != 0 or not isinstance(box, dict):
        return None, exit_code or 1
    if not box.get("box_present"):
        print(f"no authorization box detected for agent: {agent_id}", file=sys.stderr)
        return None, _GATE_PREVIEW_NOTHING_TO_PREVIEW
    if box.get("delegated"):
        # 已被覆盖的框不需要再 grant 一次;此时唯一缺的是那一次显式放行。
        print(
            "this box is already covered by an active delegation: "
            f"{box.get('delegation_id')}",
            file=sys.stderr,
        )
        print(f"  release it once with: {box.get('release_command')}", file=sys.stderr)
        return None, _GATE_PREVIEW_NOTHING_TO_PREVIEW
    return {field: box.get(field) for field in HUMAN_GATE_FIELDS} | {
        "agent_id": agent_id
    }, 0


def delegation_gate_preview_command(args: argparse.Namespace) -> int:
    """把一道停住走开段的授权框摊开成"grant 什么 → 再放行一次"——**纯只读**。

    它不写 state、不追加事件、不 grant、不 release、不调 provider、不发送任何
    tmux 输入。**绝不推荐**任何一条前缀:同一道框不同前缀的授权宽度差着数量级,
    该由谁承担风险,谁就该自己挑那一条。
    """
    config, store, exit_code = _load_project_or_error()
    if config is None or store is None:
        return exit_code
    if args.agent:
        gate, exit_code = _gate_preview_from_agent_scan(args.agent)
        source = "agent_scan"
    else:
        gate, exit_code = _gate_preview_from_host_record()
        source = "host_record"
    if gate is None:
        return exit_code
    payload = derive_gate_preview(
        agent_id=str(gate.get("agent_id")),
        box_kind=gate.get("box_kind"),
        command=gate.get("command"),
        mcp_server=gate.get("mcp_server"),
        mcp_tool=gate.get("mcp_tool"),
        waiting_hint=gate.get("waiting_hint"),
        source=source,
    )
    validation = validate_delegation_gate_preview_contract(payload)
    if not validation["ok"]:
        print("delegation gate-preview contract validation failed", file=sys.stderr)
        for error in validation["errors"]:
            print(f"- {error}", file=sys.stderr)
        return 1
    if args.json:
        _print_json(payload)
    else:
        print(render_gate_preview(payload))
    return 0


def storage_shadow_enable_command(args: argparse.Namespace) -> int:
    config, store, exit_code = _load_project_or_error()
    if config is None or store is None:
        return exit_code
    if not args.confirm:
        print("storage shadow-enable requires --confirm", file=sys.stderr)
        return 1
    from agentdeck.storage import file_safety as storage_file_safety
    from agentdeck.storage import schema as storage_schema
    from agentdeck.storage import shadow as storage_shadow

    database = storage_shadow.shadow_database_path(config.root)
    if database.exists():
        print("shadow database already exists; rm it first to re-enable", file=sys.stderr)
        return 1
    storage_file_safety.create_private_file(database)
    connection = storage_shadow.open_shadow_connection(database)
    try:
        storage_schema.apply_schema_v1(connection)
        if not storage_schema.verify_schema_v1(connection):
            connection.close()
            database.unlink()
            print("shadow schema fingerprint mismatch; database removed", file=sys.stderr)
            return 1
        connection.execute(
            "INSERT OR REPLACE INTO meta(key, value) VALUES ('authority_state', ?)",
            (storage_shadow.AUTHORITY_QUARANTINED,),
        )
        connection.commit()
    finally:
        connection.close()
    # 立即做一次全量镜像，让 status 从启用起就有可比对内容。
    storage_shadow.mirror_if_enabled(config.root, store.load())
    store.append_event(
        EventRecord.create(
            "storage_shadow_enabled",
            {
                "database": str(database),
                "schema_version": storage_schema.SCHEMA_VERSION,
                "fingerprint": storage_schema.EXPECTED_SCHEMA_V1_FINGERPRINT,
            },
        )
    )
    _print_json(
        {
            "ok": True,
            "mode": "storage_shadow_enabled",
            "database": str(database),
            "authority_state": storage_shadow.AUTHORITY_QUARANTINED,
            "schema_version": storage_schema.SCHEMA_VERSION,
            "fingerprint": storage_schema.EXPECTED_SCHEMA_V1_FINGERPRINT,
            "rollback_command": f"rm {database}",
        }
    )
    return 0


def storage_shadow_status_command(_args: argparse.Namespace) -> int:
    config, store, exit_code = _load_project_or_error()
    if config is None or store is None:
        return exit_code
    from agentdeck.storage import schema as storage_schema
    from agentdeck.storage import shadow as storage_shadow

    database = storage_shadow.shadow_database_path(config.root)
    events_export_mode = storage_shadow.events_export_mode(config.root)
    payload: dict[str, object] = {
        "ok": True,
        "mode": "storage_shadow_status",
        "database": str(database),
        "enabled": False,
        "events_authority": storage_shadow.events_authority(config.root),
        "events_export_mode": events_export_mode,
        "enable_command": "agentdeck storage shadow-enable --confirm",
    }
    if events_export_mode == storage_shadow.EVENTS_EXPORT_ON_DEMAND:
        # 5d 硬边界：按需导出下 events.jsonl 滞后于权威表，`rm state.db`
        # 不再无损——必须显著标注。
        payload["events_export_warning"] = (
            "events export mode is on_demand: events.jsonl lags the "
            "authoritative table, so `rm state.db` is not lossless; run "
            "`agentdeck storage events-export --confirm` or "
            "`agentdeck storage events-rollback --confirm` first"
        )
    if database.is_file():
        connection = storage_shadow.open_shadow_connection(database)
        try:
            meta = dict(connection.execute("SELECT key, value FROM meta"))
            counts = {
                str(row[0]): int(row[1])
                for row in connection.execute(
                    "SELECT collection, COUNT(*) FROM records GROUP BY collection"
                )
            }
            singleton_count = int(
                connection.execute("SELECT COUNT(*) FROM singletons").fetchone()[0]
            )
            fingerprint_ok = storage_schema.verify_schema_v1(connection)
        finally:
            connection.close()
        payload.update(
            {
                "enabled": meta.get("authority_state") == storage_shadow.AUTHORITY_QUARANTINED,
                "authority_state": meta.get("authority_state"),
                "schema_version": meta.get("schema_version"),
                "fingerprint_ok": fingerprint_ok,
                "mirrored_at": meta.get("mirrored_at"),
                "record_counts": counts,
                "singleton_count": singleton_count,
                "rollback_command": f"rm {database}",
            }
        )
    _print_json(payload)
    return 0


def storage_shadow_diff_command(_args: argparse.Namespace) -> int:
    config, store, exit_code = _load_project_or_error()
    if config is None or store is None:
        return exit_code
    from agentdeck.storage import shadow as storage_shadow

    database = storage_shadow.shadow_database_path(config.root)
    payload: dict[str, object] = {
        "ok": True,
        "mode": "storage_shadow_diff",
        "database": str(database),
        "enabled": False,
        "in_sync": None,
        "mismatched_collections": [],
        "enable_command": "agentdeck storage shadow-enable --confirm",
    }
    if not database.is_file():
        _print_json(payload)
        return 0
    connection = storage_shadow.open_shadow_connection(database)
    try:
        enabled = storage_shadow._shadow_enabled(connection)
        payload["enabled"] = enabled
        if not enabled:
            _print_json(payload)
            return 0
        mirrored = storage_shadow.reconstruct_state(connection)
    finally:
        connection.close()
    authoritative = store.load()
    mismatched = sorted(
        key
        for key in set(authoritative) | set(mirrored)
        if authoritative.get(key) != mirrored.get(key)
    )
    payload["in_sync"] = not mismatched
    payload["mismatched_collections"] = mismatched
    payload["collection_count"] = len(authoritative)
    _print_json(payload)
    return 0 if not mismatched else 1


def ui_serve_command(args: argparse.Namespace) -> int:
    config, store, exit_code = _load_project_or_error()
    if config is None or store is None:
        return exit_code
    from agentdeck import ui as agentdeck_ui

    server = agentdeck_ui.build_server(Path(config.root), args.port)
    host, port = server.server_address[:2]
    print(f"AgentDeck read-only UI: http://{host}:{port}/ (Ctrl-C to stop)", file=sys.stderr)
    try:
        server.serve_forever()
    except KeyboardInterrupt:
        pass
    finally:
        server.server_close()
    return 0


