def worktree_prune_command(args: argparse.Namespace) -> int:
    config, store, exit_code = _load_project_or_error()
    if config is None or store is None:
        return exit_code
    if not args.confirm:
        print("worktree prune requires --confirm", file=sys.stderr)
        return 1
    state = store.load()
    merged_ids = {str(item) for item in state.get("merged_worktrees", [])}
    removed: list[dict[str, object]] = []
    skipped: list[dict[str, object]] = []
    for message in _worktree_messages(state):
        item = _worktree_item(config, state, message)
        if not item["exists"]:
            continue
        message_id = str(item["message_id"])
        branch = str(item["branch"])
        path = str(item["path"])
        # 零 commit 分支的 git merged 是平凡真（分支尖==主干尖），只有显式
        # merge 记录或账本已收到 reply 才把 git-merged 当真正的可清理信号。
        merge_settled = message_id in merged_ids or (
            bool(item["merged"]) and not item["in_flight"]
        )
        if item["abandoned"]:
            removal = subprocess.run(
                ["git", "worktree", "remove", "--force", path],
                cwd=config.root,
                capture_output=True,
                text=True,
            )
            branch_delete_flag = "-D"
        elif merge_settled and not item["dirty"]:
            removal = subprocess.run(
                ["git", "worktree", "remove", path],
                cwd=config.root,
                capture_output=True,
                text=True,
            )
            branch_delete_flag = "-d"
        else:
            if item["dirty"]:
                reason = "dirty and not abandoned"
            elif item["in_flight"]:
                reason = "task still in flight"
            else:
                reason = "branch not merged"
            skipped.append({"message_id": message_id, "branch": branch, "reason": reason})
            continue
        if removal.returncode != 0:
            detail = " ".join((removal.stderr or removal.stdout or "").split())[:200]
            skipped.append({"message_id": message_id, "branch": branch, "reason": f"git worktree remove failed: {detail}"})
            continue
        subprocess.run(
            ["git", "branch", branch_delete_flag, branch],
            cwd=config.root,
            capture_output=True,
            text=True,
        )
        removed.append({"message_id": message_id, "branch": branch, "path": path})
        store.append_event(
            EventRecord.create(
                "worktree_pruned",
                {
                    "message_id": message_id,
                    "branch": branch,
                    "abandoned": bool(item["abandoned"]),
                },
            )
        )
    _print_json(
        {
            "ok": True,
            "mode": "worktree_prune",
            "removed": removed,
            "removed_count": len(removed),
            "skipped": skipped,
            "skipped_count": len(skipped),
        }
    )
    return 0


def _record_worktree_provenance(
    store: StateStore,
    agent: AgentSpec,
    message_id: str,
    worktree_info: dict[str, str] | None,
    skip_reason: str | None,
) -> None:
    if worktree_info is not None:
        store.append_event(
            EventRecord.create(
                "worktree_created",
                {
                    "agent_id": agent.agent_id,
                    "message_id": message_id,
                    "branch": worktree_info["branch"],
                    "path": worktree_info["path"],
                },
            )
        )
    elif skip_reason is not None:
        store.append_event(
            EventRecord.create(
                "worktree_skipped",
                {
                    "agent_id": agent.agent_id,
                    "message_id": message_id,
                    "reason": skip_reason,
                },
            )
        )


def dispatch_command(args: argparse.Namespace) -> int:
    config, store, exit_code = _load_project_or_error()
    if config is None or store is None:
        return exit_code
    agent = _agent_by_id(config, args.agent)
    if agent is None:
        print(f"unknown agent: {args.agent}", file=sys.stderr)
        return 1
    binding, exit_code = _running_binding_or_error(store, args.agent)
    if binding is None:
        return exit_code
    pane_id = str(binding["pane_id"])
    skill_loads = _loaded_skill_records_for_agent(store, agent.agent_id)
    prompt_skill_context = _dispatch_prompt_skill_context(skill_loads)
    message_id = new_id("msg")
    worktree_info, worktree_skip = _create_task_worktree(config, agent, message_id)
    reply_file = _reply_file_path(config.root, message_id)
    reply_file.parent.mkdir(parents=True, exist_ok=True)
    prompt = build_dispatch_prompt(
        agent,
        args.task,
        skill_loads=skill_loads,
        reply_file=str(reply_file),
        worktree_path=(worktree_info or {}).get("path"),
        worktree_branch=(worktree_info or {}).get("branch"),
        artifacts_dir=str(Path(config.root) / ".agentdeck" / "artifacts") if worktree_info else None,
    )
    records = store.create_dispatch_records(
        args.from_agent,
        agent.agent_id,
        args.task,
        prompt,
        pane_id,
        prompt_skill_context=prompt_skill_context,
        message_id=message_id,
        worktree_path=(worktree_info or {}).get("path"),
        worktree_branch=(worktree_info or {}).get("branch"),
    )
    message = records["message"]
    _record_worktree_provenance(store, agent, message_id, worktree_info, worktree_skip)
    TmuxBackend().send_input(config.runtime, pane_id, prompt)
    store.append_event(
        EventRecord.create(
            "task_dispatched",
            {
                "message_id": message["message_id"],
                "to_agent": agent.agent_id,
                "pane_id": pane_id,
                "task_length": len(args.task),
            },
        )
    )
    _print_json(
        {
            "ok": True,
            "message_id": message["message_id"],
            "agent_id": agent.agent_id,
            "pane_id": pane_id,
            "trace_command": _trace_command(message["message_id"]),
        }
    )
    return 0


def inbox_command(args: argparse.Namespace) -> int:
    config, store, exit_code = _load_project_or_error()
    if config is None or store is None:
        return exit_code
    if not _is_known_mailbox_agent(config, args.agent):
        print(f"unknown agent: {args.agent}", file=sys.stderr)
        return 1
    payload = _inbox_queue_payload(args.agent, store)
    validation = validate_inbox_contract(payload)
    if not validation["ok"]:
        print("Inbox contract validation failed", file=sys.stderr)
        for error in validation["errors"]:
            print(f"- {error}", file=sys.stderr)
        return 1
    _print_json(payload)
    return 0


def _inbox_queue_payload(agent_id: str, store: StateStore) -> dict[str, object]:
    raw_items = store.inbox_items(agent_id)
    head = next((item for item in raw_items if item.get("status") == "pending"), None)
    head_inbox_id = head.get("inbox_id") if isinstance(head, dict) else None
    items = [_inbox_queue_item(agent_id, item, head_inbox_id) for item in raw_items]
    return {"agent_id": agent_id, "count": len(items), "head_inbox_id": head_inbox_id, "items": items}


def _inbox_queue_item(agent_id: str, item: dict[str, object], head_inbox_id: object) -> dict[str, object]:
    inbox_id = item.get("inbox_id")
    is_head = inbox_id == head_inbox_id
    can_ack = item.get("status") == "pending" and is_head
    return {
        "inbox_id": inbox_id,
        "event_type": item.get("event_type"),
        "message_id": item.get("message_id"),
        "attempt_id": item.get("attempt_id"),
        "job_id": item.get("job_id"),
        "reply_id": item.get("reply_id"),
        "from_actor": item.get("from_actor"),
        "from_agent": item.get("from_agent"),
        "to_agent": item.get("to_agent"),
        "task": item.get("task"),
        "status": item.get("status"),
        "created_at": item.get("created_at"),
        "preview_command": _trace_command(inbox_id),
        "controls": _inbox_item_controls(agent_id, str(inbox_id), can_ack),
        "trace_command": _trace_command(inbox_id),
        "ack_command": f"agentdeck ack --agent {agent_id} --inbox-id {inbox_id}",
        "is_head": is_head,
        "can_ack": can_ack,
        "ack_blocker": None if can_ack else "inbox item is not head",
    }


def reply_command(args: argparse.Namespace) -> int:
    config, store, exit_code = _load_project_or_error()
    if config is None or store is None:
        return exit_code
    if _agent_by_id(config, args.agent) is None:
        print(f"unknown agent: {args.agent}", file=sys.stderr)
        return 1
    try:
        reply = store.record_reply(args.agent, args.message_id, args.text)
    except KeyError:
        print(f"unknown message: {args.message_id}", file=sys.stderr)
        return 1
    store.append_event(
        EventRecord.create(
            "task_replied",
            {
                "reply_id": reply["reply_id"],
                "message_id": reply["message_id"],
                "from_agent": args.agent,
                "artifact_count": len(reply.get("artifacts", [])) if isinstance(reply.get("artifacts"), list) else 0,
            },
        )
    )
    payload = _reply_success_payload(reply, store)
    if payload is None:
        return 1
    _print_json(payload)
    return 0


def _reply_success_payload(reply: dict[str, object], store: StateStore) -> dict[str, object] | None:
    payload = {
        "ok": True,
        "reply_id": reply["reply_id"],
        "message_id": reply["message_id"],
        "from_agent": reply["from_agent"],
        "trace_command": _trace_command(reply["reply_id"]),
    }
    to_actor = reply.get("to_actor")
    if to_actor and to_actor != "user":
        # The reply, its artifacts and this mailbox entry are already on the
        # books. The card is a presentational extra on top of that, so a card
        # that will not render may only degrade the response -- reporting
        # failure here invites a re-run, and re-running `agentdeck reply`
        # records a SECOND reply for the same message. Same rule, and the same
        # helper, as `approval dispatch`.
        inbox_card, inbox_blocker, inbox_errors = _dispatch_inbox_card(
            str(to_actor), store
        )
        payload["inbox_card"] = inbox_card
        payload["blocker"] = inbox_blocker
        if inbox_blocker is not None:
            store.append_event(
                EventRecord.create(
                    "reply_inbox_card_unrenderable",
                    {
                        "reply_id": reply.get("reply_id"),
                        "message_id": reply.get("message_id"),
                        "agent_id": str(to_actor),
                        "errors": inbox_errors,
                    },
                )
            )
    artifacts = reply.get("artifacts")
    if isinstance(artifacts, list) and artifacts:
        payload["artifacts"] = store.artifact_summaries(artifacts)
    return payload


def _strip_tui_reply_decoration(line: str) -> str:
    # 真实 agent TUI（如 codex）会把回复首行渲染成 "• status: ..."。
    return line.strip().lstrip("•").strip()


def _extract_structured_reply(output: str) -> str | None:
    lines = output.splitlines()
    start_index = None
    for index, line in enumerate(lines):
        if _strip_tui_reply_decoration(line).startswith("status:"):
            start_index = index
    if start_index is None:
        return None
    tail = lines[start_index:]
    tail[0] = _strip_tui_reply_decoration(tail[0])
    return "\n".join(tail).strip()


def _capture_reply_from_file_channel(
    config: ProjectConfig, store: StateStore, agent_id: str, message_id: str
) -> dict[str, object] | None:
    """File-channel-only reply ingestion for the run loop.

    Reads the explicit worker reply file; never touches tmux panes."""
    reply_file = _reply_file_path(config.root, message_id)
    if not reply_file.is_file():
        return None
    try:
        file_text = reply_file.read_text(encoding="utf-8")
    except OSError:
        return None
    text = _extract_structured_reply(file_text)
    if text is None:
        return None
    try:
        reply = store.record_reply(agent_id, message_id, text)
    except KeyError:
        return None
    store.append_event(
        EventRecord.create(
            "reply_captured",
            {
                "reply_id": reply["reply_id"],
                "message_id": reply["message_id"],
                "from_agent": agent_id,
                "pane_id": None,
                "captured_from": "file",
                "captured_lines": len(text.splitlines()),
                "artifact_count": len(reply.get("artifacts", [])) if isinstance(reply.get("artifacts"), list) else 0,
            },
        )
    )
    return {
        "message_id": str(reply["message_id"]),
        "reply_id": str(reply["reply_id"]),
        "agent_id": agent_id,
        "captured_from": "file",
        "trace_command": _trace_command(reply["reply_id"]),
    }


def capture_reply_command(args: argparse.Namespace) -> int:
    config, store, exit_code = _load_project_or_error()
    if config is None or store is None:
        return exit_code
    if _agent_by_id(config, args.agent) is None:
        print(f"unknown agent: {args.agent}", file=sys.stderr)
        return 1
    binding, exit_code = _running_binding_or_error(store, args.agent)
    if binding is None:
        return exit_code
    pane_id = str(binding["pane_id"])
    text = None
    captured_from = "pane"
    reply_file = _reply_file_path(config.root, args.message_id)
    if reply_file.is_file():
        try:
            file_text = reply_file.read_text(encoding="utf-8")
        except OSError:
            file_text = ""
        text = _extract_structured_reply(file_text)
        if text is not None:
            captured_from = "file"
    if text is None:
        output = TmuxBackend().capture_output(config.runtime, pane_id, args.lines)
        text = _extract_structured_reply(output)
    if text is None:
        print(f"no structured reply found for agent: {args.agent}", file=sys.stderr)
        return 1
    try:
        reply = store.record_reply(args.agent, args.message_id, text)
    except KeyError:
        print(f"unknown message: {args.message_id}", file=sys.stderr)
        return 1
    store.append_event(
        EventRecord.create(
            "reply_captured",
            {
                "reply_id": reply["reply_id"],
                "message_id": reply["message_id"],
                "from_agent": args.agent,
                "pane_id": pane_id,
                "captured_from": captured_from,
                "captured_lines": len(text.splitlines()),
                "artifact_count": len(reply.get("artifacts", [])) if isinstance(reply.get("artifacts"), list) else 0,
            },
        )
    )
    payload = _reply_success_payload(reply, store)
    if payload is None:
        return 1
    payload["pane_id"] = pane_id
    payload["captured_from"] = captured_from
    payload["captured_lines"] = len(text.splitlines())
    _print_json(payload)
    return 0


