def _record_leader_provider_failure(
    store: StateStore,
    mode: str,
    provider: str,
    model: str | None,
    task: str,
    error: Exception,
    stage: str | None = None,
) -> None:
    record = store.record_leader_error(mode, provider, model, task, str(error))
    payload: dict[str, object] = {
        "error_id": record["error_id"],
        "mode": mode,
        "provider": provider,
        "model": model,
        "task_length": len(task),
        "error": str(error),
    }
    if stage is not None:
        payload["stage"] = stage
    # CLI-backed provider 的诊断:退出码是进程事实,failure_reason 是闭合
    # 枚举码(解析→分类→丢弃原文);二者都不含 provider 输出片段。
    exit_code = getattr(error, "exit_code", None)
    if isinstance(exit_code, int) and not isinstance(exit_code, bool):
        payload["exit_code"] = exit_code
    failure_reason = getattr(error, "failure_reason", None)
    if isinstance(failure_reason, str) and failure_reason:
        payload["failure_reason"] = failure_reason
    store.append_event(EventRecord.create("leader_provider_failed", payload))


def _plan_requested_verdict(store: StateStore, plan_id: str) -> bool:
    """该 plan 是否真的派发过 review step——即注入过验收标准、**期待**判定。

    信号与 G5 注入条件同源:dispatch 时 `base_branch` 非 None 且该步不是
    rework 步(`worktree_base_branch` 落在 message 上)。从没要求过判定的
    plan(无 worktree、纯实现 plan)不受零 verdict 收紧影响。
    """
    state = store.load()
    rework_steps = rework_step_numbers(
        next(
            (
                (item.get("plan") or {}).get("steps") or []
                for item in state.get("plans", [])
                if isinstance(item, dict) and item.get("plan_id") == plan_id
            ),
            [],
        )
    )
    base_branch_messages = {
        str(message.get("message_id"))
        for message in state.get("messages", [])
        if isinstance(message, dict) and message.get("worktree_base_branch")
    }
    for approval in state.get("approvals", []):
        if not isinstance(approval, dict) or approval.get("plan_id") != plan_id:
            continue
        if approval.get("step") in rework_steps:
            continue
        if str(approval.get("message_id")) in base_branch_messages:
            return True
    return False


def _resolve_git_branch_exists(root: object, branch: str | None) -> bool | None:
    """该本地分支还在不在;无法判断时返回 None,**绝不返回 False**。

    与 `_resolve_git_commit` 同一条纪律:"查不了"和"不存在"是两件事。把前者
    塌成后者,就会把一次 git 探测失败报成一次越界合并——而越界合并是要给人
    看的告警,假警报会很快让人不再看它。
    """
    if not branch:
        return None
    done = subprocess.run(
        ["git", "rev-parse", "--verify", "--quiet", f"refs/heads/{branch}"],
        cwd=str(root),
        capture_output=True,
        text=True,
    )
    return done.returncode == 0


def _plan_branch_custody(
    config: ProjectConfig, store: StateStore, plan_id: str
) -> dict[str, object]:
    """这条 plan 建过的每条任务分支,现在处于什么状态。

    Round 1 finding ①:reviewer 自行 `git merge` 并清理分支,绕过了当天上午
    才建好的合并闸,而账本毫不知情。AgentDeck 拦不住一个有 shell 的 worker
    敲 git,但它至少可以**发现**自己的记述已经不成立了。

    与 `_plan_review_bindings` 同构:git 解析只在这里,store 一次都不 shell
    out;全程只读,不写 state、不追加事件、不阻断任何合并或派发。
    """
    state = store.load()
    settled = {
        str(message_id)
        for key in ("merged_worktrees", "abandoned_worktrees")
        for message_id in state.get(key, [])
    }
    messages_by_id = {
        str(message.get("message_id")): message
        for message in state.get("messages", [])
        if isinstance(message, dict)
    }
    git_available = _resolve_git_commit(config.root, "HEAD") is not None
    items: list[dict[str, object]] = []
    for approval in state.get("approvals", []):
        if not isinstance(approval, dict) or approval.get("plan_id") != plan_id:
            continue
        message_id = str(approval.get("message_id") or "")
        message = messages_by_id.get(message_id)
        if message is None or not message.get("worktree_branch"):
            continue
        branch = str(message.get("worktree_branch"))
        verdict = classify_branch_custody(
            worktree_branch=branch,
            settled_by_agentdeck=message_id in settled,
            branch_exists=(
                _resolve_git_branch_exists(config.root, branch)
                if git_available
                else None
            ),
        )
        items.append({"message_id": message_id, **verdict})
    return {
        "count": len(items),
        "items": items,
        # 只点名需要人看的那一档;其余三档都不是告警。
        "gone_unrecorded_count": sum(
            1 for item in items if item["state"] == "gone_unrecorded"
        ),
    }


def _plan_review_bindings(
    config: ProjectConfig, store: StateStore, plan_id: str
) -> dict[str, object]:
    """Every verdict-bearing step of this plan, bound to the commit it reviewed.

    Git resolution lives here, never in the store -- every other store method
    touches nothing but its own JSON/SQLite. Read-only: it runs `git rev-parse`
    and nothing else, writes no state and appends no event.
    """
    state = store.load()
    replies_with_verdict = {
        str(reply.get("message_id"))
        for reply in state.get("replies", [])
        if isinstance(reply, dict) and reply.get("verdict")
    }
    messages_by_id = {
        str(message.get("message_id")): message
        for message in state.get("messages", [])
        if isinstance(message, dict)
    }
    git_available = _resolve_git_commit(config.root, "HEAD") is not None
    resolved: dict[str, str | None] = {}
    items: list[dict[str, object]] = []
    for approval in state.get("approvals", []):
        if not isinstance(approval, dict) or approval.get("plan_id") != plan_id:
            continue
        message_id = str(approval.get("message_id") or "")
        if message_id not in replies_with_verdict:
            continue
        message = messages_by_id.get(message_id)
        if message is None or not message.get("worktree_base_branch"):
            continue
        branch = str(message["worktree_base_branch"])
        if branch not in resolved:
            resolved[branch] = _resolve_git_commit(config.root, branch)
        items.append({
            "message_id": message_id,
            "agent_id": approval.get("agent_id"),
            "step": approval.get("step"),
            "base_branch": branch,
            "base_commit": message.get("worktree_base_commit"),
            "resolved_commit": resolved[branch],
        })
    items.sort(key=lambda item: int(item.get("step") or 0))
    return summarize_review_bindings(items, git_available=git_available)


def _stale_review_merge_blocker(
    config: ProjectConfig, store: StateStore, plan_id: str
) -> str | None:
    """Withhold the AUTOMATIC merge when the reviewed code has moved.

    Explicit `agentdeck worktree merge-plan --confirm` is never gated -- the
    same rule the G5 verdict gate follows.
    """
    blocker = _plan_review_bindings(config, store, plan_id).get("blocker")
    return str(blocker) if blocker else None


def _verdict_merge_blocker(store: StateStore, plan_id: str) -> str | None:
    summary = store.plan_verdict_summary(plan_id)
    if summary is None:
        # 零 verdict 收紧(2026-08-01 user 拍板):要过 verdict 就必须有
        # verdict——派发过 review step(注入过验收标准)却一份有效判定都
        # 没拿到时,委托型自动合并必须扣住;人类 `worktree merge-plan
        # --confirm` 永不受 gate。从未要求判定的 plan 行为不变。
        if _plan_requested_verdict(store, plan_id):
            return "no review verdict recorded for a dispatched review step; auto-merge withheld"
        return None
    overall = summary.get("overall")
    group = summary.get("group") or {}
    if group.get("complete") is False:
        # 组没审完就不自动合并:一人 verdict 无效/缺失时,整组判定不完整,
        # 委托型自动合并必须扣住(人类 `worktree merge-plan --confirm`
        # 永不受 gate)。
        reported = sum(1 for m in group.get("members") or [] if m.get("overall"))
        return (
            f"review group incomplete ({reported}/{group.get('size')} members "
            "reported); auto-merge withheld"
        )
    if overall == "pass":
        return None
    return f"review verdict overall is {overall}; auto-merge withheld"


def _review_group_reviewers(config: ProjectConfig) -> tuple[tuple[str, str], ...]:
    """(agent_id, role) 纯数据;未配置或成员未知时返回空元组(不展开)。"""
    roles = {agent.agent_id: agent.role for agent in config.agents}
    pairs = [
        (agent_id, roles[agent_id])
        for agent_id in config.review.reviewers
        if agent_id in roles
    ]
    return tuple(pairs)


def _review_binding(config: ProjectConfig) -> dict[str, object]:
    """`[review]` 段 → `append_review_iteration` 的纯数据 binding。

    空 binding(缺省配置)让写入路径退化为今天逐字节相同的克隆行为;
    它只描述"复审步该派给谁",不是执行授权——追加的 step 照常生成
    pending 审批走既有 allowlist/预算/顺序守卫。"""
    roles = {agent.agent_id: agent.role for agent in config.agents}
    name = config.review.round_reviewer
    return {
        "round_reviewer": (name, roles[name]) if name in roles else None,
        "reviewers": _review_group_reviewers(config),
    }


def _generate_leader_plan(
    config: ProjectConfig,
    store: StateStore,
    *,
    task: str,
    provider_override: str | None,
    model_override: str | None,
    skill_context: dict[str, object],
    source: str,
) -> tuple[dict[str, object], str, str, dict[str, object] | None]:
    """Generate one plan via the configured Leader.

    Explicit --provider/--model overrides always use the existing
    single-stage path; the G2 planner/orchestrator split runs only when
    configured and not overridden. Provider failures are audited here
    (split failures carry stage=planner|orchestrator) and re-raised.
    """
    provider_name = _leader_provider_name(config, provider_override)
    model_label = _leader_model_label(config, model_override)
    use_split = (
        leader_split_enabled(config.leader)
        and provider_override is None
        and model_override is None
    )
    if not use_split:
        provider = leader_provider(provider_name)
        orchestrator = LeaderOrchestrator(config, provider)
        try:
            plan = orchestrator.plan(task, model_label, skill_context=skill_context)
        except RuntimeError as exc:
            _record_leader_provider_failure(
                store, source, provider.name, model_label, task, exc
            )
            raise
        reviewers = _review_group_reviewers(config)
        return expand_review_group(plan, reviewers), provider.name, model_label, None
    planner_provider_name, planner_model = resolved_planner_backend(config.leader)
    orchestrator_provider_name, orchestrator_model = resolved_orchestrator_backend(
        config.leader
    )
    planner_provider = leader_provider(planner_provider_name)
    orchestrator_provider = leader_provider(orchestrator_provider_name)
    try:
        result = run_split_planning(
            config,
            task,
            planner_provider=planner_provider,
            orchestrator_provider=orchestrator_provider,
            planner_model=planner_model,
            orchestrator_model=orchestrator_model,
            skill_context=skill_context,
        )
    except SplitPlanningError as exc:
        if exc.stage == "planner":
            failed_provider, failed_model = planner_provider_name, planner_model
        else:
            failed_provider, failed_model = orchestrator_provider_name, orchestrator_model
        _record_leader_provider_failure(
            store, source, failed_provider, failed_model, task, exc, stage=exc.stage
        )
        raise
    split_provenance: dict[str, object] = {
        "planner_backend": result.planner_backend,
        "orchestrator_backend": result.orchestrator_backend,
        "planner_brief": result.planner_brief,
    }
    reviewers = _review_group_reviewers(config)
    return (
        expand_review_group(result.plan, reviewers),
        orchestrator_provider_name,
        orchestrator_model,
        split_provenance,
    )


def _leader_provider_name(config: ProjectConfig, requested_provider: str | None) -> str:
    if requested_provider:
        return requested_provider
    return config.leader.provider


def _leader_model_label(config: ProjectConfig, requested_model: str | None) -> str:
    if requested_model:
        return requested_model
    return config.leader.model


def _leader_skill_context(config: ProjectConfig, store: StateStore) -> dict[str, object]:
    project_view = _project_view_payload_or_error(config, store)
    if project_view is None:
        raise RuntimeError("ProjectView contract validation failed")
    skills = project_view.get("skills")
    if isinstance(skills, dict):
        return skills
    return {"count": 0, "by_agent": {}, "by_source": {}, "items": []}


def leader_plan_command(args: argparse.Namespace) -> int:
    config, store, exit_code = _load_project_or_error()
    if config is None or store is None:
        return exit_code
    skill_context = _leader_skill_context(config, store)
    try:
        plan, record_provider, record_model, split_provenance = _generate_leader_plan(
            config,
            store,
            task=args.task,
            provider_override=args.provider,
            model_override=args.model,
            skill_context=skill_context,
            source="plan",
        )
    except ValueError as exc:
        print(str(exc), file=sys.stderr)
        return 1
    except RuntimeError as exc:
        print(f"leader provider failed: {exc}", file=sys.stderr)
        return 1
    record = store.record_plan(
        args.task,
        record_provider,
        record_model,
        plan,
        skill_context=skill_context,
        split_provenance=split_provenance,
    )
    store.append_event(
        EventRecord.create(
            "leader_plan_created",
            {
                "plan_id": record["plan_id"],
                "provider": record["provider"],
                "model": record["model"],
                "task_length": len(args.task),
            },
        )
    )
    _print_json(
        {
            "ok": True,
            "plan_id": record["plan_id"],
            "status": record["status"],
            "provider": record["provider"],
            "provider_backend": record["provider_backend"],
            "provider_transport": record["provider_transport"],
            "leader_backend": record["leader_backend"],
            "model": record["model"],
            "dispatch_ready": record["dispatch_ready"],
            "plan": record["plan"],
        }
    )
    return 0


def run_command(args: argparse.Namespace) -> int:
    config, store, exit_code = _load_project_or_error()
    if config is None or store is None:
        return exit_code
    if args.plan_id:
        try:
            payload = _run_progress_payload(store, args.plan_id)
        except KeyError:
            print(f"unknown plan: {args.plan_id}", file=sys.stderr)
            return 1
        validation = validate_run_start_contract(payload)
        if not validation["ok"]:
            print("Run progress contract validation failed", file=sys.stderr)
            for error in validation["errors"]:
                print(f"- {error}", file=sys.stderr)
            return 1
        _print_json(payload)
        return 0
    try:
        payload, _record, _approvals = _create_run_start_payload(
            config,
            store,
            task=args.task,
            provider_override=args.provider,
            model_override=args.model,
            source="run",
        )
    except ValueError as exc:
        print(str(exc), file=sys.stderr)
        return 1
    except RuntimeError as exc:
        print(f"leader provider failed: {exc}", file=sys.stderr)
        return 1
    validation = validate_run_start_contract(payload)
    if not validation["ok"]:
        print("Run start contract validation failed", file=sys.stderr)
        for error in validation["errors"]:
            print(f"- {error}", file=sys.stderr)
        return 1
    _print_json(payload)
    return 0


def _create_run_start_payload(
    config: ProjectConfig,
    store: StateStore,
    *,
    task: str,
    provider_override: str | None,
    model_override: str | None,
    source: str,
) -> tuple[dict[str, object], dict[str, object], list[dict[str, object]]]:
    skill_context = _leader_skill_context(config, store)
    plan, record_provider, record_model, split_provenance = _generate_leader_plan(
        config,
        store,
        task=task,
        provider_override=provider_override,
        model_override=model_override,
        skill_context=skill_context,
        source=source,
    )
    record = store.record_plan(
        task,
        record_provider,
        record_model,
        plan,
        skill_context=skill_context,
        split_provenance=split_provenance,
    )
    approvals = store.create_approvals_from_plan(record["plan_id"])
    store.append_event(
        EventRecord.create(
            "leader_plan_created",
            {
                "plan_id": record["plan_id"],
                "provider": record["provider"],
                "model": record["model"],
                "task_length": len(task),
                "source": source,
            },
        )
    )
    store.append_event(
        EventRecord.create(
            "approvals_created_from_plan",
            {
                "plan_id": record["plan_id"],
                "count": len(approvals),
                "source": source,
            },
        )
    )
    store.append_event(
        EventRecord.create(
            "run_started",
            {
                "plan_id": record["plan_id"],
                "approval_count": len(approvals),
                "task_length": len(task),
                "source": source,
            },
        )
    )
    approval_card = _approval_queue_payload(store, plan_id=record["plan_id"])
    return _run_start_payload(record, approvals, approval_card), record, approvals


def _run_loop_preview_card(store: StateStore, config: ProjectConfig, plan_id: str) -> dict[str, object]:
    autonomous = config.leader.approval_mode == "autonomous"
    command = f"agentdeck run-loop --plan-id {plan_id} --confirm"
    blocker = None if autonomous else "autonomous mode is not enabled"
    enable_command = (
        None if autonomous
        else "agentdeck policy set-mode --mode autonomous --confirm --allow-agent <id> --max-approvals <N>"
    )
    return {
        "mode": "run_loop_preview",
        "plan_id": plan_id,
        "command": command,
        "autonomous_enabled": autonomous,
        "safety": "delegated",
        "requires_explicit_user": True,
        "blocker": blocker,
        "enable_command": enable_command,
        "controls": [
            _control(kind="run_loop", label="Run-loop (autonomous)", command=command,
                     safety="delegated", enabled=autonomous, blocker=blocker),
            _control(kind="inspect", label="Inspect run progress",
                     command=f"agentdeck run --plan-id {plan_id}", safety="inspect"),
        ],
    }


def _run_progress_payload(store: StateStore, plan_id: str) -> dict[str, object]:
    status = store.plan_status(plan_id)
    review = _leader_review_payload(store.leader_review(plan_id))
    approval_card = _approval_queue_payload(store, plan_id=plan_id)
    next_command = review.get("next_command")
    controls = [
        _control(
            kind="plan_status",
            label="Plan status",
            command=f"agentdeck plan status --plan-id {plan_id}",
            safety="inspect",
        ),
        _control(
            kind="review",
            label="Review run",
            command=f"agentdeck leader review --plan-id {plan_id}",
            safety="inspect",
        ),
        _control(
            kind="approval_queue",
            label="Review approval queue",
            command="agentdeck approval list",
            safety="inspect",
        ),
    ]
    if next_command:
        review_next_action = review.get("next_action")
        controls.append(
            _control(
                kind="next",
                label="Next command",
                command=next_command,
                safety="inspect" if review_next_action in {"summarize", "wait_for_approval"} else "explicit_runtime",
            )
        )
    controls.extend(
        [
            _control(kind="continue", label="Continue", command="agentdeck continue", safety="inspect"),
            _control(kind="workbench", label="Open workbench", command="agentdeck workbench", safety="inspect"),
        ]
    )
    return {
        "schema_version": PROJECT_VIEW_SCHEMA_VERSION,
        "ok": True,
        "mode": "run_progress",
        "plan_id": plan_id,
        "task": status.get("task"),
        "status": status.get("status"),
        "provider": status.get("provider"),
        "provider_backend": status.get("provider_backend"),
        "provider_transport": status.get("provider_transport"),
        "leader_backend": status.get("leader_backend")
        or leader_backend_identity(
            str(status.get("provider") or ""),
            str(status.get("model") or ""),
            False,
        ),
        "model": status.get("model"),
        "counts": status.get("counts"),
        "steps": status.get("steps"),
        "acceptance_criteria": review.get("acceptance_criteria"),
        "verdict_summary": review.get("verdict_summary"),
        "review": review,
        "approval_card": approval_card,
        "next_command": next_command,
        "plan_status_command": f"agentdeck plan status --plan-id {plan_id}",
        "review_command": f"agentdeck leader review --plan-id {plan_id}",
        "continue_command": "agentdeck continue",
        "workbench_command": "agentdeck workbench",
        "controls": controls,
        "safety": "approval_gated",
        "requires_explicit_user": True,
    }


def _run_start_payload(
    plan_record: dict[str, object],
    approvals: list[dict[str, object]],
    approval_card: dict[str, object],
) -> dict[str, object]:
    plan_id = str(plan_record["plan_id"])
    pending_approvals = [item for item in approvals if item.get("status") == "pending"]
    first_approval = pending_approvals[0] if pending_approvals else None
    first_approval_id = first_approval.get("approval_id") if isinstance(first_approval, dict) else None
    approve_next_command = (
        f"agentdeck approval approve --approval-id {first_approval_id}" if first_approval_id else None
    )
    review_command = f"agentdeck leader review --plan-id {plan_id}"
    controls = [
        _control(
            kind="preview",
            label="Review approval queue",
            command="agentdeck approval list",
            safety="inspect",
        ),
        _control(
            kind="approve",
            label="Approve next step",
            command=approve_next_command or "agentdeck approval approve --approval-id <approval_id>",
            safety="explicit_runtime",
            enabled=approve_next_command is not None,
            blocker=None if approve_next_command is not None else "no pending approval",
        ),
        _control(kind="review", label="Review run", command=review_command, safety="inspect"),
        _control(kind="continue", label="Continue", command="agentdeck continue", safety="inspect"),
        _control(kind="workbench", label="Open workbench", command="agentdeck workbench", safety="inspect"),
    ]
    return {
        "schema_version": PROJECT_VIEW_SCHEMA_VERSION,
        "ok": True,
        "mode": "run_start",
        "task": plan_record["task"],
        "plan_id": plan_id,
        "provider": plan_record["provider"],
        "provider_backend": plan_record.get("provider_backend")
        or leader_provider_backend(str(plan_record.get("provider") or "")),
        "provider_transport": plan_record.get("provider_transport")
        or leader_provider_transport(str(plan_record.get("provider") or "")),
        "leader_backend": plan_record.get("leader_backend")
        or leader_backend_identity(
            str(plan_record.get("provider") or ""),
            str(plan_record.get("model") or ""),
            bool(plan_record.get("dispatch_ready", False)),
        ),
        "model": plan_record["model"],
        "approval_count": len(approvals),
        "pending_approval_count": len(pending_approvals),
        "plan": plan_record["plan"],
        "approval_card": approval_card,
        "next_command": "agentdeck approval list",
        "approve_next_command": approve_next_command,
        "review_command": review_command,
        "continue_command": "agentdeck continue",
        "workbench_command": "agentdeck workbench",
        "controls": controls,
        "safety": "approval_gated",
        "requires_explicit_user": True,
    }


def leader_review_command(args: argparse.Namespace) -> int:
    config, store, exit_code = _load_project_or_error()
    if config is None or store is None:
        return exit_code
    if _project_view_payload_or_error(config, store) is None:
        return 1
    try:
        review = store.leader_review(args.plan_id)
    except KeyError:
        print(f"unknown plan: {args.plan_id}", file=sys.stderr)
        return 1
    payload = _leader_review_payload(review)
    validation = validate_leader_review_contract(payload)
    if not validation["ok"]:
        print("Leader review contract validation failed", file=sys.stderr)
        for error in validation["errors"]:
            print(f"- {error}", file=sys.stderr)
        return 1
    _print_json(payload)
    return 0


