def _leader_summary_payload(store: StateStore, plan_id: str) -> dict[str, object]:
    plan = store.plan_by_id(plan_id)
    plan_status = store.plan_status(plan_id)
    state = store.load()
    replies_by_message = {reply.get("message_id"): reply for reply in state.get("replies", [])}
    artifacts_by_message: dict[object, list[dict[str, object]]] = {}
    for artifact in state.get("artifacts", []):
        artifacts_by_message.setdefault(artifact.get("message_id"), []).append(artifact)
    steps = []
    reply_count = 0
    artifact_count = 0
    for step in plan_status.get("steps", []):
        if not isinstance(step, dict):
            continue
        message_id = step.get("message_id")
        reply = replies_by_message.get(message_id)
        artifacts = artifacts_by_message.get(message_id, [])
        if reply is not None:
            reply_count += 1
        artifact_count += len(artifacts)
        trace_id = message_id or step.get("job_id") or step.get("approval_id")
        steps.append(
            {
                "step": step.get("step"),
                "agent_id": step.get("agent_id"),
                "role": step.get("role"),
                "task": step.get("task"),
                "approval_id": step.get("approval_id"),
                "message_id": message_id,
                "attempt_id": step.get("attempt_id"),
                "job_id": step.get("job_id"),
                "reply_id": reply.get("reply_id") if isinstance(reply, dict) else None,
                "reply_text": reply.get("text") if isinstance(reply, dict) else None,
                "artifact_count": len(artifacts),
                "artifacts": [_leader_summary_artifact(item) for item in artifacts],
                "trace_command": _trace_command(trace_id) if trace_id else None,
            }
        )
    controls = [
        _control(
            kind="summary",
            label="View summary",
            command=f"agentdeck leader summary --plan-id {plan_id}",
            safety="inspect",
        ),
        _control(
            kind="plan_status",
            label="Plan status",
            command=f"agentdeck plan status --plan-id {plan_id}",
            safety="inspect",
        ),
        _control(
            kind="review",
            label="Review plan",
            command=f"agentdeck leader review --plan-id {plan_id}",
            safety="inspect",
        ),
    ]
    for step in steps:
        if step.get("trace_command"):
            controls.append(
                _control(
                    kind="trace",
                    label="Trace step",
                    command=step.get("trace_command"),
                    safety="inspect",
                )
            )
            break
    return {
        "schema_version": PROJECT_VIEW_SCHEMA_VERSION,
        "plan_id": plan_id,
        "task": plan.get("task"),
        "status": "ready" if reply_count else "waiting",
        "provider": plan.get("provider"),
        "model": plan.get("model"),
        "leader_backend": plan_status.get("leader_backend")
        or leader_backend_identity(
            str(plan.get("provider") or ""),
            str(plan.get("model") or ""),
            bool(plan.get("dispatch_ready", False)),
        ),
        "counts": plan_status.get("counts"),
        "reply_count": reply_count,
        "artifact_count": artifact_count,
        "verdict_summary": store.plan_verdict_summary(plan_id),
        "summary": f"{reply_count} dispatched step has replies; {artifact_count} artifact recorded.",
        "plan_status_command": f"agentdeck plan status --plan-id {plan_id}",
        "review_command": f"agentdeck leader review --plan-id {plan_id}",
        "steps": steps,
        "controls": controls,
    }


def _learning_review_payload(store: StateStore, plan_id: str) -> dict[str, object]:
    summary = _leader_summary_payload(store, plan_id)
    task = str(summary.get("task") or "")
    reply_count = int(summary.get("reply_count") or 0)
    artifact_count = int(summary.get("artifact_count") or 0)
    status = "ready" if reply_count else "waiting"
    skill_name = _learning_review_skill_name(summary)
    skill_summary = f"Review {task or 'a completed AgentDeck run'} as a repeatable workflow."
    skill_rationale = (
        f"Plan {plan_id} produced {reply_count} replies and {artifact_count} artifacts; "
        "capture the reusable review procedure as an explicit skill suggestion."
    )
    memory_summary = (
        f"Plan {plan_id} completed with {reply_count} replies and {artifact_count} artifacts; "
        f"review whether its lessons should become durable project memory."
    )
    memory_rationale = (
        "Learning review is read-only, so durable memory must still go through "
        "memory suggestions, apply-preview, and explicit apply confirmation."
    )
    skill_command = (
        "agentdeck skills suggest "
        f"--name {shlex.quote(skill_name)} "
        f"--summary {shlex.quote(skill_summary)} "
        f"--rationale {shlex.quote(skill_rationale)} "
        f"--source learn-review --agent leader --from-trace {shlex.quote(plan_id)}"
    )
    memory_command = (
        "agentdeck memory suggest "
        f"--summary {shlex.quote(memory_summary)} "
        f"--rationale {shlex.quote(memory_rationale)} "
        f"--source learn-review --agent leader --from-trace {shlex.quote(plan_id)} --scope project"
    )
    controls = [
        _control(
            kind="summary",
            label="View Leader summary",
            command=f"agentdeck leader summary --plan-id {plan_id}",
            safety="inspect",
        ),
        _control(
            kind="suggest_skill",
            label="Queue skill suggestion",
            command=skill_command,
            safety="explicit_user",
            enabled=status == "ready",
            blocker=None if status == "ready" else "no replies available for learning review",
        ),
        _control(
            kind="suggest_memory",
            label="Queue memory suggestion",
            command=memory_command,
            safety="explicit_user",
            enabled=status == "ready",
            blocker=None if status == "ready" else "no replies available for learning review",
        ),
    ]
    return {
        "schema_version": PROJECT_VIEW_SCHEMA_VERSION,
        "ok": True,
        "mode": "learning_review",
        "plan_id": plan_id,
        "task": task,
        "status": status,
        "reply_count": reply_count,
        "artifact_count": artifact_count,
        "summary": (
            "Learning review can queue explicit skill and memory suggestions."
            if status == "ready"
            else "Learning review is waiting for at least one worker reply."
        ),
        "plan_status_command": f"agentdeck plan status --plan-id {plan_id}",
        "summary_command": f"agentdeck leader summary --plan-id {plan_id}",
        "skill_suggestion": {
            "kind": "skill_suggestion",
            "name": skill_name,
            "summary": skill_summary,
            "rationale": skill_rationale,
            "source": "learn-review",
            "agent_id": "leader",
            "trace_id": plan_id,
            "command": skill_command,
        },
        "memory_suggestion": {
            "kind": "memory_suggestion",
            "scope": "project",
            "summary": memory_summary,
            "rationale": memory_rationale,
            "source": "learn-review",
            "agent_id": "leader",
            "trace_id": plan_id,
            "command": memory_command,
        },
        "controls": controls,
    }


def _learning_review_skill_name(summary: dict[str, object]) -> str:
    text_parts = [str(summary.get("task") or "")]
    for step in summary.get("steps", []):
        if isinstance(step, dict):
            text_parts.append(str(step.get("task") or ""))
            for artifact in step.get("artifacts", []):
                if isinstance(artifact, dict):
                    text_parts.append(str(artifact.get("path") or ""))
    combined = " ".join(text_parts).lower()
    if "deploy" in combined:
        return "deployment-review"
    if "incident" in combined:
        return "incident-review"
    tokens = [token for token in re.findall(r"[a-z0-9]+", combined) if token not in {"a", "the", "and", "to"}]
    stem = tokens[0] if tokens else "run"
    return f"{stem}-review"


def _leader_summary_artifact(artifact: dict[str, object]) -> dict[str, object]:
    artifact_id = artifact.get("artifact_id")
    return {
        "artifact_id": artifact_id,
        "path": artifact.get("path"),
        "kind": artifact.get("kind"),
        "status": artifact.get("status"),
        "trace_command": _trace_command(artifact_id) if artifact_id else None,
    }


def _leader_review_payload(review: dict[str, object]) -> dict[str, object]:
    next_command = _leader_review_next_command(review)
    return {
        **review,
        "approval_id": review.get("approval_id"),
        "agent_id": review.get("agent_id"),
        "message_id": review.get("message_id"),
        "replies": review.get("replies", []),
        "next_command": next_command,
        "controls": _leader_review_controls(review, next_command),
    }


def _leader_review_next_command(review: dict[str, object]) -> str | None:
    next_action = review.get("next_action")
    if next_action == "dispatch_approved" and review.get("approval_id"):
        return f"agentdeck approval dispatch --approval-id {review['approval_id']}"
    if next_action == "wait_for_reply" and review.get("agent_id") and review.get("message_id"):
        return f"agentdeck capture-reply --agent {review['agent_id']} --message-id {review['message_id']}"
    if next_action == "summarize" and review.get("plan_id"):
        return f"agentdeck leader summary --plan-id {review['plan_id']}"
    if next_action == "wait_for_approval":
        return "agentdeck approval list"
    return None


def _leader_review_controls(review: dict[str, object], next_command: str | None) -> list[dict[str, object]]:
    controls: list[dict[str, object]] = []
    message_id = review.get("message_id")
    if message_id:
        controls.append(
            _control(
                kind="preview",
                label="Preview message lineage",
                command=_trace_command(message_id),
                safety="inspect",
            )
        )
    if review.get("next_action") == "wait_for_reply":
        controls.append(
            _control(
                kind="capture_reply",
                label="Capture reply",
                command=next_command,
                safety="explicit_runtime",
                enabled=next_command is not None,
                blocker=None if next_command is not None else "capture reply command unavailable",
            )
        )
    elif next_command is not None:
        controls.append(
            _control(
                kind="next",
                label="Next command",
                command=next_command,
                safety="inspect" if review.get("next_action") in {"summarize", "wait_for_approval"} else "explicit_runtime",
            )
        )
    return controls


def leader_next_command(args: argparse.Namespace) -> int:
    config, store, exit_code = _load_project_or_error()
    if config is None or store is None:
        return exit_code
    if _project_view_payload_or_error(config, store) is None:
        return 1
    try:
        action = store.suggest_leader_action(args.plan_id)
    except KeyError as exc:
        print(f"unknown plan: {exc.args[0]}", file=sys.stderr)
        return 1
    store.append_event(
        EventRecord.create(
            "leader_action_suggested",
            {
                "action_id": action["action_id"],
                "kind": action["kind"],
                "plan_id": action["plan_id"],
                "command": action["command"],
            },
        )
    )
    _print_json({"ok": True, **action})
    return 0


def _leader_action_summary(action: dict[str, object], recommended_action_id: object = None) -> dict[str, object]:
    detail_fields = StateStore._leader_action_detail_fields(action)
    return {
        "action_id": action.get("action_id"),
        "kind": action.get("kind"),
        "status": action.get("status"),
        "requires_confirmation": action.get("requires_confirmation"),
        "plan_id": action.get("plan_id"),
        "approval_id": action.get("approval_id"),
        "agent_id": action.get("agent_id"),
        "message_id": action.get("message_id"),
        "command": action.get("command"),
        "reason": action.get("reason"),
        "created_at": action.get("created_at"),
        "can_apply": detail_fields["can_apply"],
        "preview_command": detail_fields["preview_command"],
        "controls": detail_fields["controls"],
        "apply_command": detail_fields["apply_command"],
        "explicit_command": detail_fields["explicit_command"],
        "apply_blocker": detail_fields["apply_blocker"],
        "is_recommended": action.get("action_id") == recommended_action_id,
    }


def leader_actions_command(_args: argparse.Namespace) -> int:
    config, store, exit_code = _load_project_or_error()
    if config is None or store is None:
        return exit_code
    project_view = _project_view_payload_or_error(config, store)
    if project_view is None:
        return 1
    recovery = project_view.get("recovery", {})
    recommended_action = recovery.get("recommended_action") if isinstance(recovery, dict) else None
    recommended_action_id = recommended_action.get("target_id") if isinstance(recommended_action, dict) else None
    actions = [_leader_action_summary(action, recommended_action_id) for action in store.list_leader_actions()]
    payload = {
        "count": len(actions),
        "recommended_action_id": recommended_action_id,
        "actions": actions,
    }
    validation = validate_leader_actions_contract(payload)
    if not validation["ok"]:
        print("Leader actions contract validation failed", file=sys.stderr)
        for error in validation["errors"]:
            print(f"- {error}", file=sys.stderr)
        return 1
    _print_json(payload)
    return 0


def leader_action_command(args: argparse.Namespace) -> int:
    config, store, exit_code = _load_project_or_error()
    if config is None or store is None:
        return exit_code
    project_view = _project_view_payload_or_error(config, store)
    if project_view is None:
        return 1
    try:
        action = store.leader_action_detail(args.action_id)
    except KeyError:
        print(f"unknown leader action: {args.action_id}", file=sys.stderr)
        return 1
    recovery = project_view.get("recovery", {})
    recommended_action = recovery.get("recommended_action") if isinstance(recovery, dict) else None
    matches_recommended_action = (
        isinstance(recommended_action, dict) and recommended_action.get("target_id") == args.action_id
    )
    payload = {
        **action,
        "recovery": recovery,
        "recommended_action": recommended_action,
        "matches_recommended_action": matches_recommended_action,
    }
    validation = validate_leader_action_contract(payload)
    if not validation["ok"]:
        print("Leader action contract validation failed", file=sys.stderr)
        for error in validation["errors"]:
            print(f"- {error}", file=sys.stderr)
        return 1
    _print_json(payload)
    return 0


def leader_apply_action_command(args: argparse.Namespace) -> int:
    config, store, exit_code = _load_project_or_error()
    if config is None or store is None:
        return exit_code
    if _project_view_payload_or_error(config, store) is None:
        return 1
    try:
        applied = store.apply_leader_action(args.action_id)
    except KeyError:
        print(f"unknown leader action: {args.action_id}", file=sys.stderr)
        return 1
    except (PermissionError, ValueError) as exc:
        print(str(exc), file=sys.stderr)
        return 1
    action = applied["action"]
    result = applied["result"]
    store.append_event(
        EventRecord.create(
            "leader_action_applied",
            {
                "action_id": action["action_id"],
                "kind": action["kind"],
                "plan_id": action["plan_id"],
                "result_count": result.get("count"),
            },
        )
    )
    _print_json({"ok": True, **_leader_action_summary(action), "result": result})
    return 0


def _next_command_for_review(review: dict[str, object]) -> str | None:
    action = review.get("next_action")
    if action == "dispatch_approved" and review.get("approval_id"):
        return f"agentdeck approval dispatch --approval-id {review['approval_id']}"
    if action == "wait_for_reply" and review.get("agent_id") and review.get("message_id"):
        return f"agentdeck capture-reply --agent {review['agent_id']} --message-id {review['message_id']}"
    if action == "wait_for_approval" and review.get("plan_id"):
        return f"agentdeck approval create-from-plan --plan-id {review['plan_id']}"
    if action == "summarize" and review.get("plan_id"):
        return f"agentdeck leader summary --plan-id {review['plan_id']}"
    return None


def _chat_apply_action_id(message: str) -> str | None:
    stripped = message.strip()
    lowered = stripped.lower()
    for prefix in ["/apply-action ", "apply action "]:
        if lowered.startswith(prefix):
            return stripped[len(prefix) :].strip()
    for prefix in ["应用 action ", "应用action "]:
        if stripped.startswith(prefix):
            return stripped[len(prefix) :].strip()
    return None


def _is_continue_chat_message(message: str) -> bool:
    normalized = message.strip().lower()
    return normalized in {"继续", "继续吧", "/continue", "continue"}


def _chat_wants_frontdesk(message: str) -> bool:
    normalized = message.strip().lower()
    compact = normalized.replace(" ", "")
    return (
        normalized.startswith("frontdesk")
        or normalized.startswith("/frontdesk")
        or "前台接待" in compact
        or "前台处理" in compact
        or "前台路由" in compact
        or "梳理需求" in compact
        or "澄清需求" in compact
    )


def _frontdesk_goal_from_message(message: str) -> str:
    # Same rule as before, now owned by the pure `agentdeck.frontdesk` module so
    # the card and the classifier can never drift apart.
    return frontdesk_goal(message)


def _frontdesk_candidate_control(candidate: dict[str, object]) -> dict[str, object]:
    """Render one classified route candidate as a GUI-ready control.

    The control reuses the safety level of the command it points at. A command
    that still carries a `<placeholder>` is never actionable, so it ships
    disabled with a blocker; rendering it is surfacing, not authorization.
    """
    command = candidate.get("command")
    has_placeholder = "<" in str(command)
    return {
        "kind": "route",
        "label": candidate.get("label"),
        "command": command,
        "safety": FRONTDESK_ROUTE_SAFETY.get(str(candidate.get("route")), "inspect"),
        "enabled": not has_placeholder,
        "blocker": "requires goal text" if has_placeholder else None,
    }


def _frontdesk_card(message: str) -> dict[str, object]:
    goal = _frontdesk_goal_from_message(message)
    has_goal = bool(goal)
    next_command = (
        f"agentdeck leader plan --task {shlex.quote(goal)}"
        if has_goal
        else 'agentdeck leader chat --message "帮助"'
    )
    candidates = classify_frontdesk(message)
    return {
        "mode": "frontdesk",
        "title": "Frontdesk intake",
        "summary": "Frontdesk routed the request without calling a planning provider.",
        "user_message": message,
        "intake_summary": goal,
        "classification": "planning_candidate" if has_goal else "needs_goal",
        "next_command": next_command,
        "controls": [
            {
                "kind": "inspect",
                "label": "Open Leader help",
                "command": 'agentdeck leader chat --message "帮助"',
                "safety": "inspect",
                "enabled": True,
                "blocker": None,
            },
            {
                "kind": "plan",
                "label": "Create Leader plan",
                "command": next_command if has_goal else None,
                "safety": "plan_only",
                "enabled": has_goal,
                "blocker": None if has_goal else "requires goal text",
            },
            *[_frontdesk_candidate_control(candidate) for candidate in candidates],
        ],
        "candidates": candidates,
        "route": str(candidates[0]["route"]) if candidates else None,
    }


