    stripped = message.strip()
    lowered = stripped.lower()
    if not any(
        token in lowered
        for token in [
            "create skill",
            "skill create",
            "创建 skill",
            "创建skill",
            "创建 技能",
            "创建技能",
            "生成 skill",
            "生成skill",
        ]
    ):
        return None
    match = re.search(r"\bsgs_[A-Za-z0-9_-]+\b", stripped)
    return match.group(0) if match else None


