def _chat_skill_import_preview_path(message: str) -> Path | None:
    text = message.strip()
    lowered = text.lower()
    wants_preview = (
        "import-preview" in lowered
        or ("preview" in lowered and "skill" in lowered and "import" in lowered)
        or ("预览" in text and ("导入" in text or "import" in lowered) and ("skill" in lowered or "技能" in text))
    )
    if not wants_preview:
        return None
    path_match = re.search(r"--path\s+(.+)$", text)
    if path_match:
        return Path(shlex.split(path_match.group(1))[0]).expanduser()
    skill_md_match = re.search(r"((?:/|~/?|\.\.?/)[^\s，,；;]+SKILL\.md)", text, re.IGNORECASE)
    if skill_md_match:
        return Path(skill_md_match.group(1)).expanduser()
    return None


def _chat_skill_load_preview_request(message: str) -> tuple[str, str, str] | None:
    text = message.strip()
    lowered = text.lower()
    wants_preview = (
        ("preview" in lowered and "load" in lowered and "skill" in lowered)
        or ("预览" in text and "加载" in text and ("skill" in lowered or "技能" in text))
    )
    if not wants_preview:
        return None
    chinese_match = re.search(
        r"(?:预览)?加载\s*(?:skill|技能)\s+([A-Za-z0-9._-]+)\s+给\s+([A-Za-z0-9._-]+)\s+用于\s+(.+)$",
        text,
        re.IGNORECASE,
    )
    if chinese_match:
        return (
            chinese_match.group(1),
            chinese_match.group(2),
            chinese_match.group(3).strip(),
        )
    english_match = re.search(
        r"preview\s+load\s+skill\s+([A-Za-z0-9._-]+)\s+for\s+([A-Za-z0-9._-]+)(?:\s+(?:purpose|for-purpose)\s+(.+))?$",
        text,
        re.IGNORECASE,
    )
    if english_match:
        return (
            english_match.group(1),
            english_match.group(2),
            (english_match.group(3) or "").strip(),
        )
    return None


