    delegation_gate_preview.set_defaults(func=delegation_gate_preview_command)

    boxes = subparsers.add_parser("boxes", help="Authorization box automation (delegation-gated)")
    boxes_subparsers = boxes.add_subparsers(dest="boxes_command")
    boxes_watch = boxes_subparsers.add_parser(
        "watch", help="Bounded watch loop that releases delegation-covered authorization boxes (autonomous mode only)"
    )
    boxes_watch.add_argument("--agent", default=None, help="Limit watching to one agent id")
    boxes_watch.add_argument("--iterations", type=int, default=1, help="Bounded number of scan iterations")
    boxes_watch.add_argument("--interval", type=float, default=5.0, help="Seconds between iterations")
    boxes_watch.add_argument("--confirm", action="store_true", help="Explicitly confirm the watch loop")
    boxes_watch.set_defaults(func=boxes_watch_command)

    storage = subparsers.add_parser("storage", help="State storage backend commands (SQLite migration)")
    storage_subparsers = storage.add_subparsers(dest="storage_command")
    storage_shadow_enable = storage_subparsers.add_parser(
        "shadow-enable", help="Create the quarantined SQLite shadow mirror (explicit; JSON stays authoritative)"
    )
    storage_shadow_enable.add_argument("--confirm", action="store_true", help="Explicitly confirm enabling the shadow mirror")
    storage_shadow_enable.set_defaults(func=storage_shadow_enable_command)
    storage_shadow_status = storage_subparsers.add_parser(
        "shadow-status", help="Read-only shadow mirror status"
    )
    storage_shadow_status.set_defaults(func=storage_shadow_status_command)
    storage_shadow_diff = storage_subparsers.add_parser(
        "shadow-diff", help="Read-only comparison of the shadow mirror against the authoritative JSON state"
    )
    storage_shadow_diff.set_defaults(func=storage_shadow_diff_command)
    storage_events_diff = storage_subparsers.add_parser(
        "events-diff", help="Read-only comparison of the shadow events table against the authoritative events.jsonl"
    )
    storage_events_diff.set_defaults(func=storage_events_diff_command)
    storage_events_cutover = storage_subparsers.add_parser(
        "events-cutover",
        help="Explicitly flip events authority from events.jsonl to the shadow events table (SQLite phase 5c)",
    )
    storage_events_cutover.add_argument("--confirm", action="store_true")
    storage_events_cutover.set_defaults(func=storage_events_cutover_command)
    storage_events_rollback = storage_subparsers.add_parser(
        "events-rollback",
        help="Explicitly flip events authority back to events.jsonl after verifying the export is drift-free",
    )
    storage_events_rollback.add_argument("--confirm", action="store_true")
    storage_events_rollback.set_defaults(func=storage_events_rollback_command)
    storage_events_export = storage_subparsers.add_parser(
        "events-export",
        help="Explicitly rebuild events.jsonl from the authoritative events table (sqlite authority only)",
    )
    storage_events_export.add_argument("--confirm", action="store_true")
    storage_events_export.set_defaults(func=storage_events_export_command)
    storage_events_export_mode = storage_subparsers.add_parser(
        "events-export-mode",
        help="Explicitly switch the post-cutover events.jsonl export mode (sync|on_demand)",
    )
    storage_events_export_mode.add_argument(
        "--mode", choices=["sync", "on_demand"], required=True
    )
    storage_events_export_mode.add_argument("--confirm", action="store_true")
    storage_events_export_mode.set_defaults(func=storage_events_export_mode_command)

    ui_parser = subparsers.add_parser("ui", help="Local read-only web shell over the contract surface")
    ui_subparsers = ui_parser.add_subparsers(dest="ui_command")
    ui_serve = ui_subparsers.add_parser(
        "serve", help="Serve the read-only workbench page on 127.0.0.1 (GET only, no mutations)"
    )
    ui_serve.add_argument("--port", type=int, default=8787, help="Port on 127.0.0.1 (default 8787)")
    ui_serve.set_defaults(func=ui_serve_command)

    dispatch = subparsers.add_parser("dispatch", help="Send a role-aware task to a running agent")
    dispatch.add_argument("--from-agent", default="user", help="Actor or agent id that submitted this task")
    dispatch.add_argument("--agent", required=True, help="Agent id from .agentdeck/config.toml")
    dispatch.add_argument("--task", required=True, help="Task text to send with the agent role prompt")
    dispatch.set_defaults(func=dispatch_command)

    inbox = subparsers.add_parser("inbox", help="Show pending inbox items for an agent")
    inbox.add_argument("--agent", required=True, help="Agent id from .agentdeck/config.toml")
    inbox.set_defaults(func=inbox_command)

    reply = subparsers.add_parser("reply", help="Record an agent reply for a dispatched message")
